import "os"

func abcSelectIf(condition bool, yes, no string) string {
	if condition {
		return yes
	}
	return no
}

func abcDefaultString(value, fallback string) string {
	if value == "" {
		return fallback
	}
	return value
}

// abcAtoi matches C atoi's decimal-prefix parsing used by command options.
func abcAtoi(value string) int32 {
	i := 0
	for i < len(value) && (value[i] == ' ' || value[i] == '\t' || value[i] == '\n' || value[i] == '\r' || value[i] == '\f' || value[i] == '\v') {
		i++
	}
	start := i
	if i < len(value) && (value[i] == '+' || value[i] == '-') {
		i++
	}
	digits := i
	for i < len(value) && value[i] >= '0' && value[i] <= '9' {
		i++
	}
	if i == digits {
		return 0
	}
	n, _ := strconv.Atoi(value[start:i])
	return int32(n)
}

// abcTruth32ToWords packs the C truth table's adjacent 32-bit words into the
// native 64-bit words used by Dau_DecTrySets.
func abcTruth32ToWords(truth []uint32) []uint64 {
	words := make([]uint64, (len(truth)+1)/2)
	for i := range words {
		var raw [8]byte
		binary.NativeEndian.PutUint32(raw[:4], truth[2*i])
		if 2*i+1 < len(truth) {
			binary.NativeEndian.PutUint32(raw[4:], truth[2*i+1])
		}
		words[i] = binary.NativeEndian.Uint64(raw[:])
	}
	return words
}

