/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_FrameReplaceCex(pAbc *Abc_Frame_t, ppCex **Abc_Cex_t) {
	state := abcFrameState(pAbc)
	if old, ok := state.Cex().(*Abc_Cex_t); ok {
		Abc_CexFree(old)
	}
	if old, ok := state.CexVec().(*Vec_Ptr_t); ok {
		Vec_PtrFreeFree(old)
	}
	var value any = *ppCex
	state.ReplaceCex(&value)
	*ppCex = nil
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_FrameReplaceCexVec(pAbc *Abc_Frame_t, pvCexVec **Vec_Ptr_t) {
	state := abcFrameState(pAbc)
	if old, ok := state.CexVec().(*Vec_Ptr_t); ok {
		Vec_PtrFreeFree(old)
	}
	if old, ok := state.Cex().(*Abc_Cex_t); ok {
		Abc_CexFree(old)
	}
	var value any = *pvCexVec
	state.ReplaceCexVec(&value)
	*pvCexVec = nil
}

