/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintFanio(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fUseFanio int32
	var fUsePio int32
	var fUseSupp int32
	var fUseCone int32
	var fMffc int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "fiscmvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "fiscmvh") {
		switch c {
		case 'f':
			fUseFanio ^= 1
			break
		case 'i':
			fUsePio ^= 1
			break
		case 's':
			fUseSupp ^= 1
			break
		case 'c':
			fUseCone ^= 1
			break
		case 'm':
			fMffc ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	// print the nodes
	if (fMffc != 0) || !(fVerbose != 0) {
		Abc_NtkPrintFanioNew(os.Stdout, pNtk, fMffc)
	} else {
		if fUseFanio+fUsePio+fUseSupp+fUseCone == 1 {
			Abc_NtkPrintFanio(os.Stdout, pNtk, fUseFanio, fUsePio, fUseSupp, fUseCone)
		} else {
			fmt.Printf("Exactly one of the switches \"-f\", \"-i\", \"-s\", \"-c\" should be enabled.\n")
		}
	}
	return 0

usage:
	Abc_Print(-2, "usage: print_fanio [-fiscmvh]\n")
	Abc_Print(-2, "\t        prints the statistics about different objects in the network\n")
	Abc_Print(-2, "\t-f    : toggles considering fanins/fanouts of all nodes [default = %s]\n", abcYesNo(fUseFanio))
	Abc_Print(-2, "\t-i    : toggles considering fanins/fanouts of CI/CO [default = %s]\n", abcYesNo(fUsePio))
	Abc_Print(-2, "\t-s    : toggles considering TFO/TFI support sizes of CI/CO [default = %s]\n", abcYesNo(fUseSupp))
	Abc_Print(-2, "\t-c    : toggles considering TFO/TFI cone sizes of CI/CO [default = %s]\n", abcYesNo(fUseCone))
	Abc_Print(-2, "\t-m    : toggles printing MFFC sizes instead of fanouts [default = %s]\n", abcYesNo(fMffc))
	Abc_Print(-2, "\t-v    : toggles verbose way of printing the stats [default = %s]\n", abcYesNo(fVerbose))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

