/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintFactor(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pNode *Abc_Obj_t
	var c int32
	var fUseRealNames int32

	// set defaults
	fUseRealNames = 1
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "nh"); c != -1; c = Extra_UtilGetopt(argc, argv, "nh") {
		switch c {
		case 'n':
			fUseRealNames ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsSopLogic(pNtk) {
		Abc_Print(-1, "Printing factored forms can be done for SOP networks.\n")
		return 1
	}

	if argc > globalUtilOptind+1 {
		Abc_Print(-1, "Wrong number of auguments.\n")
		goto usage
	}

	if argc == globalUtilOptind+1 {
		pNode = Abc_NtkFindNode(pNtk, argv[globalUtilOptind])
		if pNode == nil {
			Abc_Print(-1, "Cannot find node \"%s\".\n", argv[globalUtilOptind])
			return 1
		}
		Abc_NodePrintFactor(os.Stdout, pNode, fUseRealNames)
		return 0
	}
	// print the nodes
	Abc_NtkPrintFactor(os.Stdout, pNtk, fUseRealNames)
	return 0

usage:
	Abc_Print(-2, "usage: print_factor [-nh] <node>\n")
	Abc_Print(-2, "\t        prints the factored forms of nodes\n")
	Abc_Print(-2, "\t-n    : toggles real/dummy fanin names [default = %s]\n", abcSelect(fUseRealNames, "real", "dummy"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	Abc_Print(-2, "\tnode  : (optional) one node to consider\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintLevel(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pNode *Abc_Obj_t
	var c int32
	var fListNodes int32
	var fProfile int32
	var fVerbose int32

	// set defaults
	fListNodes = 0
	fProfile = 1
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "npvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "npvh") {
		switch c {
		case 'n':
			fListNodes ^= 1
			break
		case 'p':
			fProfile ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !(fProfile != 0) && !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for AIGs (run \"strash\").\n")
		return 1
	}

	if argc > globalUtilOptind+1 {
		Abc_Print(-1, "Wrong number of auguments.\n")
		goto usage
	}

	if argc == globalUtilOptind+1 {
		pNode = Abc_NtkFindNode(pNtk, argv[globalUtilOptind])
		if pNode == nil {
			Abc_Print(-1, "Cannot find node \"%s\".\n", argv[globalUtilOptind])
			return 1
		}
		Abc_NodePrintLevel(os.Stdout, pNode)
		return 0
	}
	// process all COs
	Abc_NtkPrintLevel(os.Stdout, pNtk, fProfile, fListNodes, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: print_level [-npvh] <node>\n")
	Abc_Print(-2, "\t        prints information about node level and cone size\n")
	Abc_Print(-2, "\t-n    : toggles printing nodes by levels [default = %s]\n", abcYesNo(fListNodes))
	Abc_Print(-2, "\t-p    : toggles printing level profile [default = %s]\n", abcYesNo(fProfile))
	Abc_Print(-2, "\t-v    : enable verbose output [default = %s].\n", abcYesNo(fVerbose))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	Abc_Print(-2, "\tnode  : (optional) one node to consider\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintSupport(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var vSuppFun *Vec_Ptr_t
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fStruct int32
	var fVerbose int32
	var fVeryVerbose int32

	// set defaults
	fStruct = 1
	fVerbose = 0
	fVeryVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "svwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "svwh") {
		switch c {
		case 's':
			fStruct ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	// print support information
	if fStruct != 0 {
		Abc_NtkPrintStrSupports(pNtk, fVeryVerbose)
		return 0
	}

	if !Abc_NtkIsComb(pNtk) {
		Abc_Print(-1, "This command works only for combinational networks (run \"comb\").\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for AIGs (run \"strash\").\n")
		return 1
	}
	vSuppFun = Sim_ComputeFunSupp(pNtk, fVerbose)
	ABC_FREE(vSuppFun.pArray[0])
	Vec_PtrFree(vSuppFun)
	return 0

usage:
	Abc_Print(-2, "usage: print_supp [-svwh]\n")
	Abc_Print(-2, "\t        prints the supports of the CO nodes\n")
	Abc_Print(-2, "\t-s    : toggle printing structural support only [default = %s].\n", abcYesNo(fStruct))
	Abc_Print(-2, "\t-v    : enable verbose output [default = %s].\n", abcYesNo(fVerbose))
	Abc_Print(-2, "\t-w    : enable printing CI/CO dependency matrix [default = %s].\n", abcYesNo(fVeryVerbose))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintMint(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pObj *Abc_Obj_t
	var c int32
	var fVerbose int32

	// set defaults
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "svwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "svwh") {
		switch c {
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for logic networks (run \"clp\").\n")
		return 1
	}
	if !Abc_NtkHasBdd(pNtk) {
		Abc_Print(-1, "This command works only for logic networks with local functions represented by BDDs.\n")
		return 1
	}
	// The original C loop iterates over internal nodes in object order.
	for c = 0; c < Abc_NtkObjNumMax(pNtk); c++ {
		pObj = Abc_NtkObj(pNtk, c)
		if pObj == nil || !Abc_ObjIsNode(pObj) {
			continue
		}
		fmt.Printf("ObjId %3d : SuppSize = %5d   MintCount = %32.0f\n", c, Abc_ObjFaninNum(pObj), Cudd_CountMinterm(pNtk.pManFunc, pObj.pData, Abc_ObjFaninNum(pObj)))
	}
	return 0

usage:
	Abc_Print(-2, "usage: print_mint [-svwh]\n")
	Abc_Print(-2, "\t        prints the number of on-set minterms in the PO functions\n")
	Abc_Print(-2, "\t-v    : enable verbose output [default = %s].\n", abcYesNo(fVerbose))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintSymms(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fUseBdds int32
	var fNaive int32
	var fReorder int32
	var fVerbose int32

	// set defaults
	fUseBdds = 0
	fNaive = 0
	fReorder = 1
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "bnrvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "bnrvh") {
		switch c {
		case 'b':
			fUseBdds ^= 1
			break
		case 'n':
			fNaive ^= 1
			break
		case 'r':
			fReorder ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsComb(pNtk) {
		Abc_Print(-1, "This command works only for combinational networks (run \"comb\").\n")
		return 1
	}
	if Abc_NtkIsStrash(pNtk) {
		Abc_NtkSymmetries(pNtk, fUseBdds, fNaive, fReorder, fVerbose)
	} else {
		pNtk = Abc_NtkStrash(pNtk, 0, 0, 0)
		Abc_NtkSymmetries(pNtk, fUseBdds, fNaive, fReorder, fVerbose)
		Abc_NtkDelete(pNtk)
	}
	return 0

usage:
	Abc_Print(-2, "usage: print_symm [-bnrvh]\n")
	Abc_Print(-2, "\t         computes symmetries of the PO functions\n")
	Abc_Print(-2, "\t-b     : toggle BDD-based or SAT-based computations [default = %s].\n", abcSelect(fUseBdds, "BDD", "SAT"))
	Abc_Print(-2, "\t-n     : enable naive BDD-based computation [default = %s].\n", abcYesNo(fNaive))
	Abc_Print(-2, "\t-r     : enable dynamic BDD variable reordering [default = %s].\n", abcYesNo(fReorder))
	Abc_Print(-2, "\t-v     : enable verbose output [default = %s].\n", abcYesNo(fVerbose))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

