/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintDsd(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fCofactor int32
	var nCofLevel int32
	var fProfile int32
	var fPrintDec int32

	// set defaults
	nCofLevel = 1
	fCofactor = 0
	fProfile = 0
	fPrintDec = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Npcdh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Npcdh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nCofLevel = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCofLevel < 0 {
				goto usage
			}
			break
		case 'p':
			fProfile ^= 1
			break
		case 'c':
			fCofactor ^= 1
			break
		case 'd':
			fPrintDec ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	// get the truth table of the first output
	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "Currently works only for logic networks.\n")
		return 1
	}
	Abc_NtkToAig(pNtk)
	// convert it to truth table
	{
		var pObj *Abc_Obj_t = Abc_ObjFanin0(Abc_NtkPo(pNtk, 0))
		var vMemory *Vec_Int_t
		var pTruth []uint32
		if !Abc_ObjIsNode(pObj) {
			Abc_Print(-1, "The fanin of the first PO node does not have a logic function.\n")
			return 1
		}
		if Abc_ObjFaninNum(pObj) > 16 {
			Abc_Print(-1, "Currently works only for up to 16 inputs.\n")
			return 1
		}
		vMemory = Vec_IntAlloc(0)
		pMan, _ := pNtk.FunctionManager.(*Hop_Man_t)
		pRoot, _ := Abc_ObjData(pObj).(*Hop_Obj_t)
		pTruth = Hop_ManConvertAigToTruth(pMan, Hop_Regular(pRoot), Abc_ObjFaninNum(pObj), vMemory, 0)
		if Hop_IsComplement(pRoot) != 0 {
			Extra_TruthNot(pTruth, pTruth, Abc_ObjFaninNum(pObj))
		}
		//        Extra_PrintBinary( stdout, pTruth, 1 << Abc_ObjFaninNum(pObj) );
		//        Abc_Print( -1, "\n" );
		if fPrintDec != 0 { //&&Abc_ObjFaninNum(pObj) <= 6 )

			pTruthW := abcTruth32ToWords(pTruth)
			if Abc_ObjFaninNum(pObj) < 6 {
				pTruthW[0] = Abc_Tt6Stretch(pTruthW[0], Abc_ObjFaninNum(pObj))
			}
			Dau_DecTrySets(pTruthW, Abc_ObjFaninNum(pObj), 1)
		}
		if fProfile != 0 {
			Kit_TruthPrintProfile(pTruth, Abc_ObjFaninNum(pObj))
		} else if fCofactor != 0 {
			Kit_DsdPrintCofactors(pTruth, Abc_ObjFaninNum(pObj), nCofLevel, 1)
		} else {
			Kit_DsdTest(pTruth, Abc_ObjFaninNum(pObj))
		}
		Vec_IntFree(vMemory)
	}
	return 0

usage:
	Abc_Print(-2, "usage: print_dsd [-pcdh] [-N <num>]\n")
	Abc_Print(-2, "\t           print DSD formula for a single-output function with less than 16 variables\n")
	Abc_Print(-2, "\t-p       : toggle printing profile [default = %s]\n", abcSelect(fProfile, "yes", "no"))
	Abc_Print(-2, "\t-c       : toggle recursive cofactoring [default = %s]\n", abcSelect(fCofactor, "yes", "no"))
	Abc_Print(-2, "\t-d       : toggle printing decompositions [default = %s]\n", abcSelect(fPrintDec, "yes", "no"))
	Abc_Print(-2, "\t-N <num> : the number of levels to cofactor [default = %d]\n", nCofLevel)
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

