func Abc_CommandPrintStatus(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fOutStatus int32
	var fShort int32 = 1
	var pLogFileName string
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Losh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Losh") {
		switch c {
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a file name.\n")
				goto usage
			}
			pLogFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'o':
			fOutStatus ^= 1
			break
		case 's':
			fShort ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if fOutStatus != 0 {
		if pNtk == nil {
			Abc_Print(-1, "Empty network.\n")
			return 1
		}
		Abc_NtkPrintPoEquivs(pNtk)
		return 0
	}
	if pAbc.vStatuses == nil {
		Abc_Print(1, "Status = %d  Frames = %d   ", pAbc.Status, pAbc.nFrames)
	}
	if pAbc.pCex == nil && pAbc.vCexVec == nil {
		Abc_Print(1, "Cex is not defined.\n")
	} else {
		if pAbc.pCex != nil {
			Abc_CexPrintStats(pAbc.pCex)
		}
		if pAbc.vCexVec != nil {
			var pTemp *Abc_Cex_t
			var nCexes int32
			var Counter int32
			//printf( "\n" );
			for c = 0; c < int32(Vec_PtrSize(pAbc.vCexVec)); c++ {
				entry := Vec_PtrEntry(pAbc.vCexVec, int(c))
				if sentinel, ok := entry.(uintptr); ok && sentinel == 1 {
					Counter++
					continue
				}
				pTemp, _ = entry.(*Abc_Cex_t)
				if pTemp != nil {
					nCexes++
					fmt.Printf("%4d : ", nCexes)
					Abc_CexPrintStats(pTemp)
				}
			}
			//            if ( Counter )
			//                printf( "In total, %d (out of %d) outputs are \"sat\" but CEXes are not recorded.\n", Counter, Vec_PtrSize(pAbc->vCexVec) );
		}
	}
	if pAbc.vStatuses != nil {
		if pLogFileName != "" {
			var pTemp *Abc_Cex_t = nil
			var pFile *os.File
			var err error
			pFile, err = os.OpenFile(pLogFileName, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
			if err != nil {
				fmt.Printf("Cannot open file \"%s\" for writing.\n", pLogFileName)
				return 0
			}
			for c = 0; c < int32(Vec_PtrSize(pAbc.vCexVec)); c++ {
				pTemp, _ = Vec_PtrEntry(pAbc.vCexVec, int(c)).(*Abc_Cex_t)
				var Status int32 = Vec_IntEntry(pAbc.vStatuses, c)
				if Status == -1 { // undec
					fmt.Fprintf(pFile, "STATUS: ABORTED ")
				} else if Status == 0 {
					fmt.Fprintf(pFile, "STATUS: SAT ")
				} else if Status == 1 {
					fmt.Fprintf(pFile, "STATUS: UNSAT ")
				}
				fmt.Fprintf(pFile, "%s\n", Abc_ObjName(Abc_NtkPo(pNtk, c)))
				if Status != 0 {
					continue
				}
				Abc_NtkDumpOneCexSpecial(pFile, pNtk, pTemp)
			}
			_ = pFile.Close()

		} else if fShort != 0 {
			fmt.Printf("Status array contains %d SAT, %d UNSAT, and %d UNDEC entries (out of %d).", Vec_IntCountEntry(pAbc.vStatuses, 0), Vec_IntCountEntry(pAbc.vStatuses, 1), Vec_IntCountEntry(pAbc.vStatuses, -1), Vec_IntSize(pAbc.vStatuses))

		} else {
			for i := 0; i < Vec_IntSize(pAbc.vStatuses); i++ {
				Entry := Vec_IntEntry(pAbc.vStatuses, i)
				fmt.Printf("%d=%d  ", i, Entry)
			}
		}
		fmt.Printf("\n")
	}
	return 0

usage:
	Abc_Print(-2, "usage: print_status [-L file] [-osh]\n")
	Abc_Print(-2, "\t          prints verification status\n")
	Abc_Print(-2, "\t-L file : the log file name [default = %s]\n", abcDefaultString(pLogFileName, "no logging"))
	Abc_Print(-2, "\t-o      : toggle printing output status [default = %s]\n", abcSelect(fOutStatus, "yes", "no"))
	Abc_Print(-2, "\t-s      : toggle using short print-out [default = %s]\n", abcSelect(fShort, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPrintDelay(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pObjIn *Abc_Obj_t = nil
	var pObjOut *Abc_Obj_t = nil
	var c int32
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsMappedLogic(pNtk) {
		Abc_Print(-1, "Delay trace works only for network mapped into standard cells.\n")
		return 1
	}
	if argc > globalUtilOptind+2 {
		Abc_Print(-1, "Wrong number of auguments.\n")
		goto usage
	}
	// collect the first name (PO name)
	if argc >= globalUtilOptind+1 {
		var Num int32 = Nm_ManFindIdByName(pNtk.pManName, argv[globalUtilOptind], ABC_OBJ_PO)
		if Num < 0 {
			Num = Nm_ManFindIdByName(pNtk.pManName, argv[globalUtilOptind], ABC_OBJ_BI)
		}
		if Num >= 0 {
			pObjOut = Abc_NtkObj(pNtk, Num)
		}
		if pObjOut == nil {
			Abc_Print(1, "Cannot find combinational output \"%s\".\n", argv[globalUtilOptind])
			return 1
		}
	}
	// collect the second name (PI name)
	if argc == globalUtilOptind+2 {
		var Num int32 = Nm_ManFindIdByName(pNtk.pManName, argv[globalUtilOptind+1], ABC_OBJ_PI)
		if Num < 0 {
			Num = Nm_ManFindIdByName(pNtk.pManName, argv[globalUtilOptind+1], ABC_OBJ_BO)
		}
		if Num >= 0 {
			pObjIn = Abc_NtkObj(pNtk, Num)
		}
		if pObjIn == nil {
			Abc_Print(1, "Cannot find combinational input \"%s\".\n", argv[globalUtilOptind+1])
			return 1
		}
	}
	Abc_NtkDelayTrace(pNtk, pObjOut, pObjIn, 1)
	return 0

usage:
	Abc_Print(-2, "usage: print_delay [-h] <CO_name> <CI_name>\n")
	Abc_Print(-2, "\t            prints one critical path of the mapped network\n")
	Abc_Print(-2, "\t-h        : print the command usage\n")
	Abc_Print(-2, "\t<CO_name> : (optional) the sink of the critical path (primary output or flop input)\n")
	Abc_Print(-2, "\t<CI_name> : (optional) the source of the critical path (primary input or flop output)\n")
	Abc_Print(-2, "\t            (if CO and/or CI are not given, uses the most critical ones)\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandShow(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fSeq int32
	var fGateNames int32
	var fUseReverse int32
	var fFlopDep int32

	// set defaults
	fSeq = 0
	fGateNames = 0
	fUseReverse = 1
	fFlopDep = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "rsgfh"); c != -1; c = Extra_UtilGetopt(argc, argv, "rsgfh") {
		switch c {
		case 'r':
			fUseReverse ^= 1
			break
		case 's':
			fSeq ^= 1
			break
		case 'g':
			fGateNames ^= 1
			break
		case 'f':
			fFlopDep ^= 1
			break
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if fFlopDep != 0 {
		Abc_NtkShowFlopDependency(pNtk)
	} else {
		Abc_NtkShow(pNtk, fGateNames, fSeq, fUseReverse)
	}
	return 0

usage:
	Abc_Print(-2, "usage: show [-srgfh]\n")
	Abc_Print(-2, "       visualizes the network structure using DOT and GSVIEW\n")
	Abc_Print(-2, "\t-s    : toggles visualization of sequential networks [default = %s].\n", abcSelect(fSeq, "yes", "no"))
	Abc_Print(-2, "\t-r    : toggles ordering nodes in reverse order [default = %s].\n", abcSelect(fUseReverse, "yes", "no"))
	Abc_Print(-2, "\t-g    : toggles printing gate names for mapped network [default = %s].\n", abcSelect(fGateNames, "yes", "no"))
	Abc_Print(-2, "\t-f    : toggles visualizing flop dependency graph [default = %s].\n", abcSelect(fFlopDep, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandShowBdd(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pNode *Abc_Obj_t
	var c, fCompl, fGlobal int32

	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "cgh"); c != -1; c = Extra_UtilGetopt(argc, argv, "cgh") {
		switch c {
		case 'c':
			fCompl ^= 1
			break
		case 'g':
			fGlobal ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if fGlobal != 0 {
		var pTemp *Abc_Ntk_t
		if Abc_NtkIsStrash(pNtk) {
			pTemp = pNtk
		} else {
			pTemp = Abc_NtkStrash(pNtk, 0, 0, 0)
		}
		Abc_NtkShowBdd(pTemp, fCompl)
		if pTemp != pNtk {
			Abc_NtkDelete(pTemp)
		}
		return 0
	}

	if !Abc_NtkIsBddLogic(pNtk) {
		Abc_Print(-1, "Visualizing BDDs can only be done for logic BDD networks (run \"bdd\").\n")
		return 1
	}
	if argc > globalUtilOptind+1 {
		Abc_Print(-1, "Wrong number of auguments.\n")
		goto usage
	}
	if argc == globalUtilOptind {
		pNode = Abc_ObjFanin0(Abc_NtkPo(pNtk, 0))
		if !Abc_ObjIsNode(pNode) {
			Abc_Print(-1, "The driver \"%s\" of the first PO is not an internal node.\n", Abc_ObjName(pNode))
			return 1
		}

	} else {
		pNode = Abc_NtkFindNode(pNtk, argv[globalUtilOptind])
		if pNode == nil {
			Abc_Print(-1, "Cannot find node \"%s\".\n", argv[globalUtilOptind])
			return 1
		}
	}
	Abc_NodeShowBdd(pNode, fCompl)
	return 0

usage:
	Abc_Print(-2, "usage: show_bdd [-cgh] <node>\n")
	Abc_Print(-2, "       uses DOT and GSVIEW to visualize the global BDDs of primary outputs\n")
	Abc_Print(-2, "       in terms of primary inputs or the local BDD of a node in terms of its fanins\n")
	Abc_Print(-2, "\t<node>: (optional) the node to consider [default = the driver of the first PO]\n")
	Abc_Print(-2, "\t-c    : toggle visualizing BDD with complemented edges [default = %s].\n", abcSelect(fCompl, "yes", "no"))
	Abc_Print(-2, "\t-g    : toggle visualizing the global BDDs of primary outputs [default = %s].\n", abcSelect(fGlobal, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandShowCut(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pNode *Abc_Obj_t
	var c int32
	var nNodeSizeMax int32
	var nConeSizeMax int32

	// set defaults
	nNodeSizeMax = 10
	nConeSizeMax = ABC_INFINITY
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NCh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NCh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nNodeSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodeSizeMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConeSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConeSizeMax < 0 {
				goto usage
			}
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Visualizing cuts only works for AIGs (run \"strash\").\n")
		return 1
	}
	if argc != globalUtilOptind+1 {
		Abc_Print(-1, "Wrong number of auguments.\n")
		goto usage
	}

	pNode = Abc_NtkFindNode(pNtk, argv[globalUtilOptind])
	if pNode == nil {
		Abc_Print(-1, "Cannot find node \"%s\".\n", argv[globalUtilOptind])
		return 1
	}
	Abc_NodeShowCut(pNode, nNodeSizeMax, nConeSizeMax)
	return 0

usage:
	Abc_Print(-2, "usage: show_cut [-N <num>] [-C <num>] [-h] <node>\n")
	Abc_Print(-2, "             visualizes the cut of a node using DOT and GSVIEW\n")
	Abc_Print(-2, "\t-N <num> : the max size of the cut to be computed [default = %d]\n", nNodeSizeMax)
	Abc_Print(-2, "\t-C <num> : the max support of the containing cone [default = %d]\n", nConeSizeMax)
	Abc_Print(-2, "\t<node>   : the node to consider\n")
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCollapse(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var fVerbose int32
	var fBddSizeMax int32
	var fDualRail int32
	var fReorder int32
	var fReverse int32
	var fDumpOrder int32
	var c int32
	var pLogFileName string
	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	fVerbose = 0
	fReorder = 1
	fReverse = 0
	fDualRail = 0
	fDumpOrder = 0
	fBddSizeMax = ABC_INFINITY
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "BLrodxvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "BLrodxvh") {
		switch c {
		case 'B':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-B\" should be followed by an integer.\n")
				goto usage
			}
			fBddSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if fBddSizeMax < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a file name.\n")
				goto usage
			}
			pLogFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'r':
			fReorder ^= 1
			break
		case 'o':
			fReverse ^= 1
			break
		case 'd':
			fDualRail ^= 1
			break
		case 'x':
			fDumpOrder ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsLogic(pNtk) && !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Can only collapse a logic network or an AIG.\n")
		return 1
	}

	// get the new network
	if Abc_NtkIsStrash(pNtk) {
		pNtkRes = Abc_NtkCollapse(pNtk, fBddSizeMax, fDualRail, fReorder, fReverse, fDumpOrder, fVerbose)
	} else {
		pNtk = Abc_NtkStrash(pNtk, 0, 0, 0)
		pNtkRes = Abc_NtkCollapse(pNtk, fBddSizeMax, fDualRail, fReorder, fReverse, fDumpOrder, fVerbose)
		Abc_NtkDelete(pNtk)
	}
	if pNtkRes == nil {
		Abc_Print(-1, "Collapsing has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	if pLogFileName != "" {
		pAbc.pCex = nil
		pAbc.nFrames = -1
		if Abc_NtkNodeNum(pNtkRes) == 0 {
			pAbc.Status = 1 // UNSAT
		} else {
			pAbc.Status = -1
		} // UNDEC
		Abc_NtkWriteLogFile(pLogFileName, pAbc.pCex, pAbc.Status, pAbc.nFrames, "collapse")
	}
	return 0

usage:
	Abc_Print(-2, "usage: collapse [-B <num>] [-L file] [-rodxvh]\n")
	Abc_Print(-2, "\t          collapses the network by constructing global BDDs\n")
	Abc_Print(-2, "\t-B <num>: limit on live BDD nodes during collapsing [default = %d]\n", fBddSizeMax)
	logName := pLogFileName
	if logName == "" {
		logName = "no logging"
	}
	Abc_Print(-2, "\t-L file : the log file name [default = %s]\n", logName)
	Abc_Print(-2, "\t-r      : toggles dynamic variable reordering [default = %s]\n", abcSelect(fReorder, "yes", "no"))
	Abc_Print(-2, "\t-o      : toggles reverse variable ordering [default = %s]\n", abcSelect(fReverse, "yes", "no"))
	Abc_Print(-2, "\t-d      : toggles dual-rail collapsing mode [default = %s]\n", abcSelect(fDualRail, "yes", "no"))
	Abc_Print(-2, "\t-x      : toggles dumping file \"order.txt\" with variable order [default = %s]\n", abcSelect(fDumpOrder, "yes", "no"))
	Abc_Print(-2, "\t-v      : print verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSatClp(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pNtkRes *Abc_Ntk_t
	var nCubeLim int32
	var nBTLimit int32 = 1000000
	var nCostMax int32 = 20000000
	var fCanon int32
	var fReverse int32
	var fCnfShared int32
	var fVerbose int32
	var c int32

	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CLZcrsvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "CLZcrsvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nCubeLim = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCubeLim < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBTLimit < 0 {
				goto usage
			}
			break
		case 'Z':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-Z\" should be followed by an integer.\n")
				goto usage
			}
			nCostMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCostMax < 0 {
				goto usage
			}
			break
		case 'c':
			fCanon ^= 1
			break
		case 'r':
			fReverse ^= 1
			break
		case 's':
			fCnfShared ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsLogic(pNtk) && !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Can only collapse a logic network or an AIG.\n")
		return 1
	}

	// get the new network
	if Abc_NtkIsStrash(pNtk) {
		pNtkRes = Abc_NtkCollapseSat(pNtk, nCubeLim, nBTLimit, nCostMax, fCanon, fReverse, fCnfShared, fVerbose)
	} else {
		pNtk = Abc_NtkStrash(pNtk, 0, 0, 0)
		pNtkRes = Abc_NtkCollapseSat(pNtk, nCubeLim, nBTLimit, nCostMax, fCanon, fReverse, fCnfShared, fVerbose)
		Abc_NtkDelete(pNtk)
	}
	if pNtkRes == nil {
		Abc_Print(-1, "Collapsing has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: satclp [-CLZ num] [-crsvh]\n")
	Abc_Print(-2, "\t         performs SAT based collapsing\n")
	Abc_Print(-2, "\t-C num : the limit on the SOP size of one output [default = %d]\n", nCubeLim)
	Abc_Print(-2, "\t-L num : the limit on the number of conflicts in one SAT call [default = %d]\n", nBTLimit)
	Abc_Print(-2, "\t-Z num : the limit on the cost of the largest output [default = %d]\n", nCostMax)
	Abc_Print(-2, "\t-c     : toggles using canonical ISOP computation [default = %s]\n", abcSelect(fCanon, "yes", "no"))
	Abc_Print(-2, "\t-r     : toggles using reverse veriable ordering [default = %s]\n", abcSelect(fReverse, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggles shared CNF computation (non-canonical only) [default = %s]\n", abcSelect(fCnfShared, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandStrash(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var pObj *Abc_Obj_t
	var c int32
	var fAllNodes int32
	var fRecord int32
	var fCleanup int32
	var fComplOuts int32
	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fAllNodes = 0
	fCleanup = 1
	fRecord = 0
	fComplOuts = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "acrih"); c != -1; c = Extra_UtilGetopt(argc, argv, "acrih") {
		switch c {
		case 'a':
			fAllNodes ^= 1
			break
		case 'c':
			fCleanup ^= 1
			break
		case 'r':
			fRecord ^= 1
			break
		case 'i':
			fComplOuts ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	// get the new network
	pNtkRes = Abc_NtkStrash(pNtk, fAllNodes, fCleanup, fRecord)
	if pNtkRes == nil {
		Abc_Print(-1, "Strashing has failed.\n")
		return 1
	}
	if fComplOuts != 0 {
		Abc_NtkForEachPo(pNtkRes, pObj, c)
		Abc_ObjXorFaninC(pObj, 0)
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: strash [-acrih]\n")
	Abc_Print(-2, "\t        transforms combinational logic into an AIG\n")
	Abc_Print(-2, "\t-a    : toggles between using all nodes and DFS nodes [default = %s]\n", abcSelect(fAllNodes, "all", "DFS"))
	Abc_Print(-2, "\t-c    : toggles cleanup to remove the dagling AIG nodes [default = %s]\n", abcSelect(fCleanup, "all", "DFS"))
	Abc_Print(-2, "\t-r    : toggles using the record of AIG subgraphs [default = %s]\n", abcSelect(fRecord, "yes", "no"))
	Abc_Print(-2, "\t-i    : toggles complementing the POs of the AIG [default = %s]\n", abcSelect(fComplOuts, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandBalance(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes, pNtkTemp *Abc_Ntk_t
	var c int32
	var fDuplicate int32
	var fSelective int32
	var fUpdateLevel int32
	var fExor int32
	var fVerbose int32
	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	fDuplicate = 0
	fSelective = 0
	fUpdateLevel = 1
	fExor = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ldsxvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "ldsxvh") {
		switch c {
		case 'l':
			fUpdateLevel ^= 1
			break
		case 'd':
			fDuplicate ^= 1
			break
		case 's':
			fSelective ^= 1
			break
		case 'x':
			fExor ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	// get the new network
	if Abc_NtkIsStrash(pNtk) {
		if fExor != 0 {
			pNtkRes = Abc_NtkBalanceExor(pNtk, fUpdateLevel, fVerbose)
		} else {
			pNtkRes = Abc_NtkBalance(pNtk, fDuplicate, fSelective, fUpdateLevel)
		}

	} else {
		pNtkTemp = Abc_NtkStrash(pNtk, 0, 0, 0)
		if pNtkTemp == nil {
			Abc_Print(-1, "Strashing before balancing has failed.\n")
			return 1
		}
		if fExor != 0 {
			pNtkRes = Abc_NtkBalanceExor(pNtkTemp, fUpdateLevel, fVerbose)
		} else {
			pNtkRes = Abc_NtkBalance(pNtkTemp, fDuplicate, fSelective, fUpdateLevel)
		}
		Abc_NtkDelete(pNtkTemp)
	}

	// check if balancing worked
	if pNtkRes == nil {
		Abc_Print(-1, "Balancing has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: balance [-ldsxvh]\n")
	Abc_Print(-2, "\t        transforms the current network into a well-balanced AIG\n")
	Abc_Print(-2, "\t-l    : toggle minimizing the number of levels [default = %s]\n", abcSelect(fUpdateLevel, "yes", "no"))
	Abc_Print(-2, "\t-d    : toggle duplication of logic [default = %s]\n", abcSelect(fDuplicate, "yes", "no"))
	Abc_Print(-2, "\t-s    : toggle duplication on the critical paths [default = %s]\n", abcSelect(fSelective, "yes", "no"))
	Abc_Print(-2, "\t-x    : toggle balancing multi-input EXORs [default = %s]\n", abcSelect(fExor, "yes", "no"))
	Abc_Print(-2, "\t-v    : print verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

