/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRunSim(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pFileNames [4]string = [4]string{nil, nil, "out.v", nil}
	var c int32
	var nTimeout int32
	var nWords int32 = 8
	var nBeam int32 = 4
	var LevL int32 = -1
	var LevU int32 = -1
	var fOrder int32
	var fFancy int32
	var fUseBuf int32
	var fRandom int32
	var fUseWeights int32
	var fInputs int32
	var fSkipMffc int32
	var fVerbose int32
	var fVeryVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "TWBLUofbruimvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "TWBLUofbruimvwh") {
		switch c {
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			nTimeout = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nTimeout < 0 {
				goto usage
			}
			break
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			nWords = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nWords < 0 {
				goto usage
			}
			break
		case 'B':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-B\" should be followed by an integer.\n")
				goto usage
			}
			nBeam = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBeam < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			LevL = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if LevL < 0 {
				goto usage
			}
			break
		case 'U':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-U\" should be followed by an integer.\n")
				goto usage
			}
			LevU = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if LevU < 0 {
				goto usage
			}
			break
		case 'o':
			fOrder ^= 1
			break
		case 'f':
			fFancy ^= 1
			break
		case 'b':
			fUseBuf ^= 1
			break
		case 'r':
			fRandom ^= 1
			break
		case 'u':
			fUseWeights ^= 1
			break
		case 'i':
			fInputs ^= 1
			break
		case 'm':
			fSkipMffc ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if argc-globalUtilOptind < 2 || argc-globalUtilOptind > 4 {
		Abc_Print(1, "Expecting two or three file names on the command line.\n")
		goto usage
	}
	Gia_ManRandom(1)
	for c = 0; c < argc-globalUtilOptind; c++ {
		pFileNames[c] = argv[globalUtilOptind+c]
	}
	for c = 0; c < argc-globalUtilOptind-1; c++ {
		var pFile *os.File = os.Open(pFileNames[c])
		if pFile == nil {
			fmt.Printf("Cannot open input file \"%s\".\n", pFileNames[c])
			return 0

		} else {
			_ = pFile.Close()
		}
	}
	Acb_NtkRunSim(pFileNames, nTimeout, nWords, nBeam, LevL, LevU, fOrder, fFancy, fUseBuf, fRandom, fUseWeights, fInputs, fSkipMffc, fVerbose, fVeryVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: runsim [-TWBLU] [-ofbruimvwh] [-N <num>] <file1> <file2> <file3>\n")
	Abc_Print(-2, "\t           experimental simulation command\n")
	Abc_Print(-2, "\t-T <num> : the timeout in seconds [default = %d]\n", nTimeout)
	Abc_Print(-2, "\t-W <num> : the number of words of simulation info [default = %d]\n", nWords)
	Abc_Print(-2, "\t-B <num> : the beam width parameter [default = %d]\n", nBeam)
	Abc_Print(-2, "\t-L <num> : the lower bound on level [default = %d]\n", LevL)
	Abc_Print(-2, "\t-U <num> : the upper bound on level [default = %d]\n", LevU)
	Abc_Print(-2, "\t-o       : toggle using a different node ordering [default = %s]\n", abcSelect(fOrder, "yes", "no"))
	Abc_Print(-2, "\t-f       : toggle using experimental feature [default = %s]\n", abcSelect(fFancy, "yes", "no"))
	Abc_Print(-2, "\t-b       : toggle using buffers [default = %s]\n", abcSelect(fUseBuf, "yes", "no"))
	Abc_Print(-2, "\t-r       : toggle using random permutation of support variables [default = %s]\n", abcSelect(fRandom, "yes", "no"))
	Abc_Print(-2, "\t-u       : toggle using topological info to select support variables [default = %s]\n", abcSelect(fUseWeights, "yes", "no"))
	Abc_Print(-2, "\t-i       : toggle using primary inputs as support variables [default = %s]\n", abcSelect(fInputs, "yes", "no"))
	Abc_Print(-2, "\t-m       : toggle MFFC nodes as candidate divisors [default = %s]\n", abcSelect(fSkipMffc, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggle printing more verbose information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

