/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRewrite(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fUpdateLevel int32
	var fPrecompute int32
	var fUseZeros int32
	var fVerbose int32
	var fVeryVerbose int32
	var fPlaceEnable int32
	// external functions

	// set defaults
	fUpdateLevel = 1
	fPrecompute = 0
	fUseZeros = 0
	fVerbose = 0
	fVeryVerbose = 0
	fPlaceEnable = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "lxzvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "lxzvwh") {
		switch c {
		case 'l':
			fUpdateLevel ^= 1
			break
		case 'x':
			fPrecompute ^= 1
			break
		case 'z':
			fUseZeros ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'p':
			fPlaceEnable ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if fPrecompute != 0 {
		Rwr_Precompute()
		return 0
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command can only be applied to an AIG (run \"strash\").\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "AIG resynthesis cannot be applied to AIGs with choice nodes.\n")
		return 1
	}

	// modify the current network
	if !Abc_NtkRewrite(pNtk, fUpdateLevel, fUseZeros, fVerbose, fVeryVerbose, fPlaceEnable) {
		Abc_Print(-1, "Rewriting has failed.\n")
		return 1
	}
	return 0

usage:
	Abc_Print(-2, "usage: rewrite [-lzvwh]\n")
	Abc_Print(-2, "\t         performs technology-independent rewriting of the AIG\n")
	Abc_Print(-2, "\t-l     : toggle preserving the number of levels [default = %s]\n", abcSelect(fUpdateLevel, "yes", "no"))
	Abc_Print(-2, "\t-z     : toggle using zero-cost replacements [default = %s]\n", abcSelect(fUseZeros, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggle printout subgraph statistics [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	//    Abc_Print( -2, "\t-p     : toggle placement-aware rewriting [default = %s]\n", abcSelect(fPlaceEnable, "yes", "no") );
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRefactor(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var nNodeSizeMax int32
	var nConeSizeMax int32
	var fUpdateLevel int32
	var fUseZeros int32
	var fUseDcs int32
	var fVerbose int32

	// set defaults
	nNodeSizeMax = 10
	nConeSizeMax = 16
	fUpdateLevel = 1
	fUseZeros = 0
	fUseDcs = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Nlzvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Nlzvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nNodeSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodeSizeMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConeSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConeSizeMax < 0 {
				goto usage
			}
			break
		case 'l':
			fUpdateLevel ^= 1
			break
		case 'z':
			fUseZeros ^= 1
			break
		case 'd':
			fUseDcs ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command can only be applied to an AIG (run \"strash\").\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "AIG resynthesis cannot be applied to AIGs with choice nodes.\n")
		return 1
	}
	if nNodeSizeMax > 15 {
		Abc_Print(-1, "The cone size cannot exceed 15.\n")
		return 1
	}

	if (fUseDcs != 0) && nNodeSizeMax >= nConeSizeMax {
		Abc_Print(-1, "For don't-care to work, containing cone should be larger than collapsed node.\n")
		return 1
	}

	// modify the current network
	if !Abc_NtkRefactor(pNtk, nNodeSizeMax, nConeSizeMax, fUpdateLevel, fUseZeros, fUseDcs, fVerbose) {
		Abc_Print(-1, "Refactoring has failed.\n")
		return 1
	}
	return 0

usage:
	Abc_Print(-2, "usage: refactor [-N <num>] [-lzvh]\n")
	Abc_Print(-2, "\t           performs technology-independent refactoring of the AIG\n")
	Abc_Print(-2, "\t-N <num> : the max support of the collapsed node [default = %d]\n", nNodeSizeMax)
	//    Abc_Print( -2, "\t-C <num> : the max support of the containing cone [default = %d]\n", nConeSizeMax );
	Abc_Print(-2, "\t-l       : toggle preserving the number of levels [default = %s]\n", abcSelect(fUpdateLevel, "yes", "no"))
	Abc_Print(-2, "\t-z       : toggle using zero-cost replacements [default = %s]\n", abcSelect(fUseZeros, "yes", "no"))
	//    Abc_Print( -2, "\t-d       : toggle using don't-cares [default = %s]\n", abcSelect(fUseDcs, "yes", "no") );
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRestructure(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var nCutsMax int32
	var fUpdateLevel int32
	var fUseZeros int32
	var fVerbose int32

	// set defaults
	nCutsMax = 5
	fUpdateLevel = 0
	fUseZeros = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Klzvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Klzvh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nCutsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCutsMax < 0 {
				goto usage
			}
			break
		case 'l':
			fUpdateLevel ^= 1
			break
		case 'z':
			fUseZeros ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if nCutsMax < 4 || nCutsMax > CUT_SIZE_MAX {
		Abc_Print(-1, "Can only compute the cuts for %d <= K <= %d.\n", 4, CUT_SIZE_MAX)
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command can only be applied to an AIG (run \"strash\").\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "AIG resynthesis cannot be applied to AIGs with choice nodes.\n")
		return 1
	}

	// modify the current network
	if !Abc_NtkRestructure(pNtk, nCutsMax, fUpdateLevel, fUseZeros, fVerbose) {
		Abc_Print(-1, "Refactoring has failed.\n")
		return 1
	}
	return 0

usage:
	Abc_Print(-2, "usage: restructure [-K <num>] [-lzvh]\n")
	Abc_Print(-2, "\t           performs technology-independent restructuring of the AIG\n")
	Abc_Print(-2, "\t-K <num> : the max cut size (%d <= num <= %d) [default = %d]\n", CUT_SIZE_MIN, CUT_SIZE_MAX, nCutsMax)
	Abc_Print(-2, "\t-l       : toggle preserving the number of levels [default = %s]\n", abcSelect(fUpdateLevel, "yes", "no"))
	Abc_Print(-2, "\t-z       : toggle using zero-cost replacements [default = %s]\n", abcSelect(fUseZeros, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandResubstitute(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var RS_CUT_MIN int32 = 4
	var RS_CUT_MAX int32 = 16
	var c int32
	var nCutsMax int32
	var nNodesMax int32
	var nLevelsOdc int32
	var fUpdateLevel int32
	var fUseZeros int32
	var fVerbose int32
	var fVeryVerbose int32

	// set defaults
	nCutsMax = 8
	nNodesMax = 1
	nLevelsOdc = 0
	fUpdateLevel = 1
	fUseZeros = 0
	fVerbose = 0
	fVeryVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "KNFlzvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "KNFlzvwh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nCutsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCutsMax < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nNodesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodesMax < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nLevelsOdc = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLevelsOdc < 0 {
				goto usage
			}
			break
		case 'l':
			fUpdateLevel ^= 1
			break
		case 'z':
			fUseZeros ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if nCutsMax < RS_CUT_MIN || nCutsMax > RS_CUT_MAX {
		Abc_Print(-1, "Can only compute cuts for %d <= K <= %d.\n", RS_CUT_MIN, RS_CUT_MAX)
		return 1
	}
	if nNodesMax < 0 || nNodesMax > 3 {
		Abc_Print(-1, "Can only resubstitute at most 3 nodes.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command can only be applied to an AIG (run \"strash\").\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "AIG resynthesis cannot be applied to AIGs with choice nodes.\n")
		return 1
	}

	// modify the current network
	if !Abc_NtkResubstitute(pNtk, nCutsMax, nNodesMax, nLevelsOdc, fUpdateLevel, fVerbose, fVeryVerbose) {
		Abc_Print(-1, "Refactoring has failed.\n")
		return 1
	}
	return 0

usage:
	Abc_Print(-2, "usage: resub [-KN <num>] [-lzvwh]\n")
	Abc_Print(-2, "\t           performs technology-independent restructuring of the AIG\n")
	Abc_Print(-2, "\t-K <num> : the max cut size (%d <= num <= %d) [default = %d]\n", RS_CUT_MIN, RS_CUT_MAX, nCutsMax)
	Abc_Print(-2, "\t-N <num> : the max number of nodes to add (0 <= num <= 3) [default = %d]\n", nNodesMax)
	Abc_Print(-2, "\t-F <num> : the number of fanout levels for ODC computation [default = %d]\n", nLevelsOdc)
	Abc_Print(-2, "\t-l       : toggle preserving the number of levels [default = %s]\n", abcSelect(fUpdateLevel, "yes", "no"))
	Abc_Print(-2, "\t-z       : toggle using zero-cost replacements [default = %s]\n", abcSelect(fUseZeros, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggle verbose printout of ODC computation [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRr(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c, Window int32
	var nFaninLevels int32
	var nFanoutLevels int32
	var fUseFanouts int32
	var fVerbose int32

	// set defaults
	nFaninLevels = 3
	nFanoutLevels = 3
	fUseFanouts = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Wfvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Wfvh") {
		switch c {
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			Window = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Window < 0 {
				goto usage
			}
			nFaninLevels = Window / 10
			nFanoutLevels = Window % 10
			break
		case 'f':
			fUseFanouts ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	fmt.Printf("This command is obsolete.")
	fmt.Printf("To perform pure redudancy removal, try \"mfs -r\".\n")
	fmt.Printf("To perform something a little stronger try \"mfs2\"\n")
	fmt.Printf("When working with an AIG, use \"logic\" before and \"strash\" after this command.\n")
	return 0

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command can only be applied to an AIG (run \"strash\").\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "AIG resynthesis cannot be applied to AIGs with choice nodes.\n")
		return 1
	}

	// modify the current network
	if !Abc_NtkRR(pNtk, nFaninLevels, nFanoutLevels, fUseFanouts, fVerbose) {
		Abc_Print(-1, "Redundancy removal has failed.\n")
		return 1
	}
	return 0

usage:
	Abc_Print(-2, "usage: rr [-W NM] [-fvh]\n")
	Abc_Print(-2, "\t         removes combinational redundancies in the current network\n")
	Abc_Print(-2, "\t-W NM  : window size: TFI (N) and TFO (M) logic levels [default = %d%d]\n", nFaninLevels, nFanoutLevels)
	Abc_Print(-2, "\t-f     : toggle RR w.r.t. fanouts [default = %s]\n", abcSelect(fUseFanouts, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCascade(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, nLutSize int32
	var fCheck int32
	var fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	nLutSize = 12
	fCheck = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Kcvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Kcvh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nLutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLutSize < 0 {
				goto usage
			}
			break
		case 'c':
			fCheck ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsLogic(pNtk) && !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Can only collapse a logic network or an AIG.\n")
		return 1
	}

	// get the new network
	if Abc_NtkIsStrash(pNtk) {
		pNtkRes = Abc_NtkCascade(pNtk, nLutSize, fCheck, fVerbose)
	} else {
		pNtk = Abc_NtkStrash(pNtk, 0, 0, 0)
		pNtkRes = Abc_NtkCascade(pNtk, nLutSize, fCheck, fVerbose)
		Abc_NtkDelete(pNtk)
	}
	if pNtkRes == nil {
		Abc_Print(-1, "Cascade synthesis has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: cascade [-K <num>] [-cvh]\n")
	Abc_Print(-2, "\t           performs LUT cascade synthesis for the current network\n")
	Abc_Print(-2, "\t-K <num> : the number of LUT inputs [default = %d]\n", nLutSize)
	Abc_Print(-2, "\t-c       : check equivalence after synthesis [default = %s]\n", abcSelect(fCheck, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	Abc_Print(-2, "\t           \n")
	Abc_Print(-2, "  A lookup-table cascade is a programmable architecture developed by\n")
	Abc_Print(-2, "  Professor Tsutomu Sasao (sasao@cse.kyutech.ac.jp) at Kyushu Institute\n")
	Abc_Print(-2, "  of Technology. This work received Takeda Techno-Entrepreneurship Award:\n")
	Abc_Print(-2, "  http://www.lsi-cad.com/sasao/photo/takeda.html\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandExtract(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtk, pNtkRes *Abc_Ntk_t
	var c, nMultiSize, fAnd, fVerbose int32
	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	nMultiSize = 3
	fAnd = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Kavh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Kavh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nMultiSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nMultiSize < 0 {
				goto usage
			}
			break
		case 'a':
			fAnd ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Can only collapse a logic network or an AIG.\n")
		return 1
	}
	// get the new network
	pNtkRes = Abc_NtkShareXor(pNtk, nMultiSize, fAnd, fVerbose)
	if pNtkRes == nil {
		Abc_Print(-1, "Cascade synthesis has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: extract [-K <num>] [-avh]\n")
	Abc_Print(-2, "\t           extracts shared logic from multi-input gates\n")
	Abc_Print(-2, "\t-K <num> : the minimum gate size to consider for extraction [default = %d]\n", nMultiSize)
	Abc_Print(-2, "\t-a       : toggle multi-input XOR vs multi-input AND [default = %s]\n", abcSelect(fAnd, "AND", "XOR"))
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

