/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandMajExact(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var nVars int32 = 3
	var nNodes int32 = 1
	var fUseConst int32
	var fUseLine int32
	var fGlucose int32
	var fUseRand int32
	var nRands int32
	var fVerbose int32 = 1
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "INRfcrgvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "INRfcrgvh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nVars < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nNodes = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodes < 0 {
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			nRands = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nRands < 0 {
				goto usage
			}
			break
		case 'f':
			fUseConst ^= 1
			break
		case 'c':
			fUseLine ^= 1
			break
		case 'r':
			fUseRand ^= 1
			break
		case 'g':
			fGlucose ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if (nVars & 1) == 0 {
		Abc_Print(-1, "Cannot sythesize MAJ gate with an even number of inputs (%d).\n", nVars)
		return 1
	}
	if fGlucose != 0 {
		Maj_ManExactSynthesis(nVars, nNodes, fUseConst, fUseLine, fVerbose)
	} else {
		Maj_ManExactSynthesis2(nVars, nNodes, fUseConst, fUseLine, fUseRand, nRands, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: majexact [-INR <num>] [-fcrgvh]\n")
	Abc_Print(-2, "\t           exact synthesis of multi-input MAJ using MAJ3 gates\n")
	Abc_Print(-2, "\t-I <num> : the number of input variables [default = %d]\n", nVars)
	Abc_Print(-2, "\t-N <num> : the number of MAJ3 nodes [default = %d]\n", nNodes)
	Abc_Print(-2, "\t-R <num> : the number of additional connections [default = %d]\n", nRands)
	Abc_Print(-2, "\t-f       : toggle using constant fanins [default = %s]\n", abcSelect(fUseConst, "yes", "no"))
	Abc_Print(-2, "\t-c       : toggle using cascade topology [default = %s]\n", abcSelect(fUseLine, "yes", "no"))
	Abc_Print(-2, "\t-r       : toggle using random topology [default = %s]\n", abcSelect(fUseRand, "yes", "no"))
	Abc_Print(-2, "\t-g       : toggle using Glucose 3.0 by Gilles Audemard and Laurent Simon [default = %s]\n", abcSelect(fGlucose, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandTwoExact(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var Pars Bmc_EsPar_t
	var pPars *Bmc_EsPar_t = &Pars
	Bmc_EsParSetDefault(pPars)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "INTaogvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "INTaogvh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nVars < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nNodes = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nNodes < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			pPars.RuntimeLim = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.RuntimeLim < 0 {
				goto usage
			}
			break
		case 'a':
			pPars.fOnlyAnd ^= 1
			break
		case 'o':
			pPars.fFewerVars ^= 1
			break
		case 'g':
			pPars.fGlucose ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if argc == globalUtilOptind+1 {
		pPars.pTtStr = argv[globalUtilOptind]
	}
	if pPars.pTtStr == nil {
		Abc_Print(-1, "Truth table should be given on the command line.\n")
		return 1
	}
	if (1 << (pPars.nVars - 2)) != int32(len(pPars.pTtStr)) {
		Abc_Print(-1, "Truth table is expected to have %d hex digits (instead of %d).\n", (1 << (pPars.nVars - 2)), len(pPars.pTtStr))
		return 1
	}
	if pPars.nVars > pPars.nNodes*(2-1)+1 {
		Abc_Print(-1, "Function with %d variales cannot be implemented with %d two-input gates.\n", pPars.nVars, pPars.nNodes)
		return 1
	}
	if pPars.nVars > 10 {
		Abc_Print(-1, "Function should not have more than 10 inputs.\n")
		return 1
	}
	if pPars.fGlucose {
		Exa_ManExactSynthesis(pPars)
	} else {
		Exa_ManExactSynthesis2(pPars)
	}
	return 0

usage:
	Abc_Print(-2, "usage: twoexact [-INT <num>] [-aogvh] <hex>\n")
	Abc_Print(-2, "\t           exact synthesis of multi-input function using two-input gates\n")
	Abc_Print(-2, "\t-I <num> : the number of input variables [default = %d]\n", pPars.nVars)
	Abc_Print(-2, "\t-N <num> : the number of two-input nodes [default = %d]\n", pPars.nNodes)
	Abc_Print(-2, "\t-T <num> : the runtime limit in seconds [default = %d]\n", pPars.RuntimeLim)
	Abc_Print(-2, "\t-a       : toggle using only AND-gates (without XOR-gates) [default = %s]\n", abcSelect(pPars.fOnlyAnd, "yes", "no"))
	Abc_Print(-2, "\t-o       : toggle using additional optimizations [default = %s]\n", abcSelect(pPars.fFewerVars, "yes", "no"))
	Abc_Print(-2, "\t-g       : toggle using Glucose 3.0 by Gilles Audemard and Laurent Simon [default = %s]\n", abcSelect(pPars.fGlucose, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(pPars.fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	Abc_Print(-2, "\t<hex>    : truth table in hex notation\n")
	Abc_Print(-2, "\t           \n")
	Abc_Print(-2, "\t           For example, command line \"twoexact -g -I 5 -N 12 169AE443\"\n")
	Abc_Print(-2, "\t           synthesizes the smallest circuit composed of two-input gates\n")
	Abc_Print(-2, "\t           for the only NPN class of 5-input functions that requires 12 gates;\n")
	Abc_Print(-2, "\t           all other functions can be realized with 11 two-input gates or less\n")
	Abc_Print(-2, "\t           (see Section 7.1.2 \"Boolean evaluation\" in the book by Donald Knuth\n")
	Abc_Print(-2, "\t           http://www.cs.utsa.edu/~wagner/knuth/fasc0c.pdf)\n")
	return 1
}

