func Abc_CommandMajGen(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var nVars int32 = 8
	var fDump int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Ndvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Ndvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nVars < 0 {
				goto usage
			}
			break
		case 'd':
			fDump ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	Gem_Enumerate(nVars, fDump, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: majgen [-N <num>] [-dvh]>\n")
	Abc_Print(-2, "\t           generates networks for majority gates\n")
	Abc_Print(-2, "\t-N <num> : the maximum number of variables [default = %d]\n", nVars)
	Abc_Print(-2, "\t-d       : toggle dumping functions into a file [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandLogic(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command is only applicable to strashed networks.\n")
		return 1
	}

	// get the new network
	pNtkRes = Abc_NtkToLogic(pNtk)
	if pNtkRes == nil {
		Abc_Print(-1, "Converting to a logic network has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: logic [-h]\n")
	Abc_Print(-2, "\t        transforms an AIG into a logic network with SOPs\n")
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandComb(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var fRemoveLatches int32
	var nLatchesToAdd int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fRemoveLatches = 0
	nLatchesToAdd = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Llh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Llh") {
		switch c {
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nLatchesToAdd = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLatchesToAdd < 0 {
				goto usage
			}
			break
		case 'l':
			fRemoveLatches ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkIsComb(pNtk) && nLatchesToAdd == 0 {
		Abc_Print(-1, "The network is already combinational.\n")
		return 0
	}
	if !Abc_NtkIsComb(pNtk) && nLatchesToAdd != 0 {
		Abc_Print(-1, "The network is already combinational.\n")
		return 0
	}

	// get the new network
	pNtkRes = Abc_NtkDup(pNtk)
	if nLatchesToAdd != 0 {
		Abc_NtkMakeSeq(pNtkRes, nLatchesToAdd)
	} else {
		Abc_NtkMakeComb(pNtkRes, fRemoveLatches)
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: comb [-L <num>] [-lh]\n")
	Abc_Print(-2, "\t           converts comb network into seq, and vice versa\n")
	Abc_Print(-2, "\t-L <num> : number of latches to add to comb network (0 = do not add) [default = %d]\n", nLatchesToAdd)
	Abc_Print(-2, "\t-l       : toggle converting latches to PIs/POs or removing them [default = %s]\n", abcSelect(fRemoveLatches, "remove", "convert"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandMiter(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var Buffer string // was [32]byte in C

	var pNtk, pNtk1, pNtk2, pNtkRes *Abc_Ntk_t
	var fDelete1, fDelete2 int32
	var pArgvNew *string
	var nArgcNew int32
	var c int32
	var fCheck int32
	var fComb int32
	var fImplic int32
	var fMulti int32
	var nPartSize int32
	var fTrans int32
	var fIgnoreNames int32

	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	fComb = 0
	fCheck = 1
	fImplic = 0
	fMulti = 0
	nPartSize = 0
	fTrans = 0
	fIgnoreNames = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Pcmitnh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Pcmitnh") {
		switch c {
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nPartSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPartSize < 0 {
				goto usage
			}
			break
		case 'c':
			fComb ^= 1
			break
		case 'm':
			fMulti ^= 1
			break
		case 'i':
			fImplic ^= 1
			break
		case 't':
			fTrans ^= 1
			break
		case 'n':
			fIgnoreNames ^= 1
			break
		default:
			goto usage
		}
	}

	if fTrans != 0 {
		if (Abc_NtkPoNum(pNtk) & 1) == 1 {
			Abc_Print(-1, "Abc_CommandMiter(): The number of outputs should be even.\n")
			return 0
		}
		// replace the current network
		pNtkRes = Abc_NtkDupTransformMiter(pNtk)
		Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
		Abc_Print(1, "The miter (current network) is transformed by XORing POs pair-wise.\n")
		return 0
	}

	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1) {
		return 1
	}

	if fIgnoreNames != 0 {
		if !fDelete1 {
			pNtk1 = Abc_NtkStrash(pNtk1, 0, 1, 0)
			fDelete1 = 1
		}
		if !(fDelete2 != 0) {
			pNtk2 = Abc_NtkStrash(pNtk2, 0, 1, 0)
			fDelete2 = 1
		}
		Abc_NtkShortNames(pNtk1)
		Abc_NtkShortNames(pNtk2)
	}
	// compute the miter
	pNtkRes = Abc_NtkMiter(pNtk1, pNtk2, fComb, nPartSize, fImplic, fMulti)
	if fDelete1 != 0 {
		Abc_NtkDelete(pNtk1)
	}
	if fDelete2 != 0 {
		Abc_NtkDelete(pNtk2)
	}

	// get the new network
	if pNtkRes == nil {
		Abc_Print(-1, "Miter computation has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	if nPartSize == 0 {
		strcpy(Buffer, "unused")
	} else {
		Buffer = fmt.Sprintf("%d", nPartSize)
	}
	Abc_Print(-2, "usage: miter [-P <num>] [-cimtnh] <file1> <file2>\n")
	Abc_Print(-2, "\t           computes the miter of the two circuits\n")
	Abc_Print(-2, "\t-P <num> : output partition size [default = %s]\n", Buffer)
	Abc_Print(-2, "\t-c       : toggles deriving combinational miter (latches as POs) [default = %s]\n", abcSelect(fComb, "yes", "no"))
	Abc_Print(-2, "\t-i       : toggles deriving implication miter (file1 => file2) [default = %s]\n", abcSelect(fImplic, "yes", "no"))
	Abc_Print(-2, "\t-m       : toggles creating multi-output miter [default = %s]\n", abcSelect(fMulti, "yes", "no"))
	Abc_Print(-2, "\t-t       : toggle XORing pair-wise POs of the miter [default = %s]\n", abcSelect(fTrans, "yes", "no"))
	Abc_Print(-2, "\t-n       : toggle ignoring names when matching CIs/COs [default = %s]\n", abcSelect(fIgnoreNames, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	Abc_Print(-2, "\tfile1    : (optional) the file with the first network\n")
	Abc_Print(-2, "\tfile2    : (optional) the file with the second network\n")
	Abc_Print(-2, "\t           if no files are given, uses the current network and its spec\n")
	Abc_Print(-2, "\t           if one file is given, uses the current network and the file\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandMiter2(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtk, pNtkRes *Abc_Ntk_t
	var vNodes *Vec_Ptr_t
	var pFileName string
	var c, fVerbose int32
	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "vh"); c != -1; c = Extra_UtilGetopt(argc, argv, "vh") {
		switch c {
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	// get the second network
	if argc != globalUtilOptind+1 {
		Abc_Print(-1, "The file with node names is not given.\n")
		return 1
	}
	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "The base network should be logic network from BLIF file.\n")
		return 1
	}
	// read the second network
	pFileName = argv[globalUtilOptind]
	vNodes = Abc_NtkReadNodeNames(pNtk, pFileName)
	if vNodes == nil {
		Abc_Print(-1, "Cannot read node names from file \"%s\".\n", pFileName)
		return 1
	}
	pNtkRes = Abc_NtkSpecialMiter(pNtk, vNodes)
	Vec_PtrFree(vNodes)
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: miter2 [-h] <file>\n")
	Abc_Print(-2, "\t         derives specialized miter\n")
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t<file> : file name with node names\n")
	return 1
}

