/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDropSat(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pNtkRes *Abc_Ntk_t = nil
	var fNoSweep int32
	var c, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "svh"); c != -1; c = Extra_UtilGetopt(argc, argv, "svh") {
		switch c {
		case 's':
			fNoSweep ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			fallthrough
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for AIGs (run \"strash\").\n")
		return 1
	}
	if pAbc.vCexVec == nil {
		Abc_Print(-1, "CEX array is not defined. Run \"bmc3 -az\", \"sim3 -az\", or \"pdr -az\".\n")
		return 1
	}
	if Vec_PtrSize(pAbc.vCexVec) != Abc_NtkPoNum(pNtk) {
		Abc_Print(-1, "CEX array size (%d) does not match the number of outputs (%d).\n", Vec_PtrSize(pAbc.vCexVec), Abc_NtkPoNum(pNtk))
		return 1
	}
	Abc_NtkDropSatOutputs(pNtk, pAbc.vCexVec, fVerbose)
	if !(fNoSweep != 0) {
		pNtkRes = Abc_NtkDarLatchSweep(pNtk, 1, 1, 1, 0, -1, -1, 0, 0)
		if pNtkRes == nil {
			Abc_Print(-1, "Removing SAT outputs has failed.\n")
			return 1
		}
		Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	}
	return 0

usage:
	Abc_Print(-2, "usage: dropsat [-sh]\n")
	Abc_Print(-2, "\t         replaces satisfiable POs by constant 0 and cleans up the AIG\n")
	Abc_Print(-2, "\t-s     : toggles skipping sequential sweep [default = %s]\n", abcSelect(fNoSweep, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

