func Abc_CommandSop(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fMode int32 = -1
	var nCubeLimit int32 = 1000000

	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Cdnh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Cdnh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nCubeLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCubeLimit < 0 {
				goto usage
			}
			break
		case 'd':
			fMode = 1
			break
		case 'n':
			fMode = 0
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "Converting to SOP is possible only for logic networks.\n")
		return 1
	}
	if !Abc_NtkToSop(pNtk, fMode, nCubeLimit) {
		Abc_Print(-1, "Converting to SOP has failed.\n")
		return 0
	}
	return 0

usage:
	Abc_Print(-2, "usage: sop [-C num] [-dnh]\n")
	Abc_Print(-2, "\t         converts node functions to SOP\n")
	Abc_Print(-2, "\t-C num : the limit on the number of cubes at a node [default = %d]\n", nCubeLimit)
	Abc_Print(-2, "\t-d     : toggles using only positive polarity [default = %s]\n", abcSelectIf(fMode == 1, "yes", "no"))
	Abc_Print(-2, "\t-n     : toggles using only negative polarity [default = %s]\n", abcSelectIf(fMode == 0, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandBdd(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var fReorder int32 = 1
	var fBdd2Sop int32
	var c int32

	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "rsh"); c != -1; c = Extra_UtilGetopt(argc, argv, "rsh") {
		switch c {
		case 'r':
			fReorder ^= 1
			break
		case 's':
			fBdd2Sop ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "Converting to BDD is possible only for logic networks.\n")
		return 1
	}
	if (fBdd2Sop != 0) && Abc_NtkHasSop(pNtk) {
		return !Abc_NtkSopToBdd(pNtk)
	}
	if Abc_NtkIsBddLogic(pNtk) {
		Abc_Print(-1, "The logic network is already in the BDD form.\n")
		return 0
	}
	if !Abc_NtkToBdd(pNtk) {
		Abc_Print(-1, "Converting to BDD has failed.\n")
		return 1
	}
	return 0

usage:
	Abc_Print(-2, "usage: bdd [-rsh]\n")
	Abc_Print(-2, "\t         converts node functions to BDD\n")
	Abc_Print(-2, "\t-r     : toggles enabling dynamic variable reordering [default = %s]\n", abcSelect(fReorder, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggles constructing BDDs directly from SOPs [default = %s]\n", abcSelect(fBdd2Sop, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

