/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandOrder(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pFile *os.File
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pFileName string
	var c int32
	var fReverse int32
	var fVerbose int32

	// set defaults
	fReverse = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "rvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "rvh") {
		switch c {
		case 'r':
			fReverse ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	//    if ( Abc_NtkLatchNum(pNtk) > 0 )
	//    {
	//        Abc_Print( -1, "Currently this procedure does not work for sequential networks.\n" );
	//        return 1;
	//    }

	// if the var order file is given, implement this order
	pFileName = nil
	if argc == globalUtilOptind+1 {
		pFileName = argv[globalUtilOptind]
		pFile = os.Open(pFileName)
		if pFile == nil {
			Abc_Print(-1, "Cannot open file \"%s\" with the BDD variable order.\n", pFileName)
			return 1
		}
		_ = pFile.Close()
	}
	if pFileName != "" {
		Abc_NtkImplementCiOrder(pNtk, pFileName, fReverse, fVerbose)
	} else {
		Abc_NtkFindCiOrder(pNtk, fReverse, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: order [-rvh] <file>\n")
	Abc_Print(-2, "\t         computes a good static CI variable order\n")
	Abc_Print(-2, "\t-r     : toggle reverse ordering [default = %s]\n", abcSelect(fReverse, "yes", "no"))
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t<file> : (optional) file with the given variable order\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandMuxes(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var fGlobal int32
	var Limit int32 = 1000000
	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Bgh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Bgh") {
		switch c {
		case 'B':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-B\" should be followed by an integer.\n")
				goto usage
			}
			Limit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Limit < 0 {
				goto usage
			}
			break
		case 'g':
			fGlobal ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if fGlobal != 0 {
		if !Abc_NtkIsStrash(pNtk) {
			Abc_Print(-1, "The current network should be an AIG.\n")
			return 1
		}

	} else {
		if !Abc_NtkIsBddLogic(pNtk) {
			Abc_Print(-1, "Only a BDD logic network can be converted to MUXes.\n")
			return 1
		}
	}

	// get the new network
	pNtkRes = Abc_NtkBddToMuxes(pNtk, fGlobal, Limit)
	if pNtkRes == nil {
		Abc_Print(0, "Converting to MUXes has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: muxes [-B num] [-gh]\n")
	Abc_Print(-2, "\t          converts the current network into a network derived by\n")
	Abc_Print(-2, "\t          replacing all nodes by DAGs isomorphic to the local BDDs\n")
	Abc_Print(-2, "\t-B <num>: limit on live BDD nodes during collapsing [default = %d]\n", Limit)
	Abc_Print(-2, "\t-g      : toggle visualizing the global BDDs of primary outputs [default = %s].\n", abcSelect(fGlobal, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

