func Abc_CommandTopmost(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, nLevels int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	nLevels = 10
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Nh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Nh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nLevels = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLevels < 0 {
				goto usage
			}
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Currently only works for structurally hashed circuits.\n")
		return 0
	}

	if Abc_NtkLatchNum(pNtk) > 0 {
		Abc_Print(-1, "Currently only works for combinational circuits.\n")
		return 0
	}

	pNtkRes = Abc_NtkTopmost(pNtk, nLevels)
	if pNtkRes == nil {
		Abc_Print(-1, "The command has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: topmost [-N num] [-h]\n")
	Abc_Print(-2, "\t         replaces the current network by several of its topmost levels\n")
	Abc_Print(-2, "\t-N num : max number of levels [default = %d]\n", nLevels)
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\tname   : the node name\n")
	return 1
}

