/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandExdcSet(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pFile *os.File
	var err error
	var pNtk, pNtkNew, pNtkRes *Abc_Ntk_t
	var FileName string
	var c int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if argc != globalUtilOptind+1 {
		goto usage
	}

	// get the input file name
	FileName = argv[globalUtilOptind]
	pFile, err = os.Open(FileName)
	if err != nil {
		Abc_Print(-1, "Cannot open input file \"%s\". ", FileName)
		if similar := Extra_FileGetSimilarName(FileName, ".mv", ".blif", ".pla", ".eqn", ".bench"); similar != "" {
			Abc_Print(1, "Did you mean \"%s\"?", similar)
		}
		Abc_Print(1, "\n")
		return 1
	}
	_ = pFile.Close()

	// set the new network
	pNtkNew = Io_Read(FileName, Io_ReadFileType(FileName), 1, 0)
	if pNtkNew == nil {
		Abc_Print(-1, "Reading network from file has failed.\n")
		return 1
	}

	// replace the EXDC
	if pNtk.pExdc {
		Abc_NtkDelete(pNtk.pExdc)
		pNtk.pExdc = nil
	}
	pNtkRes = Abc_NtkDup(pNtk)
	pNtkRes.pExdc = pNtkNew

	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: exdc_set [-h] <file>\n")
	Abc_Print(-2, "\t         sets the network from file as EXDC for the current network\n")
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t<file> : file with the new EXDC network\n")
	return 1
}

