/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCut(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var Params Cut_Params_t
	var pParams *Cut_Params_t = &Params
	var pCutMan *Cut_Man_t
	var pCutOracle *Cut_Oracle_t = nil
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fOracle int32

	// set defaults
	fOracle = 0
	memset(pParams, 0, sizeof(Cut_Params_t))
	pParams.nVarsMax = 5    // the max cut size ("k" of the k-feasible cuts)
	pParams.nKeepMax = 1000 // the max number of cuts kept at a node
	pParams.fTruth = 1      // compute truth tables
	pParams.fFilter = 1     // filter dominated cuts
	pParams.fDrop = 0       // drop cuts on the fly
	pParams.fDag = 1        // compute DAG cuts
	pParams.fTree = 0       // compute tree cuts
	pParams.fGlobal = 0     // compute global cuts
	pParams.fLocal = 0      // compute local cuts
	pParams.fFancy = 0      // compute something fancy
	pParams.fRecordAig = 1  // compute something fancy
	pParams.fMap = 0        // compute mapping delay
	pParams.fAdjust = 0     // removes useless fanouts
	pParams.fNpnSave = 0    // enables dumping truth tables
	pParams.fVerbose = 0    // the verbosiness flag
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "KMtfdxyglzamjvosh"); c != -1; c = Extra_UtilGetopt(argc, argv, "KMtfdxyglzamjvosh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nVarsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nVarsMax < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nKeepMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nKeepMax < 0 {
				goto usage
			}
			break
		case 't':
			pParams.fTruth ^= 1
			break
		case 'f':
			pParams.fFilter ^= 1
			break
		case 'd':
			pParams.fDrop ^= 1
			break
		case 'x':
			pParams.fDag ^= 1
			break
		case 'y':
			pParams.fTree ^= 1
			break
		case 'g':
			pParams.fGlobal ^= 1
			break
		case 'l':
			pParams.fLocal ^= 1
			break
		case 'z':
			pParams.fFancy ^= 1
			break
		case 'a':
			pParams.fRecordAig ^= 1
			break
		case 'm':
			pParams.fMap ^= 1
			break
		case 'j':
			pParams.fAdjust ^= 1
			break
		case 'v':
			pParams.fVerbose ^= 1
			break
		case 'o':
			fOracle ^= 1
			break
		case 's':
			pParams.fNpnSave ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Cut computation is available only for AIGs (run \"strash\").\n")
		return 1
	}
	if pParams.nVarsMax < CUT_SIZE_MIN || pParams.nVarsMax > CUT_SIZE_MAX {
		Abc_Print(-1, "Can only compute the cuts for %d <= K <= %d.\n", CUT_SIZE_MIN, CUT_SIZE_MAX)
		return 1
	}
	if pParams.fDag && pParams.fTree {
		Abc_Print(-1, "Cannot compute both DAG cuts and tree cuts at the same time.\n")
		return 1
	}

	if pParams.fNpnSave {
		pParams.nVarsMax = 6
		pParams.fTruth = 1
	}

	if fOracle != 0 {
		pParams.fRecord = 1
	}
	pCutMan = Abc_NtkCuts(pNtk, pParams)
	if fOracle != 0 {
		pCutOracle = Cut_OracleStart(pCutMan)
	}
	Cut_ManStop(pCutMan)
	if fOracle != 0 {
		assert((pCutOracle != nil), "pCutOracle")
		Abc_NtkCutsOracle(pNtk, pCutOracle)
		Cut_OracleStop(pCutOracle)
	}
	return 0

usage:
	Abc_Print(-2, "usage: cut [-K num] [-M num] [-tfdcovamjsvh]\n")
	Abc_Print(-2, "\t         computes k-feasible cuts for the AIG\n")
	Abc_Print(-2, "\t-K num : max number of leaves (%d <= num <= %d) [default = %d]\n", CUT_SIZE_MIN, CUT_SIZE_MAX, pParams.nVarsMax)
	Abc_Print(-2, "\t-M num : max number of cuts stored at a node [default = %d]\n", pParams.nKeepMax)
	Abc_Print(-2, "\t-t     : toggle truth table computation [default = %s]\n", abcSelect(pParams.fTruth, "yes", "no"))
	Abc_Print(-2, "\t-f     : toggle filtering of duplicated/dominated [default = %s]\n", abcSelect(pParams.fFilter, "yes", "no"))
	Abc_Print(-2, "\t-d     : toggle dropping when fanouts are done [default = %s]\n", abcSelect(pParams.fDrop, "yes", "no"))
	Abc_Print(-2, "\t-x     : toggle computing only DAG cuts [default = %s]\n", abcSelect(pParams.fDag, "yes", "no"))
	Abc_Print(-2, "\t-y     : toggle computing only tree cuts [default = %s]\n", abcSelect(pParams.fTree, "yes", "no"))
	Abc_Print(-2, "\t-g     : toggle computing only global cuts [default = %s]\n", abcSelect(pParams.fGlobal, "yes", "no"))
	Abc_Print(-2, "\t-l     : toggle computing only local cuts [default = %s]\n", abcSelect(pParams.fLocal, "yes", "no"))
	Abc_Print(-2, "\t-z     : toggle fancy computations [default = %s]\n", abcSelect(pParams.fFancy, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggle recording cut functions [default = %s]\n", abcSelect(pParams.fRecordAig, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggle delay-oriented FPGA mapping [default = %s]\n", abcSelect(pParams.fMap, "yes", "no"))
	Abc_Print(-2, "\t-j     : toggle removing fanouts due to XOR/MUX [default = %s]\n", abcSelect(pParams.fAdjust, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle creating library of 6-var functions [default = %s]\n", abcSelect(pParams.fNpnSave, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandScut(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var Params Cut_Params_t
	var pParams *Cut_Params_t = &Params
	var pCutMan *Cut_Man_t
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32

	// set defaults
	memset(pParams, 0, sizeof(Cut_Params_t))
	pParams.nVarsMax = 5    // the max cut size ("k" of the k-feasible cuts)
	pParams.nKeepMax = 1000 // the max number of cuts kept at a node
	pParams.fTruth = 0      // compute truth tables
	pParams.fFilter = 1     // filter dominated cuts
	pParams.fSeq = 1        // compute sequential cuts
	pParams.fVerbose = 0    // the verbosiness flag
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "KMtvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "KMtvh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nVarsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nVarsMax < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nKeepMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nKeepMax < 0 {
				goto usage
			}
			break
		case 't':
			pParams.fTruth ^= 1
			break
		case 'v':
			pParams.fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	/*
	   if ( !Abc_NtkIsSeq(pNtk) )
	   {
	       Abc_Print( -1, "Sequential cuts can be computed for sequential AIGs (run \"seq\").\n" );
	       return 1;
	   }
	*/
	if pParams.nVarsMax < CUT_SIZE_MIN || pParams.nVarsMax > CUT_SIZE_MAX {
		Abc_Print(-1, "Can only compute the cuts for %d <= K <= %d.\n", CUT_SIZE_MIN, CUT_SIZE_MAX)
		return 1
	}

	pCutMan = Abc_NtkSeqCuts(pNtk, pParams)
	Cut_ManStop(pCutMan)
	return 0

usage:
	Abc_Print(-2, "usage: scut [-K num] [-M num] [-tvh]\n")
	Abc_Print(-2, "\t         computes k-feasible cuts for the sequential AIG\n")
	Abc_Print(-2, "\t-K num : max number of leaves (%d <= num <= %d) [default = %d]\n", CUT_SIZE_MIN, CUT_SIZE_MAX, pParams.nVarsMax)
	Abc_Print(-2, "\t-M num : max number of cuts stored at a node [default = %d]\n", pParams.nKeepMax)
	Abc_Print(-2, "\t-t     : toggle truth table computation [default = %s]\n", abcSelect(pParams.fTruth, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandEspresso(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fVerbose int32

	if argc == 2 && !(int32(strings.Compare(argv[1], "-h")) != 0) {
		Abc_Print(-2, "The espresso command is currently disabled.\n")
		return 1
	}

	Abc_Print(-1, "This command is currently disabled.\n")
	return 0

	// set defaults
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "vh"); c != -1; c = Extra_UtilGetopt(argc, argv, "vh") {
		switch c {
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "SOP minimization is possible for logic networks (run \"renode\").\n")
		return 1
	}
	//    Abc_NtkEspresso( pNtk, fVerbose );
	return 0

usage:
	Abc_Print(-2, "usage: espresso [-vh]\n")
	Abc_Print(-2, "\t         minimizes SOPs of the local functions using Espresso\n")
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandGen(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	//    Abc_Ntk_t * pNtk = Abc_FrameReadNtk(pAbc);
	var c int32
	var nVars int32         // the number of variables
	var nArgs int32         // the number of arguments
	var nLutSize int32 = -1 // the size of LUTs
	var nLuts int32 = -1    // the number of LUTs
	var fAdder int32
	var fAdderTree int32
	var fSorter int32
	var fMesh int32
	var fMulti int32
	var fBooth int32
	var fFpga int32
	var fOneHot int32
	var fRandom int32
	var fVerbose int32
	var FileName string
	var Command string // was [1000]byte in C

	// set defaults
	nVars = 8
	nArgs = 8
	fAdder = 0
	fAdderTree = 0
	fSorter = 0
	fMesh = 0
	fMulti = 0
	fBooth = 0
	fFpga = 0
	fOneHot = 0
	fRandom = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NAKLatsembfnrvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NAKLatsembfnrvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nVars < 0 {
				goto usage
			}
			break
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by an integer.\n")
				goto usage
			}
			nArgs = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nArgs < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nLutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLutSize < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nLuts = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLuts < 0 {
				goto usage
			}
			break
		case 'a':
			fAdder ^= 1
			break
		case 't':
			fAdderTree ^= 1
			break
		case 's':
			fSorter ^= 1
			break
		case 'e':
			fMesh ^= 1
			break
		case 'm':
			fMulti ^= 1
			break
		case 'b':
			fBooth ^= 1
			break
		case 'f':
			fFpga ^= 1
			break
		case 'n':
			fOneHot ^= 1
			break
		case 'r':
			fRandom ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if argc != globalUtilOptind+1 {
		goto usage
	}
	if nVars < 1 {
		Abc_Print(-1, "The number of variables should be a positive integer.\n")
		return 0
	}
	// get the input file name
	FileName = argv[globalUtilOptind]
	if fAdder != 0 {
		Abc_GenAdder(FileName, nVars)
	} else if fSorter != 0 {
		Abc_GenSorter(FileName, nVars)
	} else if fMesh != 0 {
		Abc_GenMesh(FileName, nVars)
	} else if fMulti != 0 {
		Abc_GenMulti(FileName, nVars)
	} else if fBooth != 0 {
		Abc_GenBooth(FileName, nVars)
	} else if fFpga != 0 {
		Abc_GenFpga(FileName, nLutSize, nLuts, nVars)
		//        Abc_GenFpga( FileName, 2, 2, 3 );
		//        Abc_GenFpga( FileName, 3, 2, 5 );
	} else if fOneHot != 0 {
		Abc_GenOneHot(FileName, nVars)
	} else if fRandom != 0 {
		Abc_GenRandom(FileName, nVars)
	} else if fAdderTree != 0 {
		fmt.Printf("Generating adder tree with %d arguments and %d bits.\n", nArgs, nVars)
		Abc_GenAdderTree(FileName, nArgs, nVars)
		Command = fmt.Sprintf("%%read %s; %%blast; &put", FileName)
		Cmd_CommandExecute(pAbc, Command)
		return 0

	} else {
		Abc_Print(-1, "Type of circuit is not specified.\n")
		return 0
	}
	// read the file just produced
	Command = fmt.Sprintf("read %s", FileName)
	Cmd_CommandExecute(pAbc, Command)
	return 0

usage:
	Abc_Print(-2, "usage: gen [-NAKL num] [-atsembfnrvh] <file>\n")
	Abc_Print(-2, "\t         generates simple circuits\n")
	Abc_Print(-2, "\t-N num : the number of variables [default = %d]\n", nVars)
	Abc_Print(-2, "\t-A num : the number of agruments (for adder tree) [default = %d]\n", nArgs)
	Abc_Print(-2, "\t-K num : the LUT size (to be used with switch -f) [default = %d]\n", nLutSize)
	Abc_Print(-2, "\t-L num : the LUT count (to be used with switch -f) [default = %d]\n", nLuts)
	Abc_Print(-2, "\t-a     : generate ripple-carry adder [default = %s]\n", abcSelect(fAdder, "yes", "no"))
	Abc_Print(-2, "\t-t     : generate an adder tree [default = %s]\n", abcSelect(fAdderTree, "yes", "no"))
	Abc_Print(-2, "\t-s     : generate a sorter [default = %s]\n", abcSelect(fSorter, "yes", "no"))
	Abc_Print(-2, "\t-e     : generate a mesh [default = %s]\n", abcSelect(fMesh, "yes", "no"))
	Abc_Print(-2, "\t-m     : generate a multiplier [default = %s]\n", abcSelect(fMulti, "yes", "no"))
	Abc_Print(-2, "\t-b     : generate a signed Booth multiplier [default = %s]\n", abcSelect(fBooth, "yes", "no"))
	Abc_Print(-2, "\t-f     : generate a LUT FPGA structure [default = %s]\n", abcSelect(fFpga, "yes", "no"))
	Abc_Print(-2, "\t-n     : generate one-hotness conditions [default = %s]\n", abcSelect(fOneHot, "yes", "no"))
	Abc_Print(-2, "\t-r     : generate random single-output function [default = %s]\n", abcSelect(fRandom, "yes", "no"))
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t<file> : output file name\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandGenFsm(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c, nIns, nOuts, nStates, nLines, ProbI, ProbO, fVerbose int32
	var FileName string
	// set defaults
	nIns = 30
	nOuts = 1
	nStates = 20
	nLines = 100
	ProbI = 10
	ProbO = 100
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "IOSLPQvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "IOSLPQvh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nIns = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nIns < 0 {
				goto usage
			}
			break
		case 'O':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-O\" should be followed by an integer.\n")
				goto usage
			}
			nOuts = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nOuts < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			nStates = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nStates < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nLines = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLines < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			ProbI = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if ProbI < 0 {
				goto usage
			}
			break
		case 'Q':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-Q\" should be followed by an integer.\n")
				goto usage
			}
			ProbO = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if ProbO < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if argc != globalUtilOptind+1 {
		goto usage
	}
	if nIns < 1 || nStates < 1 || nLines < 1 || ProbI < 1 || ProbO < 1 {
		Abc_Print(-1, "The number of inputs. states, lines, and probablity should be positive integers.\n")
		goto usage
	}
	// get the input file name
	FileName = argv[globalUtilOptind]
	Abc_GenFsm(FileName, nIns, nOuts, nStates, nLines, ProbI, ProbO)
	return 0

usage:
	Abc_Print(-2, "usage: genfsm [-IOSLPQ num] [-vh] <file>\n")
	Abc_Print(-2, "\t         generates random FSM in KISS format\n")
	Abc_Print(-2, "\t-I num : the number of input variables [default = %d]\n", nIns)
	Abc_Print(-2, "\t-O num : the number of output variables [default = %d]\n", nOuts)
	Abc_Print(-2, "\t-S num : the number of state variables [default = %d]\n", nStates)
	Abc_Print(-2, "\t-L num : the number of lines (product terms) [default = %d]\n", nLines)
	Abc_Print(-2, "\t-P num : percentage propability of a variable present in the input cube [default = %d]\n", ProbI)
	Abc_Print(-2, "\t-Q num : percentage propability of a variable present in the output cube [default = %d]\n", ProbO)
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t<file> : output file name\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCover(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var fVerbose int32
	var fUseSop int32
	var fUseEsop int32
	var fUseInvs int32
	var nFaninMax int32
	var nCubesMax int32
	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	fUseSop = 1
	fUseEsop = 0
	fVerbose = 0
	fUseInvs = 1
	nFaninMax = 8
	nCubesMax = 8
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "IPsxivh"); c != -1; c = Extra_UtilGetopt(argc, argv, "IPsxivh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nFaninMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFaninMax < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nCubesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCubesMax < 0 {
				goto usage
			}
			break
		case 's':
			fUseSop ^= 1
			break
		case 'x':
			fUseEsop ^= 1
			break
		case 'i':
			fUseInvs ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Only works for strashed networks.\n")
		return 1
	}

	// run the command
	pNtkRes = Abc_NtkSopEsopCover(pNtk, nFaninMax, nCubesMax, fUseEsop, fUseSop, fUseInvs, fVerbose)
	if pNtkRes == nil {
		Abc_Print(-1, "Command has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: cover [-IP num] [-sxvh]\n")
	Abc_Print(-2, "\t         decomposition into a network of SOP/ESOP PLAs\n")
	Abc_Print(-2, "\t         (this command is known to have bugs)\n")
	Abc_Print(-2, "\t-I num : maximum number of inputs [default = %d]\n", nFaninMax)
	Abc_Print(-2, "\t-P num : maximum number of products [default = %d]\n", nCubesMax)
	Abc_Print(-2, "\t-s     : toggle the use of SOPs [default = %s]\n", abcSelect(fUseSop, "yes", "no"))
	Abc_Print(-2, "\t-x     : toggle the use of ESOPs [default = %s]\n", abcSelect(fUseEsop, "yes", "no"))
	//    Abc_Print( -2, "\t-i     : toggle the use of interters [default = %s]\n", abcSelect(fUseInvs, "yes", "no") );
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandInter(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t
	var pNtk1 *Abc_Ntk_t
	var pNtk2 *Abc_Ntk_t
	var pNtkRes *Abc_Ntk_t = nil
	var pArgvNew *string
	var nArgcNew int32
	var c, fDelete1, fDelete2 int32
	var fRelation int32
	var fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fRelation = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "rvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "rvh") {
		switch c {
		case 'r':
			fRelation ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1) {
		return 1
	}
	if nArgcNew == 0 {
		var pObj *Abc_Obj_t
		var i int32
		Abc_Print(-1, "Deriving new circuit structure for the current network.\n")
		Abc_NtkForEachPo(pNtk2, pObj, i)
		Abc_ObjXorFaninC(pObj, 0)
	}
	if (fRelation != 0) && Abc_NtkCoNum(pNtk1) != 1 {
		Abc_Print(-1, "Computation of interplants as a relation only works for single-output functions.\n")
		Abc_Print(-1, "Use command \"cone\" to extract one output cone from the multi-output network.\n")

	} else {
		pNtkRes = Abc_NtkInter(pNtk1, pNtk2, fRelation, fVerbose)
	}
	if fDelete1 != 0 {
		Abc_NtkDelete(pNtk1)
	}
	if fDelete2 != 0 {
		Abc_NtkDelete(pNtk2)
	}

	if pNtkRes == nil {
		Abc_Print(-1, "Command has failed.\n")
		return 0
	}
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: inter [-rvh] <onset.blif> <offset.blif>\n")
	Abc_Print(-2, "\t         derives interpolant of two networks representing onset and offset;\n")
	Abc_Print(-2, "\t-r     : toggle computing interpolant as a relation [default = %s]\n", abcSelect(fRelation, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t         \n")
	Abc_Print(-2, "\t         Comments:\n")
	Abc_Print(-2, "\t         \n")
	Abc_Print(-2, "\t         The networks given on the command line should have the same CIs/COs.\n")
	Abc_Print(-2, "\t         If only one network is given on the command line, this network\n")
	Abc_Print(-2, "\t         is assumed to be the offset, while the current network is the onset.\n")
	Abc_Print(-2, "\t         If no network is given on the command line, the current network is\n")
	Abc_Print(-2, "\t         assumed to be the onset and its complement is taken to be the offset.\n")
	Abc_Print(-2, "\t         The resulting interpolant is stored as the current network.\n")
	Abc_Print(-2, "\t         To verify that the interpolant agrees with the onset and the offset,\n")
	Abc_Print(-2, "\t         save it in file \"inter.blif\" and run the following:\n")
	Abc_Print(-2, "\t         (a) \"miter -i <onset.blif> <inter.blif>; iprove\"\n")
	Abc_Print(-2, "\t         (b) \"miter -i <inter.blif> <offset_inv.blif>; iprove\"\n")
	Abc_Print(-2, "\t         where <offset_inv.blif> is the network derived by complementing the\n")
	Abc_Print(-2, "\t         outputs of <offset.blif>: \"r <offset.blif>; st -i; w <offset_inv.blif>\"\n")
	return 1
}

