func Abc_CommandBb2Wb(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var fSeq int32
	var fVerbose int32
	// set defaults
	fSeq = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "svh"); c != -1; c = Extra_UtilGetopt(argc, argv, "svh") {
		switch c {
		case 's':
			fSeq ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		default:
			goto usage
		}
	}
	if argc != globalUtilOptind+2 {
		Abc_Print(-1, "Expecting two files names on the command line.\n")
		goto usage
	}
	Abc_NtkConvertBb2Wb(argv[globalUtilOptind], argv[globalUtilOptind+1], fSeq, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: bb2wb [-svh] <file_in> <file_out>\n")
	Abc_Print(-2, "\t             replaces black boxes by white boxes with AND functions\n")
	Abc_Print(-2, "\t             (file names should have standard extensions, e.g. \"blif\")\n")
	Abc_Print(-2, "\t-s         : toggle using sequential white boxes [default = %s]\n", abcSelect(fSeq, "yes", "no"))
	Abc_Print(-2, "\t-v         : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h         : print the command usage\n")
	Abc_Print(-2, "\t<file_in>  : input file with design containing black boxes\n")
	Abc_Print(-2, "\t<file_out> : output file with design containing white boxes\n")
	return 1
}

