/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandQuaVar(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, iVar, fUniv, fVerbose, RetValue int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	iVar = 0
	fUniv = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Iuvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Iuvh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			iVar = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iVar < 0 {
				goto usage
			}
			break
		case 'u':
			fUniv ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "This command cannot be applied to an AIG with choice nodes.\n")
		return 1
	}

	// get the strashed network
	pNtkRes = Abc_NtkStrash(pNtk, 0, 1, 0)
	RetValue = Abc_NtkQuantify(pNtkRes, fUniv, iVar, fVerbose)
	// clean temporary storage for the cofactors
	Abc_NtkCleanData(pNtkRes)
	if pMan, ok := pNtkRes.FunctionManager.(*Abc_Aig_t); ok {
		Abc_AigCleanup(pMan)
	}
	// check the result
	if !(RetValue != 0) {
		Abc_Print(-1, "Command has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: qvar [-I num] [-uvh]\n")
	Abc_Print(-2, "\t         quantifies one variable using the AIG\n")
	Abc_Print(-2, "\t-I num : the zero-based index of a variable to quantify [default = %d]\n", iVar)
	Abc_Print(-2, "\t-u     : toggle universal quantification [default = %s]\n", abcSelect(fUniv, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandQuaRel(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, iVar, fInputs, fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	iVar = 0
	fInputs = 1
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Iqvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Iqvh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			iVar = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iVar < 0 {
				goto usage
			}
			break
		case 'q':
			fInputs ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "This command cannot be applied to an AIG with choice nodes.\n")
		return 1
	}
	if Abc_NtkIsComb(pNtk) {
		Abc_Print(-1, "This command works only for sequential circuits.\n")
		return 1
	}

	// get the strashed network
	if !Abc_NtkIsStrash(pNtk) {
		pNtk = Abc_NtkStrash(pNtk, 0, 1, 0)
		pNtkRes = Abc_NtkTransRel(pNtk, fInputs, fVerbose)
		Abc_NtkDelete(pNtk)

	} else {
		pNtkRes = Abc_NtkTransRel(pNtk, fInputs, fVerbose)
	}
	// check if the result is available
	if pNtkRes == nil {
		Abc_Print(-1, "Command has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: qrel [-qvh]\n")
	Abc_Print(-2, "\t         computes transition relation of the sequential network\n")
	//    Abc_Print( -2, "\t-I num : the zero-based index of a variable to quantify [default = %d]\n", iVar );
	Abc_Print(-2, "\t-q     : perform quantification of inputs [default = %s]\n", abcSelect(fInputs, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandQuaReach(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, nIters, fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	nIters = 256
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Ivh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Ivh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nIters = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nIters < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "This command cannot be applied to an AIG with choice nodes.\n")
		return 1
	}
	if !Abc_NtkIsComb(pNtk) {
		Abc_Print(-1, "This command works only for combinational transition relations.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for strashed networks.\n")
		return 1
	}
	if Abc_NtkPoNum(pNtk) > 1 {
		Abc_Print(-1, "The transition relation should have one output.\n")
		return 1
	}
	if Abc_NtkPiNum(pNtk)%2 != 0 {
		Abc_Print(-1, "The transition relation should have an even number of inputs.\n")
		return 1
	}

	pNtkRes = Abc_NtkReachability(pNtk, nIters, fVerbose)
	if pNtkRes == nil {
		Abc_Print(-1, "Command has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: qreach [-I num] [-vh]\n")
	Abc_Print(-2, "\t         computes unreachable states using AIG-based quantification\n")
	Abc_Print(-2, "\t         assumes that the current network is a transition relation\n")
	Abc_Print(-2, "\t         assumes that the initial state is composed of all zeros\n")
	Abc_Print(-2, "\t-I num : the number of image computations to perform [default = %d]\n", nIters)
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

