func Abc_CommandDRefactor(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var Pars Dar_RefPar_t
	var pPars *Dar_RefPar_t = &Pars
	var c int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Dar_ManDefaultRefParams(pPars)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "MKCelzvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "MKCelzvwh") {
		switch c {
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nMffcMin = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nMffcMin < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nLeafMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nLeafMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nCutsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nCutsMax < 0 {
				goto usage
			}
			break
		case 'e':
			pPars.fExtend ^= 1
			break
		case 'l':
			pPars.fUpdateLevel ^= 1
			break
		case 'z':
			pPars.fUseZeros ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		case 'w':
			pPars.fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for strashed networks.\n")
		return 1
	}
	if pPars.nLeafMax < 4 || pPars.nLeafMax > 15 {
		Abc_Print(-1, "This command only works for cut sizes 4 <= K <= 15.\n")
		return 1
	}
	pNtkRes = Abc_NtkDRefactor(pNtk, pPars)
	if pNtkRes == nil {
		Abc_Print(-1, "Command has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: drf [-M num] [-K num] [-C num] [-elzvwh]\n")
	Abc_Print(-2, "\t         performs combinational AIG refactoring\n")
	Abc_Print(-2, "\t-M num : the min MFFC size to attempt refactoring [default = %d]\n", pPars.nMffcMin)
	Abc_Print(-2, "\t-K num : the max number of cuts leaves [default = %d]\n", pPars.nLeafMax)
	Abc_Print(-2, "\t-C num : the max number of cuts to try at a node [default = %d]\n", pPars.nCutsMax)
	Abc_Print(-2, "\t-e     : toggle extending tbe cut below MFFC [default = %s]\n", abcSelect(fExtend, "yes", "no"))
	Abc_Print(-2, "\t-l     : toggle preserving the number of levels [default = %s]\n", abcSelect(fUpdateLevel, "yes", "no"))
	Abc_Print(-2, "\t-z     : toggle using zero-cost replacements [default = %s]\n", abcSelect(fUseZeros, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggle very verbose printout [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

