/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCSweep(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, nCutsMax, nLeafMax, fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	nCutsMax = 8
	nLeafMax = 6
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CKvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "CKvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nCutsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCutsMax < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nLeafMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLeafMax < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if nCutsMax < 2 {
		Abc_Print(-1, "The number of cuts cannot be less than 2.\n")
		return 1
	}

	if nLeafMax < 3 || nLeafMax > 16 {
		Abc_Print(-1, "The number of leaves is infeasible.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for strashed networks.\n")
		return 1
	}

	pNtkRes = Abc_NtkCSweep(pNtk, nCutsMax, nLeafMax, fVerbose)
	if pNtkRes == nil {
		Abc_Print(-1, "Command has failed.\n")
		return 0
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: csweep [-C num] [-K num] [-vh]\n")
	Abc_Print(-2, "\t         performs cut sweeping using a new method\n")
	Abc_Print(-2, "\t-C num : limit on the number of cuts (C >= 2) [default = %d]\n", nCutsMax)
	Abc_Print(-2, "\t-K num : limit on the cut size (3 <= K <= 16) [default = %d]\n", nLeafMax)
	Abc_Print(-2, "\t-v     : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandIProve(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var Params Prove_Params_t
	var pParams *Prove_Params_t = &Params
	var pNtk, pNtkTemp *Abc_Ntk_t
	var c int32
	var RetValue int32
	var iOut int32 = -1
	var pLogFileName string
	var clk abctime

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Prove_ParamsSetDefault(pParams)
	pParams.fUseRewriting = 1
	pParams.fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NCFGMILrfbvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NCFGMILrfbvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nItersMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nItersMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nMiteringLimitStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nMiteringLimitStart < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nFraigingLimitStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nFraigingLimitStart < 0 {
				goto usage
			}
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nFraigingLimitMulti = float32(abcAtoi(argv[globalUtilOptind]))
			globalUtilOptind++
			if pParams.nFraigingLimitMulti < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nMiteringLimitLast = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nMiteringLimitLast < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nTotalInspectLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nTotalInspectLimit < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a file name.\n")
				goto usage
			}
			pLogFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'r':
			pParams.fUseRewriting ^= 1
			break
		case 'f':
			pParams.fUseFraiging ^= 1
			break
		case 'b':
			pParams.fUseBdds ^= 1
			break
		case 'v':
			pParams.fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if Abc_NtkLatchNum(pNtk) > 0 {
		Abc_Print(-1, "The network has registers. Use \"dprove\".\n")
		return 1
	}

	clk = Abc_Clock()

	if Abc_NtkIsStrash(pNtk) {
		pNtkTemp = Abc_NtkDup(pNtk)
	} else {
		pNtkTemp = Abc_NtkStrash(pNtk, 0, 0, 0)
	}

	RetValue = Abc_NtkIvyProve(&pNtkTemp, pParams)

	// verify that the pattern is correct
	if RetValue == 0 {
		var pObj *Abc_Obj_t
		var i int32
		var pSimInfo *int32 = Abc_NtkVerifySimulatePattern(pNtk, pNtkTemp.pModel)
		for i = 0; i < Abc_NtkCoNum(pNtk); i++ {
			pObj = Abc_NtkCo(pNtk, i)
			if pSimInfo[i] == 1 {
				iOut = i
				break
			}
		}
		if i == Abc_NtkCoNum(pNtk) {
			Abc_Print(1, "ERROR in Abc_NtkMiterProve(): Generated counter-example is invalid.\n")
		}
		ABC_FREE(pSimInfo)
	}
	pAbc.Status = RetValue
	if RetValue == -1 {
		Abc_Print(1, "UNDECIDED      ")
	} else if RetValue == 0 {
		Abc_Print(1, "SATISFIABLE (output = %d) ", iOut)
	} else {
		Abc_Print(1, "UNSATISFIABLE  ")
	}
	//Abc_Print( -1, "\n" );

	Abc_PrintTime(1, "Time", Abc_Clock()-clk)
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkTemp)
	// update counter example
	if RetValue == 0 && Abc_NtkLatchNum(pNtkTemp) == 0 {
		var pCex *Abc_Cex_t = Abc_CexDeriveFromCombModel(pNtkTemp.pModel, Abc_NtkPiNum(pNtkTemp), 0, iOut)
		Abc_FrameReplaceCex(pAbc, &pCex)
	}
	if pLogFileName != "" {
		Abc_NtkWriteLogFile(pLogFileName, pAbc.pCex, pAbc.Status, pAbc.nFrames, "iprove")
	}
	return 0

usage:
	Abc_Print(-2, "usage: iprove [-NCFGMI num] [-L file] [-rfbvh]\n")
	Abc_Print(-2, "\t         performs CEC using a new method\n")
	Abc_Print(-2, "\t-N num : max number of iterations [default = %d]\n", pParams.nItersMax)
	Abc_Print(-2, "\t-C num : max starting number of conflicts in mitering [default = %d]\n", pParams.nMiteringLimitStart)
	Abc_Print(-2, "\t-F num : max starting number of conflicts in fraiging [default = %d]\n", pParams.nFraigingLimitStart)
	Abc_Print(-2, "\t-G num : multiplicative coefficient for fraiging [default = %d]\n", int32(pParams.nFraigingLimitMulti))
	Abc_Print(-2, "\t-M num : max last-gasp number of conflicts in mitering [default = %d]\n", pParams.nMiteringLimitLast)
	Abc_Print(-2, "\t-I num : max number of clause inspections in all SAT calls [default = %d]\n", int32(pParams.nTotalInspectLimit))
	Abc_Print(-2, "\t-L file: the log file name [default = %s]\n", abcDefaultString(pLogFileName, "no logging"))
	Abc_Print(-2, "\t-r     : toggle the use of rewriting [default = %s]\n", abcSelect(fUseRewriting, "yes", "no"))
	Abc_Print(-2, "\t-f     : toggle the use of FRAIGing [default = %s]\n", abcSelect(fUseFraiging, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggle the use of BDDs [default = %s]\n", abcSelect(fUseBdds, "yes", "no"))
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

