/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSendAig(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	//    const int BRIDGE_NETLIST = 106;
	//    const int BRIDGE_ABS_NETLIST = 107;

	var c int32
	var fAndSpace int32 = 1
	var fAbsNetlist int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ah"); c != -1; c = Extra_UtilGetopt(argc, argv, "ah") {
		switch c {
		case 'a':
			fAndSpace ^= 1
			break
		case 'b':
			fAbsNetlist ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if !Abc_FrameIsBridgeMode() {
		Abc_Print(-1, "The bridge mode is not available.\n")
		return 1
	}
	if fAndSpace != 0 {
		if pAbc.pGia == nil {
			Abc_Print(-1, "There is no AIG in the &-space.\n")
			return 1
		}
		mode := BRIDGE_NETLIST
		if fAbsNetlist != 0 {
			mode = BRIDGE_ABS_NETLIST
		}
		Gia_ManToBridgeAbsNetlist(os.Stdout, pAbc.pGia, mode)

	} else {
		var pAig *Aig_Man_t
		var pGia *Gia_Man_t
		if pAbc.pNtkCur == nil {
			Abc_Print(-1, "There is no network in the main-space.\n")
			return 1
		}
		if !Abc_NtkIsStrash(pAbc.pNtkCur) {
			Abc_Print(-1, "The main-space network is not an AIG.\n")
			return 1
		}
		pAig = Abc_NtkToDar(pAbc.pNtkCur, 0, 1)
		pGia = Gia_ManFromAig(pAig)
		Aig_ManStop(pAig)
		mode := BRIDGE_NETLIST
		if fAbsNetlist != 0 {
			mode = BRIDGE_ABS_NETLIST
		}
		Gia_ManToBridgeAbsNetlist(os.Stdout, pGia, mode)
		Gia_ManStop(pGia)
	}
	return 0

usage:
	Abc_Print(-2, "usage: send_aig -a\n")
	Abc_Print(-2, "\t         sends current AIG to the bridge\n")
	Abc_Print(-2, "\t-a     : toggle sending AIG from &-space [default = %s]\n", abcSelect(fAndSpace, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggle sending netlist tagged as \"abstraction\". [default = %s]\n", abcSelect(fAbsNetlist, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

