/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandFraig(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var Buffer string // was [100]byte in C

	var Params Fraig_Params_t
	var pParams *Fraig_Params_t = &Params
	var pNtk, pNtkRes *Abc_Ntk_t
	var fAllNodes int32
	var fExdc int32
	var c int32
	var fPartition int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fExdc = 0
	fAllNodes = 0
	memset(pParams, 0, sizeof(Fraig_Params_t))
	pParams.nPatsRand = 2048 // the number of words of random simulation info
	pParams.nPatsDyna = 2048 // the number of words of dynamic simulation info
	pParams.nBTLimit = 100   // the max number of backtracks to perform
	pParams.fFuncRed = 1     // performs only one level hashing
	pParams.fFeedBack = 1    // enables solver feedback
	pParams.fDist1Pats = 1   // enables distance-1 patterns
	pParams.fDoSparse = 1    // performs equiv tests for sparse functions
	pParams.fChoicing = 0    // enables recording structural choices
	pParams.fTryProve = 0    // tries to solve the final miter
	pParams.fVerbose = 0     // the verbosiness flag
	pParams.fVerboseP = 0    // the verbosiness flag
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "RDCrscptvaeh"); c != -1; c = Extra_UtilGetopt(argc, argv, "RDCrscptvaeh") {
		switch c {
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nPatsRand = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nPatsRand < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nPatsDyna = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nPatsDyna < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nBTLimit < 0 {
				goto usage
			}
			break

		case 'r':
			pParams.fFuncRed ^= 1
			break
		case 's':
			pParams.fDoSparse ^= 1
			break
		case 'c':
			pParams.fChoicing ^= 1
			break
		case 'p':
			pParams.fTryProve ^= 1
			break
		case 'v':
			pParams.fVerbose ^= 1
			break
		case 't':
			fPartition ^= 1
			break
		case 'a':
			fAllNodes ^= 1
			break
		case 'e':
			fExdc ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsLogic(pNtk) && !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Can only fraig a logic network or an AIG.\n")
		return 1
	}

	// report the proof
	pParams.fVerboseP = pParams.fTryProve

	// get the new network
	if fPartition != 0 {
		pNtkRes = Abc_NtkDup(pNtk)
		if Abc_NtkIsStrash(pNtk) {
			Abc_NtkFraigPartitionedTime(pNtk, &Params)
		} else {
			pNtk = Abc_NtkStrash(pNtk, fAllNodes, !fAllNodes, 0)
			Abc_NtkFraigPartitionedTime(pNtk, &Params)
			Abc_NtkDelete(pNtk)
		}

	} else {
		if Abc_NtkIsStrash(pNtk) {
			pNtkRes = Abc_NtkFraig(pNtk, &Params, fAllNodes, fExdc)
		} else {
			pNtk = Abc_NtkStrash(pNtk, fAllNodes, !fAllNodes, 0)
			pNtkRes = Abc_NtkFraig(pNtk, &Params, fAllNodes, fExdc)
			Abc_NtkDelete(pNtk)
		}
	}
	if pNtkRes == nil {
		Abc_Print(-1, "Fraiging has failed.\n")
		return 1
	}

	if pParams.fTryProve { // report the result
		Abc_NtkMiterReport(pNtkRes)
	}

	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Buffer = fmt.Sprintf("%d", pParams.nBTLimit)
	Abc_Print(-2, "usage: fraig [-R num] [-D num] [-C num] [-rscpvtah]\n")
	Abc_Print(-2, "\t         transforms a logic network into a functionally reduced AIG\n")
	Abc_Print(-2, "\t         (known bugs: takes an UNSAT miter and returns a SAT one)\n")
	Abc_Print(-2, "\t         (there are newer fraiging commands, \"ifraig\" and \"dfraig\")\n")
	Abc_Print(-2, "\t-R num : number of random patterns (127 < num < 32769) [default = %d]\n", pParams.nPatsRand)
	Abc_Print(-2, "\t-D num : number of systematic patterns (127 < num < 32769) [default = %d]\n", pParams.nPatsDyna)
	backtrackLimit := Buffer
	if pParams.nBTLimit == -1 {
		backtrackLimit = "infinity"
	}
	Abc_Print(-2, "\t-C num : number of backtracks for one SAT problem [default = %s]\n", backtrackLimit)
	Abc_Print(-2, "\t-r     : toggle functional reduction [default = %s]\n", abcSelect(fFuncRed, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle considering sparse functions [default = %s]\n", abcSelect(fDoSparse, "yes", "no"))
	Abc_Print(-2, "\t-c     : toggle accumulation of choices [default = %s]\n", abcSelect(fChoicing, "yes", "no"))
	Abc_Print(-2, "\t-p     : toggle proving the miter outputs [default = %s]\n", abcSelect(fTryProve, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(pParams.fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-e     : toggle functional sweeping using EXDC [default = %s]\n", abcSelect(fExdc, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggle between all nodes and DFS nodes [default = %s]\n", abcSelect(fAllNodes, "all", "dfs"))
	Abc_Print(-2, "\t-t     : toggle using partitioned representation [default = %s]\n", abcSelect(fPartition, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandFraigTrust(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var fDuplicate int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fDuplicate = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "dh"); c != -1; c = Extra_UtilGetopt(argc, argv, "dh") {
		switch c {
		case 'd':
			fDuplicate ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	// get the new network
	pNtkRes = Abc_NtkFraigTrust(pNtk)
	if pNtkRes == nil {
		Abc_Print(-1, "Fraiging in the trust mode has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: fraig_trust [-h]\n")
	Abc_Print(-2, "\t        transforms the current network into an AIG assuming it is FRAIG with choices\n")
	//    Abc_Print( -2, "\t-d    : toggle duplication of logic [default = %s]\n", abcSelect(fDuplicate, "yes", "no") );
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

