/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandFraigRestore(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var nPatsRand int32       // the number of words of random simulation info
	var nPatsDyna int32       // the number of words of dynamic simulation info
	var nBTLimit int32 = 1000 // the max number of backtracks to perform

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "RDCh"); c != -1; c = Extra_UtilGetopt(argc, argv, "RDCh") {
		switch c {
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			nPatsRand = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPatsRand < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			nPatsDyna = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPatsDyna < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBTLimit < 0 {
				goto usage
			}
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	// get the new network
	pNtkRes = Abc_NtkFraigRestore(nPatsRand, nPatsDyna, nBTLimit)
	if pNtkRes == nil {
		Abc_Print(-1, "Fraig restoring has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: fraig_restore [-RDC num] [-h]\n")
	Abc_Print(-2, "\t         makes the current network by fraiging the AIG database\n")
	Abc_Print(-2, "\t-R num : number of random patterns (127 < num < 32769) [default = design-dependent]\n")
	Abc_Print(-2, "\t-D num : number of systematic patterns (127 < num < 32769) [default = design-dependent]\n")
	Abc_Print(-2, "\t-C num : number of backtracks for one SAT problem [default = %d]\n", nBTLimit)
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

