/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandFraigSweep(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fUseInv int32
	var fExdc int32
	var fVerbose int32
	var fVeryVerbose int32

	// set defaults
	fUseInv = 1
	fExdc = 0
	fVerbose = 0
	fVeryVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ievwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "ievwh") {
		switch c {
		case 'i':
			fUseInv ^= 1
			break
		case 'e':
			fExdc ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Cannot sweep AIGs (use \"fraig\").\n")
		return 1
	}
	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "Transform the current network into a logic network.\n")
		return 1
	}
	// modify the current network
	if !Abc_NtkFraigSweep(pNtk, fUseInv, fExdc, fVerbose, fVeryVerbose) {
		Abc_Print(-1, "Sweeping has failed.\n")
		return 1
	}
	return 0

usage:
	Abc_Print(-2, "usage: fraig_sweep [-evwh]\n")
	Abc_Print(-2, "\t        performs technology-dependent sweep\n")
	Abc_Print(-2, "\t-e    : toggle functional sweeping using EXDC [default = %s]\n", abcSelect(fExdc, "yes", "no"))
	Abc_Print(-2, "\t-v    : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w    : prints equivalence class information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandFraigDress(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pNtk2 *Abc_Ntk_t
	var pFileName string
	var c int32
	var nConfs int32
	var fVerbose int32
	// set defaults
	nConfs = 1000
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Cvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Cvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfs = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfs < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for logic networks.\n")
		return 1
	}
	if argc != globalUtilOptind && argc != globalUtilOptind+1 {
		goto usage
	}
	if argc == globalUtilOptind && Abc_NtkSpec(pNtk) == nil {
		Abc_Print(-1, "The current network has no spec.\n")
		return 1
	}
	// get the input file name
	if argc == globalUtilOptind+1 {
		pFileName = argv[globalUtilOptind]
	} else {
		pFileName = Abc_NtkSpec(pNtk)
	}
	// modify the current network
	//    Abc_NtkDress( pNtk, pFileName, fVerbose );
	pNtk2 = Io_Read(pFileName, Io_ReadFileType(pFileName), 1, 0)
	Abc_NtkDress2(pNtk, pNtk2, nConfs, fVerbose)
	Abc_NtkDelete(pNtk2)
	return 0

usage:
	Abc_Print(-2, "usage: dress [-C num] [-vh] <file>\n")
	Abc_Print(-2, "\t         transfers internal node names from file to the current network\n")
	Abc_Print(-2, "\t<file> : network with names (if not given, the current network spec is used)\n")
	Abc_Print(-2, "\t-C num : the maximum number of conflicts at each node [default = %d]\n", nConfs)
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDumpEquiv(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtks [2]*Abc_Ntk_t = [2]*Abc_Ntk_t{nil}
	var pFileName [2]string
	var pFileNameOut string
	var c int32
	var nConfs int32 = 1000
	var fByName int32 = 1
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Cnvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Cnvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfs = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfs < 0 {
				goto usage
			}
			break
		case 'n':
			fByName ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if argc != globalUtilOptind+3 {
		Abc_Print(-1, "Expecting three file names on the command line.\n")
		goto usage
	}
	pFileName[0] = argv[globalUtilOptind]
	pFileName[1] = argv[globalUtilOptind+1]
	pFileNameOut = argv[globalUtilOptind+2]
	for c = 0; c < 2; c++ {
		pNtks[c] = Io_Read(pFileName[c], Io_ReadFileType(pFileName[c]), 1, 0)
		if pNtks[c] == nil {
			goto usage
		}
		Abc_NtkToAig(pNtks[c])
	}
	//    if ( Abc_NtkCiNum(pNtks[0]) != Abc_NtkCiNum(pNtks[1]) )
	//        Abc_Print( -1, "The number of primary inputs of networks \"%s\" and \"%s\" does not match.\n", Abc_NtkName(pNtks[0]), Abc_NtkName(pNtks[1]) );
	//    else if ( Abc_NtkCoNum(pNtks[0]) != Abc_NtkCoNum(pNtks[1]) )
	//        Abc_Print( -1, "The number of primary outputs of networks \"%s\" and \"%s\" does not match.\n", Abc_NtkName(pNtks[0]), Abc_NtkName(pNtks[1]) );
	//    else
	Abc_NtkDumpEquiv(pNtks, pFileNameOut, nConfs, fByName, fVerbose)
	Abc_NtkDelete(pNtks[0])
	Abc_NtkDelete(pNtks[1])
	return 0

usage:
	Abc_Print(-2, "usage: dump_equiv [-C num] [-nvh] <file1.blif> <file2.blif> <file_dump_equiv.txt>\n")
	Abc_Print(-2, "\t          computes equivalence classes of nodes in <file1> and <file2>\n")
	Abc_Print(-2, "\t          By default this procedure performs matching of primary inputs by name.\n")
	Abc_Print(-2, "\t          Those inputs that cannot be matched are treated as free variables.\n")
	Abc_Print(-2, "\t          There is no effort to match primary outputs. Indeed, if two outputs\n")
	Abc_Print(-2, "\t          are equivalent, they will belong to the same equivalence class in the end.\n")
	Abc_Print(-2, "\t-C num  : the maximum number of conflicts at each node [default = %d]\n", nConfs)
	Abc_Print(-2, "\t-n      : enable matching of primary inputs by name [default = %s]\n", abcSelect(fByName, "yes", "no"))
	Abc_Print(-2, "\t-v      : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	Abc_Print(-2, "\t<file1> : first network whose nodes are considered\n")
	Abc_Print(-2, "\t<file2> : second network whose nodes are considered\n")
	Abc_Print(-2, "\t<file_dump_equiv> : text file with node equivalence classes\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRecStart3(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var FileName, pTemp string
	var pArgvNew *string
	var c, nArgcNew int32
	var pFile *os.File
	var err error
	var pGia *Gia_Man_t = nil
	var nVars int32 = 6
	var nCuts int32 = 32
	var fFuncOnly int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "KCfvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "KCfvh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nVars < 1 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nCuts = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCuts < 1 {
				goto usage
			}
			break
		case 'f':
			fFuncOnly ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if !(nVars >= 3 && nVars <= 16) {
		Abc_Print(-1, "The range of allowed values is 3 <= K <= 16.\n")
		return 0
	}
	if Abc_NtkRecIsRunning3() {
		Abc_Print(-1, "The AIG subgraph recording is already started.\n")
		return 0
	}
	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if nArgcNew != 1 {
		Abc_Print(1, "File name is not given on the command line. Starting a new record.\n")
	} else {
		// get the input file name
		FileName = pArgvNew[0]
		// fix the wrong symbol
		FileName = strings.ReplaceAll(FileName, ">", "\\")
		pFile, err = os.Open(FileName)
		if err != nil {
			Abc_Print(-1, "Cannot open input file \"%s\". ", FileName)
			if similar := Extra_FileGetSimilarName(FileName, ".aig", "", "", "", ""); similar != "" {
				Abc_Print(1, "Did you mean \"%s\"?", similar)
			}
			Abc_Print(1, "\n")
			return 1
		}
		_ = pFile.Close()
		pGia = Gia_AigerRead(FileName, 0, 1, 0)
		if pGia == nil {
			Abc_Print(-1, "Reading AIGER has failed.\n")
			return 0
		}
	}
	Abc_NtkRecStart3(pGia, nVars, nCuts, fFuncOnly, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: rec_start3 [-K num] [-C num] [-fvh] <file>\n")
	Abc_Print(-2, "\t         starts recording AIG subgraphs (should be called for\n")
	Abc_Print(-2, "\t         an empty network or after reading in a previous record)\n")
	Abc_Print(-2, "\t-K num : the largest number of inputs [default = %d]\n", nVars)
	Abc_Print(-2, "\t-C num : the max number of cuts used at a node (0 < num < 2^12) [default = %d]\n", nCuts)
	Abc_Print(-2, "\t-f     : toggles recording functions without AIG subgraphs [default = %s]\n", abcSelect(fFuncOnly, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles additional verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t<file> : AIGER file with the library\n")
	return 1
}

