/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRecDump3(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var FileName string
	var pArgvNew *string
	var nArgcNew int32
	var pGia *Gia_Man_t
	var fAscii int32
	var fBinary int32
	var c int32

	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "abh"); c != -1; c = Extra_UtilGetopt(argc, argv, "abh") {
		switch c {
		case 'a':
			fAscii ^= 1
			break
		case 'b':
			fBinary ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if !Abc_NtkRecIsRunning3() {
		Abc_Print(-1, "The AIG subgraph recording is not started.\n")
		return 1
	}

	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if nArgcNew != 1 {
		Abc_Print(-1, "File name is not given on the command line.\n")
		return 1
	}
	// get the input file name
	FileName = pArgvNew[0]
	if fAscii != 0 {
		Abc_NtkRecDumpTt3(FileName, 0)
	} else if fBinary != 0 {
		Abc_NtkRecDumpTt3(FileName, 1)
	} else {
		pGia = Abc_NtkRecGetGia3()
		if pGia == nil {
			Abc_Print(0, "Library AIG is not available.\n")
			return 1
		}
		if Gia_ManPoNum(pGia) == 0 {
			Abc_Print(0, "No structure in the library.\n")
			return 1
		}
		Gia_AigerWrite(pGia, FileName, 0, 0, 0)
	}
	return 0

usage:
	Abc_Print(-2, "usage: rec_dump3 [-abh] <file>\n")
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t-a     : toggles dumping TTs into an ASCII file [default = %s]\n", abcSelect(fAscii, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggles dumping TTs into a binary file [default = %s]\n", abcSelect(fBinary, "yes", "no"))
	Abc_Print(-2, "\t<file> : AIGER file to write the library\n")
	return 1
}

