func Abc_CommandDsdPs(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var c, Number, Support, fOccurs, fTtDump, fSecond, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NSotbvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NSotbvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by a floating point number.\n")
				goto usage
			}
			Number = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Number < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by a floating point number.\n")
				goto usage
			}
			Support = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Support < 0 {
				goto usage
			}
			break
		case 'o':
			fOccurs ^= 1
			break
		case 't':
			fTtDump ^= 1
			break
		case 'b':
			fSecond ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if fSecond != 0 {
		if !Abc_FrameReadManDsd2() {
			Abc_Print(-1, "The DSD manager is not started.\n")
			return 0
		}
		man, _ := Abc_FrameReadManDsd2().(*If_DsdMan_t)
		If_DsdManPrint(man, nil, Number, Support, fOccurs, fTtDump, fVerbose)

	} else {
		if !Abc_FrameReadManDsd() {
			Abc_Print(-1, "The DSD manager is not started.\n")
			return 0
		}
		man, _ := Abc_FrameReadManDsd().(*If_DsdMan_t)
		If_DsdManPrint(man, nil, Number, Support, fOccurs, fTtDump, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: dsd_ps [-NS num] [-obvh]\n")
	Abc_Print(-2, "\t         prints statistics of the DSD manager\n")
	Abc_Print(-2, "\t-N num : show structures whose ID divides by N [default = %d]\n", Number)
	Abc_Print(-2, "\t-S num : show structures whose support size is S [default = %d]\n", Support)
	Abc_Print(-2, "\t-o     : toggles printing occurence distribution [default = %s]\n", abcSelect(fOccurs, "yes", "no"))
	Abc_Print(-2, "\t-t     : toggles dumping truth tables [default = %s]\n", abcSelect(fTtDump, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggles processing second manager [default = %s]\n", abcSelect(fSecond, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDsdMatch(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pStruct string
	var c int32
	var fVerbose int32
	var fFast int32
	var fAdd int32
	var fSpec int32
	var LutSize int32
	var nConfls int32 = 10000
	var nProcs int32 = 1
	pDsdMan, _ := Abc_FrameReadManDsd().(*If_DsdMan_t)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "KCPSfasvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "KCPSfasvh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by a floating point number.\n")
				goto usage
			}
			LutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if LutSize < 4 || LutSize > 6 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by a floating point number.\n")
				goto usage
			}
			nConfls = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by a floating point number.\n")
				goto usage
			}
			nProcs = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by string.\n")
				goto usage
			}
			pStruct = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'f':
			fFast ^= 1
			break
		case 'a':
			fAdd ^= 1
			break
		case 's':
			fSpec ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if !Abc_FrameReadManDsd() {
		Abc_Print(-1, "The DSD manager is not started.\n")
		return 0
	}
	if pStruct != "" {
		var pStructCur string = If_DsdManGetCellStr(pDsdMan)
		if pStructCur && (int32(strings.Compare(pStructCur, pStruct)) != 0) {
			Abc_Print(-1, "DSD manager matched with cell %s should be cleaned by \"dsd_filter -m\" before matching with cell %s.\n", pStructCur, pStruct)
			return 0
		}
		Id_DsdManTuneStr(pDsdMan, pStruct, nConfls, nProcs, fVerbose)

	} else {
		If_DsdManTune(pDsdMan, LutSize, fFast, fAdd, fSpec, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: dsd_match [-KCP num] [-fasvh] [-S str]\n")
	Abc_Print(-2, "\t         matches DSD structures with the given cell\n")
	Abc_Print(-2, "\t-K num : LUT size used for tuning [default = %d]\n", LutSize)
	Abc_Print(-2, "\t-C num : the maximum number of conflicts [default = %d]\n", nConfls)
	Abc_Print(-2, "\t-P num : the maximum number of processes [default = %d]\n", nProcs)
	Abc_Print(-2, "\t-f     : toggles using fast check [default = %s]\n", abcSelect(fFast, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggles adding tuning to the current one [default = %s]\n", abcSelect(fAdd, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggles using specialized check [default = %s]\n", abcSelect(fSpec, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-S str : string representing programmable cell [default = %s]\n", abcDefaultString(pStruct, "not used"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

