/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDsdFilter(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	pDsd, _ := Abc_FrameReadManDsd().(*If_DsdMan_t)
	var c int32
	var nLimit int32
	var nLutSize int32 = -1
	var fCleanOccur int32
	var fCleanMarks int32
	var fInvMarks int32
	var fUnate int32
	var fThresh int32
	var fThreshHeuristic int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "LKomiutsvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "LKomiutsvh") {
		switch c {
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a floating point number.\n")
				goto usage
			}
			nLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by a floating point number.\n")
				goto usage
			}
			nLutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'o':
			fCleanOccur ^= 1
			break
		case 'm':
			fCleanMarks ^= 1
			break
		case 'i':
			fInvMarks ^= 1
			break
		case 'u':
			fUnate ^= 1
			break
		case 't':
			fThresh ^= 1
			break
		case 's':
			fThreshHeuristic ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pDsd == nil {
		Abc_Print(-1, "The DSD manager is not started.\n")
		return 0
	}
	if nLimit > 0 {
		Abc_FrameSetManDsd(If_DsdManFilter(pDsd, nLimit))
	}
	if nLutSize >= 0 {
		If_DsdManSetLutSize(pDsd, nLutSize)
	}
	if fCleanOccur != 0 {
		If_DsdManCleanOccur(pDsd, fVerbose)
	}
	if fCleanMarks != 0 {
		If_DsdManCleanMarks(pDsd, fVerbose)
	}
	if fInvMarks != 0 {
		If_DsdManInvertMarks(pDsd, fVerbose)
	}
	// The optional CUDD-only tuning branch is unavailable in the default Go build.
	return 0

usage:
	Abc_Print(-2, "usage: dsd_filter [-LK num] [-omiutsvh]\n")
	Abc_Print(-2, "\t         filtering structured and modifying parameters of DSD manager\n")
	Abc_Print(-2, "\t-L num : remove structures with fewer occurrences that this [default = %d]\n", nLimit)
	Abc_Print(-2, "\t-K num : new LUT size to set for the DSD manager [default = %d]\n", nLutSize)
	Abc_Print(-2, "\t-o     : toggles cleaning occurrence counters [default = %s]\n", abcSelect(fCleanOccur, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggles cleaning matching marks [default = %s]\n", abcSelect(fCleanMarks, "yes", "no"))
	Abc_Print(-2, "\t-i     : toggles inverting matching marks [default = %s]\n", abcSelect(fInvMarks, "yes", "no"))
	Abc_Print(-2, "\t-u     : toggles marking unate functions [default = %s]\n", abcSelect(fUnate, "yes", "no"))
	Abc_Print(-2, "\t-t     : toggles marking threshold functions [default = %s]\n", abcSelect(fThresh, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggles marking threshold functions heuristically [default = %s]\n", abcSelect(fThreshHeuristic, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t        \n")
	Abc_Print(-2, "\t         Option \"dsd_filter -s\" was contributed by Augusto Neutzling and Jody Matos from\n")
	Abc_Print(-2, "\t         Federal University of Rio Grande do Sul, Brazil. The paper describing the method:\n")
	Abc_Print(-2, "\t         A. Neutzling, J. M. Matos, A. Mishchenko, R. Ribas, and A. Reis,\n")
	Abc_Print(-2, "\t         \"Threshold logic synthesis based on cut pruning\". Proc. ICCAD 2015.\n")
	//    Abc_Print( -2, "\t        http://www.eecs.berkeley.edu/~alanmi/publications/2015/iccad15_thresh.pdf\n" );
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandInit(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var pObj *Abc_Obj_t
	var pInitStr string
	var fZeros int32
	var fOnes int32
	var fRandom int32
	var fDontCare int32
	var fUseCexCs int32
	var fUseCexNs int32
	var c, i int32
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Szordcnh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Szordcnh") {
		switch c {
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by a file name.\n")
				goto usage
			}
			pInitStr = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'z':
			fZeros ^= 1
			break
		case 'o':
			fOnes ^= 1
			break
		case 'r':
			fRandom ^= 1
			break
		case 'd':
			fDontCare ^= 1
			break
		case 'c':
			fUseCexCs ^= 1
			break
		case 'n':
			fUseCexNs ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if Abc_NtkIsComb(pNtk) {
		Abc_Print(0, "The current network is combinational.\n")
		return 0
	}

	if pInitStr != "" {
		if int32(len(pInitStr)) != Abc_NtkLatchNum(pNtk) {
			Abc_Print(-1, "The length of init string (%d) differs from the number of flops (%d).\n", len(pInitStr), Abc_NtkLatchNum(pNtk))
			return 1
		}
		for i := int32(0); i < Abc_NtkObjNumMax(pNtk); i++ {
			pObj = Abc_NtkObj(pNtk, i)
			if pObj == nil || Abc_ObjIsLatch(pObj) == 0 {
				continue
			}
			if pInitStr[i] == '0' {
				Abc_LatchSetInit0(pObj)
			} else if pInitStr[i] == '1' {
				Abc_LatchSetInit1(pObj)
			} else {
				Abc_LatchSetInitDc(pObj)
			}
		}
		return 0
	}

	if fZeros != 0 {
		for i := int32(0); i < Abc_NtkObjNumMax(pNtk); i++ {
			pObj = Abc_NtkObj(pNtk, i)
			if pObj != nil && Abc_ObjIsLatch(pObj) != 0 {
				Abc_LatchSetInit0(pObj)
			}
		}

	} else if fOnes != 0 {
		for i := int32(0); i < Abc_NtkObjNumMax(pNtk); i++ {
			pObj = Abc_NtkObj(pNtk, i)
			if pObj != nil && Abc_ObjIsLatch(pObj) != 0 {
				Abc_LatchSetInit1(pObj)
			}
		}

	} else if fRandom != 0 {
		rand.Seed(time.Now().Unix())
		for i := int32(0); i < Abc_NtkObjNumMax(pNtk); i++ {
			pObj = Abc_NtkObj(pNtk, i)
			if pObj != nil && Abc_ObjIsLatch(pObj) != 0 {
				if rand.Intn(2) != 0 {
					Abc_LatchSetInit1(pObj)
				} else {
					Abc_LatchSetInit0(pObj)
				}
			}
		}

	} else if fDontCare != 0 {
		for i := int32(0); i < Abc_NtkObjNumMax(pNtk); i++ {
			pObj = Abc_NtkObj(pNtk, i)
			if pObj != nil && Abc_ObjIsLatch(pObj) != 0 {
				Abc_LatchSetInitDc(pObj)
			}
		}

	} else if (fUseCexCs != 0) || (fUseCexNs != 0) {

		var pMan *Aig_Man_t
		var vFailState *Vec_Int_t
		if (fUseCexCs != 0) && (fUseCexNs != 0) {
			Abc_Print(-1, "The two options (-c and -n) are incompatible.\n")
			return 0
		}
		if !Abc_NtkIsStrash(pNtk) {
			Abc_Print(-1, "The current network should be an AIG.\n")
			return 0
		}
		if pAbc.pCex == nil {
			Abc_Print(-1, "The current CEX is not available.\n")
			return 0
		}
		pMan = Abc_NtkToDar(pNtk, 0, 1)
		vFailState = Saig_ManReturnFailingState(pMan, pAbc.pCex, fUseCexNs)
		//Vec_IntPrint( vFailState );
		Aig_ManStop(pMan)
		i := int32(0)
		for id := int32(0); id < Abc_NtkObjNumMax(pNtk); id++ {
			pObj = Abc_NtkObj(pNtk, id)
			if pObj == nil || Abc_ObjIsLatch(pObj) == 0 {
				continue
			}
			if Vec_IntEntry(vFailState, i) != 0 {
				Abc_LatchSetInit1(pObj)
			} else {
				Abc_LatchSetInit0(pObj)
			}
			i++
		}
		Vec_IntFree(vFailState)

	} else {
		Abc_Print(-1, "The initial states remain unchanged.\n")
	}
	return 0

usage:
	Abc_Print(-2, "usage: init [-zordcnh] [-S <init_string>]\n")
	Abc_Print(-2, "\t         resets initial states of all latches\n")
	Abc_Print(-2, "\t-z     : set zeros initial states [default = %s]\n", abcSelect(fZeros, "yes", "no"))
	Abc_Print(-2, "\t-o     : set ones initial states [default = %s]\n", abcSelect(fOnes, "yes", "no"))
	Abc_Print(-2, "\t-d     : set don't-care initial states [default = %s]\n", abcSelect(fDontCare, "yes", "no"))
	Abc_Print(-2, "\t-r     : set random initial states [default = %s]\n", abcSelect(fRandom, "yes", "no"))
	Abc_Print(-2, "\t-c     : set failure current state from the CEX (and run \"zero\") [default = %s]\n", abcSelect(fUseCexCs, "yes", "no"))
	Abc_Print(-2, "\t-n     : set next state after failure from the CEX (and run \"zero\") [default = %s]\n", abcSelect(fUseCexNs, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t-S str : (optional) initial state  [default = unused]\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandZero(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if Abc_NtkIsComb(pNtk) {
		Abc_Print(0, "The current network is combinational.\n")
		return 0
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for AIGs.\n")
		return 0
	}

	// get the new network
	pNtkRes = Abc_NtkRestrashZero(pNtk, 0)
	if pNtkRes == nil {
		Abc_Print(-1, "Converting to sequential AIG has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: zero [-h]\n")
	Abc_Print(-2, "\t        converts latches to have const-0 initial value\n")
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandUndc(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c, fUseCex int32
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ch"); c != -1; c = Extra_UtilGetopt(argc, argv, "ch") {
		switch c {
		case 'c':
			fUseCex ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if fUseCex != 0 {
		var pInit string
		var pTemp *Abc_Cex_t
		var k, nFlopsX int32
		if pAbc.pCex == nil {
			Abc_Print(-1, "Current CEX is not available.\n")
			return 1
		}
		pInit = Abc_NtkCollectLatchValuesStr(pAbc.pNtkCur)
		// count the number of X-valued flops
		for k = 0; k < Abc_NtkLatchNum(pAbc.pNtkCur); k++ {
			nFlopsX += int32((pInit[k] == 'x'))
		}
		// compare this value
		if Abc_NtkPiNum(pNtk)+nFlopsX != pAbc.pCex.nPis {
			Abc_Print(-1, "The number of PIs (%d) plus X-valued flops (%d) in the original network does not match the number of PIs in the current CEX (%d).\n",
				Abc_NtkPiNum(pNtk), Abc_NtkLatchNum(pNtk), pAbc.pCex.nPis)
			return 1
		}
		pTemp = pAbc.pCex
		pAbc.pCex = Abc_CexTransformUndc(pTemp, pInit)
		assert(pAbc.pCex.nPis == Abc_NtkPiNum(pAbc.pNtkCur), "pAbc.pCex.nPis == Abc_NtkPiNum(pAbc.pNtkCur)")
		assert(pAbc.pCex.nRegs == Abc_NtkLatchNum(pAbc.pNtkCur), "pAbc.pCex.nRegs == Abc_NtkLatchNum(pAbc.pNtkCur)")
		Abc_CexFree(pTemp)
		ABC_FREE(pInit)
		return 0
	}

	if Abc_NtkIsComb(pNtk) {
		Abc_Print(0, "The current network is combinational.\n")
		return 0
	}

	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "This command works only for logic networks.\n")
		return 0
	}

	// get the new network
	Abc_NtkConvertDcLatches(pNtk)
	return 0

usage:
	Abc_Print(-2, "usage: undc [-ch]\n")
	Abc_Print(-2, "\t        converts latches with DC init values into free PIs\n")
	Abc_Print(-2, "\t-c    : toggles transforming CEX after \"logic;undc;st;zero\" [default = %s]\n", abcSelect(fUseCex, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

