/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandRetime(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, nMaxIters int32
	var fForward int32
	var fBackward int32
	var fOneStep int32
	var fUseOldNames int32
	var fVerbose int32
	var Mode int32
	var nDelayLim int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Mode = 5
	nDelayLim = 0
	fForward = 0
	fBackward = 0
	fOneStep = 0
	fUseOldNames = 0
	fVerbose = 0
	nMaxIters = 15
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "MDfbsovh"); c != -1; c = Extra_UtilGetopt(argc, argv, "MDfbsovh") {
		switch c {
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by a positive integer.\n")
				goto usage
			}
			Mode = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Mode < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by a positive integer.\n")
				goto usage
			}
			nDelayLim = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nDelayLim < 0 {
				goto usage
			}
			break
		case 'f':
			fForward ^= 1
			break
		case 'b':
			fBackward ^= 1
			break
		case 's':
			fOneStep ^= 1
			break
		case 'o':
			fUseOldNames ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if (fForward != 0) && (fBackward != 0) {
		Abc_Print(-1, "Only one switch \"-f\" or \"-b\" can be selected at a time.\n")
		return 1
	}

	if !Abc_NtkLatchNum(pNtk) {
		//        Abc_Print( -1, "The network has no latches. Retiming is not performed.\n" );
		return 0
	}

	if Mode < 0 || Mode > 6 {
		Abc_Print(-1, "The mode (%d) is incorrect. Retiming is not performed.\n", Mode)
		return 0
	}

	if Abc_NtkIsStrash(pNtk) {
		if Abc_NtkGetChoiceNum(pNtk) {
			Abc_Print(-1, "Retiming with choice nodes is not implemented.\n")
			return 0
		}
		// convert the network into an SOP network
		pNtkRes = Abc_NtkToLogic(pNtk)
		// perform the retiming
		Abc_NtkRetime(pNtkRes, Mode, nDelayLim, fForward, fBackward, fOneStep, fUseOldNames, fVerbose)
		// replace the current network
		Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
		return 0
	}

	// get the network in the SOP form
	if !Abc_NtkToSop(pNtk, -1, ABC_INFINITY) {
		Abc_Print(-1, "Converting to SOPs has failed.\n")
		return 0
	}

	if !Abc_NtkIsLogic(pNtk) {
		Abc_Print(-1, "The network is not a logic network. Retiming is not performed.\n")
		return 0
	}

	// perform the retiming
	Abc_NtkRetime(pNtk, Mode, nDelayLim, fForward, fBackward, fOneStep, fUseOldNames, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: retime [-MD num] [-fbsovh]\n")
	Abc_Print(-2, "\t         retimes the current network using one of the algorithms:\n")
	Abc_Print(-2, "\t             1: most forward retiming\n")
	Abc_Print(-2, "\t             2: most backward retiming\n")
	Abc_Print(-2, "\t             3: forward and backward min-area retiming\n")
	Abc_Print(-2, "\t             4: forward and backward min-delay retiming\n")
	Abc_Print(-2, "\t             5: mode 3 followed by mode 4\n")
	Abc_Print(-2, "\t             6: Pan's optimum-delay retiming using binary search\n")
	Abc_Print(-2, "\t-M num : the retiming algorithm to use [default = %d]\n", Mode)
	Abc_Print(-2, "\t-D num : the minimum delay target (0=unused) [default = %d]\n", nDelayLim)
	Abc_Print(-2, "\t-f     : enables forward-only retiming in modes 3,4,5 [default = %s]\n", abcSelect(fForward, "yes", "no"))
	Abc_Print(-2, "\t-b     : enables backward-only retiming in modes 3,4,5 [default = %s]\n", abcSelect(fBackward, "yes", "no"))
	Abc_Print(-2, "\t-s     : enables retiming one step only in mode 4 [default = %s]\n", abcSelect(fOneStep, "yes", "no"))
	Abc_Print(-2, "\t-o     : enables usind old flop naming conventions [default = %s]\n", abcSelect(fUseOldNames, "yes", "no"))
	Abc_Print(-2, "\t-v     : enables verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
	// Abc_Print( -2, "\t-I num : max number of iterations of l-value computation [default = %d]\n", nMaxIters );
	// Abc_Print( -2, "\t-f     : toggle forward retiming (for AIGs) [default = %s]\n", abcSelect(fForward, "yes", "no") );
	// Abc_Print( -2, "\t-b     : toggle backward retiming (for AIGs) [default = %s]\n", abcSelect(fBackward, "yes", "no") );
	// Abc_Print( -2, "\t-i     : toggle computation of initial state [default = %s]\n", abcSelect(fInitial, "yes", "no") );
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDRetime(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var fMinArea int32
	var fForwardOnly int32
	var fBackwardOnly int32
	var fInitial int32
	var nStepsMax int32
	var fFastAlgo int32
	var fVerbose int32
	var c, nMaxIters int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fMinArea = 1
	fForwardOnly = 0
	fBackwardOnly = 0
	fInitial = 1
	nStepsMax = 100000
	fFastAlgo = 0
	nMaxIters = 20
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NSmfbiavh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NSmfbiavh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by a positive integer.\n")
				goto usage
			}
			nMaxIters = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nMaxIters < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by a positive integer.\n")
				goto usage
			}
			nStepsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nStepsMax < 0 {
				goto usage
			}
			break
		case 'm':
			fMinArea ^= 1
			break
		case 'f':
			fForwardOnly ^= 1
			break
		case 'b':
			fBackwardOnly ^= 1
			break
		case 'i':
			fInitial ^= 1
			break
		case 'a':
			fFastAlgo ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkLatchNum(pNtk) {
		//        Abc_Print( -1, "The network has no latches. Retiming is not performed.\n" );
		return 0
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for structrally hashed networks. Run \"st\".\n")
		return 0
	}

	// perform the retiming
	if fMinArea != 0 {
		pNtkRes = Abc_NtkDarRetimeMinArea(pNtk, nMaxIters, fForwardOnly, fBackwardOnly, fInitial, fVerbose)
	} else if fFastAlgo != 0 {
		pNtkRes = Abc_NtkDarRetime(pNtk, nStepsMax, fVerbose)
	} else {
		//        pNtkRes = Abc_NtkDarRetimeF( pNtk, nStepsMax, fVerbose );
		pNtkRes = Abc_NtkDarRetimeMostFwd(pNtk, nMaxIters, fVerbose)
	}
	if pNtkRes == nil {
		Abc_Print(-1, "Retiming has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: dretime [-NS num] [-mfbiavh]\n")
	Abc_Print(-2, "\t         new implementation of min-area (or most-forward) retiming\n")
	Abc_Print(-2, "\t-m     : toggle min-area retiming and most-forward retiming [default = %s]\n", abcSelect(fMinArea, "min-area", "most-fwd"))
	Abc_Print(-2, "\t-f     : enables forward-only retiming [default = %s]\n", abcSelect(fForwardOnly, "yes", "no"))
	Abc_Print(-2, "\t-b     : enables backward-only retiming [default = %s]\n", abcSelect(fBackwardOnly, "yes", "no"))
	Abc_Print(-2, "\t-i     : enables init state computation [default = %s]\n", abcSelect(fInitial, "yes", "no"))
	Abc_Print(-2, "\t-N num : the max number of one-frame iterations to perform [default = %d]\n", nMaxIters)
	Abc_Print(-2, "\t-S num : the max number of forward retiming steps to perform [default = %d]\n", nStepsMax)
	Abc_Print(-2, "\t-a     : enables a fast most-forward algorithm [default = %s]\n", abcSelect(fFastAlgo, "yes", "no"))
	Abc_Print(-2, "\t-v     : enables verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandFlowRetime(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c, nMaxIters int32
	var fForward int32
	var fBackward int32
	var fVerbose int32
	var fComputeInit, fGuaranteeInit, fBlockConst int32
	var fFastButConservative int32
	var maxDelay int32

	// extern Abc_Ntk_t* Abc_FlowRetime_MinReg( Abc_Ntk_t * pNtk, int fVerbose,
	//                                             int fComputeInit, int fGuaranteeInit, int fBlockConst,
	//                                             int fForward, int fBackward, int nMaxIters,
	//                                             int maxDelay, int fFastButConservative);

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fForward = 0
	fFastButConservative = 0
	fBackward = 0
	fComputeInit = 1
	fGuaranteeInit = 0
	fVerbose = 0
	fBlockConst = 0
	nMaxIters = 999
	maxDelay = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "MDfcgbkivh"); c != -1; c = Extra_UtilGetopt(argc, argv, "MDfcgbkivh") {
		switch c {
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by a positive integer.\n")
				goto usage
			}
			nMaxIters = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nMaxIters < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by a positive integer.\n")
				goto usage
			}
			maxDelay = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if maxDelay < 0 {
				goto usage
			}
			break
		case 'f':
			fForward ^= 1
			break
		case 'c':
			fFastButConservative ^= 1
			break
		case 'i':
			fComputeInit ^= 1
			break
		case 'b':
			fBackward ^= 1
			break
		case 'g':
			fGuaranteeInit ^= 1
			break
		case 'k':
			fBlockConst ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if (fForward != 0) && (fBackward != 0) {
		Abc_Print(-1, "Only one switch \"-f\" or \"-b\" can be selected at a time.\n")
		return 1
	}

	if fGuaranteeInit && !fComputeInit {
		Abc_Print(-1, "Initial state guarantee (-g) requires initial state computation (-i).\n")
		return 1
	}

	if !Abc_NtkLatchNum(pNtk) {
		Abc_Print(-1, "The network has no latches. Retiming is not performed.\n")
		return 0
	}

	if Abc_NtkGetChoiceNum(pNtk) {
		Abc_Print(-1, "Retiming with choice nodes is not implemented.\n")
		return 0
	}

	// perform the retiming
	pNtkRes = Abc_FlowRetime_MinReg(pNtk, fVerbose, fComputeInit,
		fGuaranteeInit, fBlockConst,
		fForward, fBackward,
		nMaxIters, maxDelay, fFastButConservative)

	if pNtkRes != pNtk {
		Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	}

	return 0

usage:
	Abc_Print(-2, "usage: fretime [-M num] [-D num] [-fbvih]\n")
	Abc_Print(-2, "\t         retimes the current network using flow-based algorithm\n")
	Abc_Print(-2, "\t-M num : the maximum number of iterations [default = %d]\n", nMaxIters)
	Abc_Print(-2, "\t-D num : the maximum delay [default = none]\n")
	Abc_Print(-2, "\t-i     : enables init state computation [default = %s]\n", abcSelect(fComputeInit, "yes", "no"))
	Abc_Print(-2, "\t-k     : blocks retiming over const nodes [default = %s]\n", abcSelect(fBlockConst, "yes", "no"))
	Abc_Print(-2, "\t-g     : guarantees init state computation [default = %s]\n", abcSelect(fGuaranteeInit, "yes", "no"))
	Abc_Print(-2, "\t-c     : very fast (but conserv.) delay constraints [default = %s]\n", abcSelect(fFastButConservative, "yes", "no"))
	Abc_Print(-2, "\t-f     : enables forward-only retiming  [default = %s]\n", abcSelect(fForward, "yes", "no"))
	Abc_Print(-2, "\t-b     : enables backward-only retiming [default = %s]\n", abcSelect(fBackward, "yes", "no"))
	Abc_Print(-2, "\t-v     : enables verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCRetime(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "vh"); c != -1; c = Extra_UtilGetopt(argc, argv, "vh") {
		switch c {
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Only works for logic networks.\n")
		return 1
	}
	if !Abc_NtkLatchNum(pNtk) {
		Abc_Print(-1, "The network is combinational.\n")
		return 0
	}
	// modify the current network
	pNtkRes = Abc_NtkCRetime(pNtk, fVerbose)
	if pNtkRes == nil {
		Abc_Print(-1, "Sequential cleanup has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: cretime [-vh]\n")
	Abc_Print(-2, "\t         performs most-forward retiming with equiv classes\n")
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSeqFpga(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkNew, pNtkRes *Abc_Ntk_t
	var c, nMaxIters int32
	var fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	nMaxIters = 15
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Ivh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Ivh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by a positive integer.\n")
				goto usage
			}
			nMaxIters = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nMaxIters < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if Abc_NtkHasAig(pNtk) {
		/*
		   // quit if there are choice nodes
		   if ( Abc_NtkGetChoiceNum(pNtk) )
		   {
		       Abc_Print( -1, "Currently cannot map/retime networks with choice nodes.\n" );
		       return 0;
		   }
		*/
		//        if ( Abc_NtkIsStrash(pNtk) )
		//            pNtkNew = Abc_NtkAigToSeq(pNtk);
		//        else
		//            pNtkNew = Abc_NtkDup(pNtk);
		pNtkNew = nil

	} else {
		// strash and balance the network
		pNtkNew = Abc_NtkStrash(pNtk, 0, 0, 0)
		if pNtkNew == nil {
			Abc_Print(-1, "Strashing before FPGA mapping/retiming has failed.\n")
			return 1
		}

		pNtkRes = pNtkNew
		pNtkNew = Abc_NtkBalance(pNtkRes, 0, 0, 1)
		Abc_NtkDelete(pNtkRes)
		if pNtkNew == nil {
			Abc_Print(-1, "Balancing before FPGA mapping has failed.\n")
			return 1
		}

		// convert into a sequential AIG
		//        pNtkNew = Abc_NtkAigToSeq( pNtkRes = pNtkNew );
		pNtkNew = nil
		Abc_NtkDelete(pNtkRes)
		if pNtkNew == nil {
			Abc_Print(-1, "Converting into a seq AIG before FPGA mapping/retiming has failed.\n")
			return 1
		}

		Abc_Print(1, "The network was strashed and balanced before FPGA mapping/retiming.\n")
	}

	// get the new network
	//    pNtkRes = Seq_NtkFpgaMapRetime( pNtkNew, nMaxIters, fVerbose );
	pNtkRes = nil
	if pNtkRes == nil {
		//        Abc_Print( -1, "Sequential FPGA mapping has failed.\n" );
		Abc_NtkDelete(pNtkNew)
		return 0
	}
	Abc_NtkDelete(pNtkNew)
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: sfpga [-I num] [-vh]\n")
	Abc_Print(-2, "\t         performs integrated sequential FPGA mapping/retiming\n")
	Abc_Print(-2, "\t-I num : max number of iterations of l-value computation [default = %d]\n", nMaxIters)
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

