func Abc_CommandTestScorr(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtkRes *Abc_Ntk_t
	var c int32
	var nConfMax int32
	var nStepsMax int32
	var fNewAlgo int32
	var fFlopOnly int32
	var fFfNdOnly int32
	var fVerbose int32
	// set defaults
	nConfMax = 100
	nStepsMax = -1
	fNewAlgo = 0
	fFlopOnly = 0
	fFfNdOnly = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CSnfsvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "CSnfsvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfMax < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			nStepsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nStepsMax < 0 {
				goto usage
			}
			break
		case 'n':
			fNewAlgo ^= 1
			break
		case 'f':
			fFlopOnly ^= 1
			break
		case 's':
			fFfNdOnly ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		default:
			goto usage
		}
	}
	if argc != globalUtilOptind+2 {
		Abc_Print(-1, "Expecting two files names on the command line.\n")
		goto usage
	}
	if (fFlopOnly != 0) && (fFfNdOnly != 0) {
		Abc_Print(-1, "These two options (-f and -s) are incompatible.\n")
		goto usage
	}
	// get the new network
	pNtkRes = Abc_NtkTestScorr(argv[globalUtilOptind], argv[globalUtilOptind+1], nStepsMax, nConfMax, fNewAlgo, fFlopOnly, fFfNdOnly, fVerbose)
	if pNtkRes == nil {
		Abc_Print(-1, "Sequential sweeping has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: testscorr [-CS num] [-nfsvh] <file_in> <file_out>\n")
	Abc_Print(-2, "\t             outputs the list of sequential equivalences into a file\n")
	Abc_Print(-2, "\t             (if <file_in> is in BENCH, init state file should be the same directory)\n")
	Abc_Print(-2, "\t-C num     : limit on the number of conflicts [default = %d]\n", nConfMax)
	Abc_Print(-2, "\t-S num     : limit on refinement iterations (-1=no limit, 0=after BMC, etc) [default = %d]\n", nStepsMax)
	Abc_Print(-2, "\t-n         : toggle between \"scorr\" and \"&scorr\" [default = %s]\n", abcSelect(fNewAlgo, "&scorr", "scorr"))
	Abc_Print(-2, "\t-f         : toggle reporting only flop/flop equivs [default = %s]\n", abcSelect(fFlopOnly, "yes", "no"))
	Abc_Print(-2, "\t-s         : toggle reporting only flop/flop and flop/node equivs [default = %s]\n", abcSelect(fFfNdOnly, "yes", "no"))
	Abc_Print(-2, "\t-v         : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h         : print the command usage\n")
	Abc_Print(-2, "\t<file_in>  : input file with design for sequential equivalence computation\n")
	Abc_Print(-2, "\t<file_out> : output file with the list of pairs of equivalent signals\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandLcorr(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var nFramesP int32
	var nConfMax int32
	var nVarsMax int32
	var fNewAlgor int32
	var fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	nFramesP = 0
	nConfMax = 1000
	nVarsMax = 1000
	fNewAlgor = 1
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "PCSnvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "PCSnvh") {
		switch c {
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nFramesP = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFramesP < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfMax < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			nVarsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nVarsMax < 0 {
				goto usage
			}
			break
		case 'n':
			fNewAlgor ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if Abc_NtkIsComb(pNtk) {
		Abc_Print(-1, "The network is combinational (run \"fraig\" or \"fraig_sweep\").\n")
		return 0
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for structrally hashed networks. Run \"st\".\n")
		return 0
	}

	// get the new network
	if fNewAlgor != 0 {
		pNtkRes = Abc_NtkDarLcorrNew(pNtk, nVarsMax, nConfMax, fVerbose)
	} else {
		pNtkRes = Abc_NtkDarLcorr(pNtk, nFramesP, nConfMax, fVerbose)
	}
	if pNtkRes == nil {
		Abc_Print(-1, "Sequential sweeping has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: lcorr [-PCS num] [-nvh]\n")
	Abc_Print(-2, "\t         computes latch correspondence using 1-step induction\n")
	Abc_Print(-2, "\t-P num : number of time frames to use as the prefix [default = %d]\n", nFramesP)
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", nConfMax)
	Abc_Print(-2, "\t-S num : the max number of SAT variables [default = %d]\n", nVarsMax)
	Abc_Print(-2, "\t-n     : toggle using new algorithm [default = %s]\n", abcSelect(fNewAlgor, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSeqCleanup(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkRes *Abc_Ntk_t
	var c int32
	var fLatchConst int32 = 1
	var fLatchEqual int32 = 1
	var fSaveNames int32 = 1
	var fUseMvSweep int32
	var nFramesSymb int32 = 1
	var nFramesSatur int32 = 512
	var fVerbose int32
	var fVeryVerbose int32
	pNtk = Abc_FrameReadNtk(pAbc)

	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "cenmFSvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "cenmFSvwh") {
		switch c {
		case 'c':
			fLatchConst ^= 1
			break
		case 'e':
			fLatchEqual ^= 1
			break
		case 'n':
			fSaveNames ^= 1
			break
		case 'm':
			fUseMvSweep ^= 1
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFramesSymb = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFramesSymb < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			nFramesSatur = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFramesSatur < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Only works for structrally hashed networks.\n")
		return 1
	}
	if !Abc_NtkLatchNum(pNtk) {
		Abc_Print(-1, "The network is combinational.\n")
		return 0
	}
	// modify the current network
	pNtkRes = Abc_NtkDarLatchSweep(pNtk, fLatchConst, fLatchEqual, fSaveNames, fUseMvSweep, nFramesSymb, nFramesSatur, fVerbose, fVeryVerbose)
	if pNtkRes == nil {
		Abc_Print(-1, "Sequential cleanup has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: scleanup [-cenmFSvwh]\n")
	Abc_Print(-2, "\t         performs sequential cleanup of the current network\n")
	Abc_Print(-2, "\t         by removing nodes and latches that do not feed into POs\n")
	Abc_Print(-2, "\t-c     : sweep stuck-at latches detected by ternary simulation [default = %s]\n", abcSelect(fLatchConst, "yes", "no"))
	Abc_Print(-2, "\t-e     : merge equal latches (same data inputs and init states) [default = %s]\n", abcSelect(fLatchEqual, "yes", "no"))
	Abc_Print(-2, "\t-n     : toggle preserving latch names [default = %s]\n", abcSelect(fSaveNames, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggle using hybrid ternary/symbolic simulation [default = %s]\n", abcSelect(fUseMvSweep, "yes", "no"))
	Abc_Print(-2, "\t-F num : the number of first frames simulated symbolically [default = %d]\n", nFramesSymb)
	Abc_Print(-2, "\t-S num : the number of frames when symbolic saturation begins [default = %d]\n", nFramesSatur)
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggle very verbose output [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCycle(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var nFrames int32
	var fUseXval int32
	var fVerbose int32

	// set defaults
	nFrames = 100
	fUseXval = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Fxvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Fxvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'x':
			fUseXval ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsStrash(pNtk) && !Abc_NtkIsSopLogic(pNtk) {
		Abc_Print(-1, "Only works for strashed networks or logic SOP networks.\n")
		return 1
	}
	if !Abc_NtkLatchNum(pNtk) {
		Abc_Print(-1, "The network is combinational.\n")
		return 0
	}
	if (fUseXval != 0) && !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "X-valued simulation only works for AIGs. Run \"strash\".\n")
		return 0
	}
	if fUseXval != 0 {
		Abc_NtkCycleInitState(pNtk, nFrames, 1, fVerbose)
	} else if Abc_NtkIsStrash(pNtk) {
		Abc_NtkCycleInitState(pNtk, nFrames, 0, fVerbose)
	} else {
		Abc_NtkCycleInitStateSop(pNtk, nFrames, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: cycle [-F num] [-xvh]\n")
	Abc_Print(-2, "\t         cycles sequential circuit for the given number of timeframes\n")
	Abc_Print(-2, "\t         to derive a new initial state (which may be on the envelope)\n")
	Abc_Print(-2, "\t-F num : the number of frames to simulate [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-x     : use x-valued primary inputs [default = %s]\n", abcSelect(fUseXval, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandXsim(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var nFrames int32
	var fXInputs int32
	var fXState int32
	var fVerbose int32

	// set defaults
	nFrames = 10
	fXInputs = 0
	fXState = 0
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Fisvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Fisvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'i':
			fXInputs ^= 1
			break
		case 's':
			fXState ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Only works for strashed networks.\n")
		return 1
	}
	if !Abc_NtkLatchNum(pNtk) {
		Abc_Print(-1, "The network is combinational.\n")
		return 0
	}
	Abc_NtkXValueSimulate(pNtk, nFrames, fXInputs, fXState, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: xsim [-F num] [-isvh]\n")
	Abc_Print(-2, "\t         performs X-valued simulation of the AIG\n")
	Abc_Print(-2, "\t-F num : the number of frames to simulate [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-i     : toggle X-valued representation of inputs [default = %s]\n", abcSelect(fXInputs, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle X-valued representation of state [default = %s]\n", abcSelect(fXState, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSim(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var fNew int32
	var fComb int32
	var nFrames int32
	var nWords int32
	var TimeOut int32
	var fMiter int32
	var fVerbose int32
	var pFileSim string
	var pLogFileName string

	// set defaults
	fNew = 0
	fComb = 0
	nFrames = 32
	nWords = 8
	TimeOut = 30
	fMiter = 1
	fVerbose = 0
	pFileSim = nil
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FWTALnmvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FWTALnmvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			nWords = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nWords < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			TimeOut = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if TimeOut < 0 {
				goto usage
			}
			break
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by a file name.\n")
				goto usage
			}
			pFileSim = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a file name.\n")
				goto usage
			}
			pLogFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'n':
			fNew ^= 1
			break
		case 'm':
			fMiter ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Only works for strashed networks.\n")
		return 1
	}
	if pFileSim != nil && Abc_NtkLatchNum(pNtk) {
		Abc_Print(-1, "Currently simulation with user-specified patterns works only for comb miters.\n")
		return 1
	}
	ABC_FREE(pNtk.pSeqModel)
	pAbc.Status = Abc_NtkDarSeqSim(pNtk, nFrames, nWords, TimeOut, fNew, fMiter, fVerbose, pFileSim)
	Abc_FrameReplaceCex(pAbc, &pNtk.pSeqModel)
	if pLogFileName != "" {
		Abc_NtkWriteLogFile(pLogFileName, pAbc.pCex, pAbc.Status, pAbc.nFrames, "sim")
	}
	return 0

usage:
	Abc_Print(-2, "usage: sim [-FWT num] [-AL file] [-nmvh]\n")
	Abc_Print(-2, "\t          performs random simulation of the sequential miter\n")
	Abc_Print(-2, "\t-F num  : the number of frames to simulate [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-W num  : the number of words to simulate [default = %d]\n", nWords)
	Abc_Print(-2, "\t-T num  : approximate runtime limit in seconds [default = %d]\n", TimeOut)
	Abc_Print(-2, "\t-A file : text file name with user's patterns [default = random simulation]\n")
	Abc_Print(-2, "\t          (patterns are listed, one per line, as sequences of 0s and 1s)\n")
	Abc_Print(-2, "\t-L file : the log file name [default = %s]\n", abcDefaultString(pLogFileName, "no logging"))
	Abc_Print(-2, "\t-n      : toggle new vs. old implementation [default = %s]\n", abcSelect(fNew, "new", "old"))
	Abc_Print(-2, "\t-m      : toggle miter vs. any circuit [default = %s]\n", abcSelect(fMiter, "miter", "circuit"))
	Abc_Print(-2, "\t-v      : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

