/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandFunEnum(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var nInputs int32 = 4
	var nVars int32 = 4
	var nNodeMax int32 = 32
	var fUseTwo int32
	var fReduce int32
	var fSimple int32
	var fDelay int32
	var fMulti int32
	var fDump int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "SIMtrldmpvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "SIMtrldmpvh") {
		switch c {
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			nInputs = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nInputs < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nVars < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			nNodeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodeMax < 0 {
				goto usage
			}
			break
		case 't':
			fUseTwo ^= 1
			break
		case 'r':
			fReduce ^= 1
			break
		case 'l':
			fSimple ^= 1
			break
		case 'd':
			fDelay ^= 1
			break
		case 'm':
			fMulti ^= 1
			break
		case 'p':
			fDump ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			Abc_Print(-2, "Unknown switch.\n")
			goto usage
		}
	}
	if (fSimple != 0) || (fDelay != 0) {
		var Buffer string // was [100]byte in C

		if nVars < 3 || nVars > 5 {
			Abc_Print(-1, "The number of inputs should be 3 <= I <= 5.\n")
			goto usage
		}
		Buffer = fmt.Sprintf("Lflib%d.txt", nVars)
		dumpName := ""
		if fDump != 0 {
			dumpName = Buffer
		}
		Dtt_EnumerateLf(nVars, nNodeMax, fDelay, fMulti, fVerbose, dumpName)
		if fDump != 0 {
			var pTemp *Gia_Man_t
			pTemp = Dau_ConstructAigFromFile(Buffer)
			Abc_FrameUpdateGia(pAbc, pTemp)
			Gia_DumpAiger(pTemp, "Lflib", nVars, 1)
		}

	} else {
		if nVars < 2 || nVars > 6 {
			Abc_Print(-1, "The number of inputs should be 2 <= I <= 6.\n")
			goto usage
		}
		if nInputs < nVars || nInputs > 6 {
			Abc_Print(-1, "The intermediate support size should be I <= S <= 6.\n")
			goto usage
		}
		Dau_FunctionEnum(nInputs, nVars, nNodeMax, fUseTwo, fReduce, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: funenum [-SIM num] [-trldmvph]\n")
	Abc_Print(-2, "\t         enumerates minimum 2-input-gate implementations\n")
	Abc_Print(-2, "\t-S num : the maximum intermediate support size [default = %d]\n", nInputs)
	Abc_Print(-2, "\t-I num : the number of inputs of Boolean functions [default = %d]\n", nVars)
	Abc_Print(-2, "\t-M num : the maximum number of 2-input gates [default = %d]\n", nNodeMax)
	Abc_Print(-2, "\t-t     : toggle adding combination of two gates [default = %s]\n", abcSelect(fUseTwo, "yes", "no"))
	Abc_Print(-2, "\t-r     : toggle reducing the last level [default = %s]\n", abcSelect(fReduce, "yes", "no"))
	Abc_Print(-2, "\t-l     : toggle generating L(f) rather than C(f) [default = %s]\n", abcSelect(fSimple, "yes", "no"))
	Abc_Print(-2, "\t-d     : toggle generating D(f) rather than C(f) [default = %s]\n", abcSelect(fDelay, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggle generating multiplicity statistics [default = %s]\n", abcSelect(fMulti, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-p     : toggle dumping result library (formula and AIG) [default = %s]\n", abcSelect(fDump, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCec(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var Buffer string // was [16]byte in C

	var pNtk, pNtk1, pNtk2 *Abc_Ntk_t
	var fDelete1, fDelete2 int32
	var pArgvNew *string
	var nArgcNew int32
	var c int32
	var fSat int32
	var fVerbose int32
	var nSeconds int32
	var nPartSize int32
	var nConfLimit int32
	var nInsLimit int32
	var fPartition int32
	var fIgnoreNames int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fSat = 0
	fVerbose = 0
	nSeconds = 20
	nPartSize = 0
	nConfLimit = 10000
	nInsLimit = 0
	fPartition = 0
	fIgnoreNames = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "TCIPpsnvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "TCIPpsnvh") {
		switch c {
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			nSeconds = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nSeconds < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfLimit < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nInsLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nInsLimit < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nPartSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPartSize < 0 {
				goto usage
			}
			break
		case 'p':
			fPartition ^= 1
			break
		case 's':
			fSat ^= 1
			break
		case 'n':
			fIgnoreNames ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		default:
			goto usage
		}
	}

	if (pNtk != nil) && pNtk.vPhases != nil {
		Abc_Print(-1, "Cannot compare networks with phases defined.\n")
		return 1
	}

	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1) {
		return 1
	}

	if fIgnoreNames != 0 {
		if !fDelete1 {
			pNtk1 = Abc_NtkStrash(pNtk1, 0, 1, 0)
			fDelete1 = 1
		}
		if !(fDelete2 != 0) {
			pNtk2 = Abc_NtkStrash(pNtk2, 0, 1, 0)
			fDelete2 = 1
		}
		Abc_NtkShortNames(pNtk1)
		Abc_NtkShortNames(pNtk2)
	}

	// perform equivalence checking
	if fPartition != 0 {
		Abc_NtkCecFraigPartAuto(pNtk1, pNtk2, nSeconds, fVerbose)
	} else if nPartSize != 0 {
		Abc_NtkCecFraigPart(pNtk1, pNtk2, nSeconds, nPartSize, fVerbose)
	} else if fSat != 0 {
		Abc_NtkCecSat(pNtk1, pNtk2, nConfLimit, nInsLimit)
	} else {
		Abc_NtkCecFraig(pNtk1, pNtk2, nSeconds, fVerbose)
	}

	if fDelete1 != 0 {
		Abc_NtkDelete(pNtk1)
	}
	if fDelete2 != 0 {
		Abc_NtkDelete(pNtk2)
	}
	return 0

usage:
	if nPartSize == 0 {
		strcpy(Buffer, "unused")
	} else {
		Buffer = fmt.Sprintf("%d", nPartSize)
	}
	Abc_Print(-2, "usage: cec [-T num] [-C num] [-I num] [-P num] [-psnvh] <file1> <file2>\n")
	Abc_Print(-2, "\t         performs combinational equivalence checking\n")
	Abc_Print(-2, "\t-T num : approximate runtime limit in seconds [default = %d]\n", nSeconds)
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", nConfLimit)
	Abc_Print(-2, "\t-I num : limit on the number of clause inspections [default = %d]\n", nInsLimit)
	Abc_Print(-2, "\t-P num : partition size for multi-output networks [default = %s]\n", Buffer)
	Abc_Print(-2, "\t-p     : toggle automatic partitioning [default = %s]\n", abcSelect(fPartition, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle \"SAT only\" and \"FRAIG + SAT\" [default = %s]\n", abcSelect(fSat, "SAT only", "FRAIG + SAT"))
	Abc_Print(-2, "\t-n     : toggle how CIs/COs are matched (by name or by order) [default = %s]\n", abcSelect(fIgnoreNames, "by order", "by name"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\tfile1  : (optional) the file with the first network\n")
	Abc_Print(-2, "\tfile2  : (optional) the file with the second network\n")
	Abc_Print(-2, "\t         if no files are given, uses the current network and its spec\n")
	Abc_Print(-2, "\t         if one file is given, uses the current network and the file\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDCec(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtk1, pNtk2 *Abc_Ntk_t
	var fDelete1, fDelete2 int32
	var pArgvNew *string
	var nArgcNew int32
	var c int32
	var fSat int32
	var fVerbose int32
	var nSeconds int32
	var nConfLimit int32
	var nInsLimit int32
	var fPartition int32
	var fMiter int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fSat = 0
	fVerbose = 0
	nSeconds = 20
	nConfLimit = 10000
	nInsLimit = 0
	fPartition = 0
	fMiter = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "TCIpmsvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "TCIpmsvh") {
		switch c {
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			nSeconds = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nSeconds < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfLimit < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nInsLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nInsLimit < 0 {
				goto usage
			}
			break
		case 'p':
			fPartition ^= 1
			break
		case 'm':
			fMiter ^= 1
			break
		case 's':
			fSat ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		default:
			goto usage
		}
	}

	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if fMiter != 0 {
		if pNtk == nil {
			Abc_Print(-1, "Empty network.\n")
			return 1
		}
		if Abc_NtkIsStrash(pNtk) {
			pNtk1 = pNtk
			fDelete1 = 0

		} else {
			pNtk1 = Abc_NtkStrash(pNtk, 0, 1, 0)
			fDelete1 = 1
		}
		pNtk2 = nil
		fDelete2 = 0

	} else {
		if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1) {
			return 1
		}
	}

	if ((pNtk1 != nil) && Abc_NtkLatchNum(pNtk1)) || ((pNtk2 != nil) && Abc_NtkLatchNum(pNtk2)) {
		if (pNtk1 != nil) && fDelete1 {
			Abc_NtkDelete(pNtk1)
		}
		if (pNtk2 != nil) && (fDelete2 != 0) {
			Abc_NtkDelete(pNtk2)
		}
		Abc_Print(-1, "Currently this command only works for networks without latches. Run \"comb\".\n")
		return 1
	}

	// perform equivalence checking
	if (fSat != 0) && (fMiter != 0) {
		Abc_NtkDSat(pNtk1, nConfLimit, nInsLimit, 0, 0, 0, 0, 0, 0, fVerbose)
	} else {
		Abc_NtkDarCec(pNtk1, pNtk2, nConfLimit, fPartition, fVerbose)
	}

	if fDelete1 != 0 {
		Abc_NtkDelete(pNtk1)
	}
	if fDelete2 != 0 {
		Abc_NtkDelete(pNtk2)
	}
	return 0

usage:
	Abc_Print(-2, "usage: dcec [-T num] [-C num] [-I num] [-mpsvh] <file1> <file2>\n")
	Abc_Print(-2, "\t         performs combinational equivalence checking\n")
	Abc_Print(-2, "\t-T num : approximate runtime limit in seconds [default = %d]\n", nSeconds)
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", nConfLimit)
	Abc_Print(-2, "\t-I num : limit on the number of clause inspections [default = %d]\n", nInsLimit)
	Abc_Print(-2, "\t-m     : toggle working on two networks or a miter [default = %s]\n", abcSelect(fMiter, "miter", "two networks"))
	Abc_Print(-2, "\t-p     : toggle automatic partitioning [default = %s]\n", abcSelect(fPartition, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle \"SAT only\" (miter) or \"FRAIG + SAT\" [default = %s]\n", abcSelect(fSat, "SAT only", "FRAIG + SAT"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\tfile1  : (optional) the file with the first network\n")
	Abc_Print(-2, "\tfile2  : (optional) the file with the second network\n")
	Abc_Print(-2, "\t         if no files are given, uses the current network and its spec\n")
	Abc_Print(-2, "\t         if one file is given, uses the current network and the file\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDSec(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var SecPar Fra_Sec_t
	var pSecPar *Fra_Sec_t = &SecPar
	var pNtk, pNtk1, pNtk2 *Abc_Ntk_t
	var fDelete1, fDelete2 int32
	var pArgvNew *string
	var nArgcNew int32
	var c int32
	var fCheck int32 = 1
	var fIgnoreNames int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Fra_SecSetDefaultParams(pSecPar)
	pSecPar.TimeLimit = 0
	fIgnoreNames = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FTarmfncvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FTarmfncvwh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nFramesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nFramesMax < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.TimeLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.TimeLimit < 0 {
				goto usage
			}
			break
		case 'a':
			pSecPar.fPhaseAbstract ^= 1
			break
		case 'r':
			pSecPar.fRetimeFirst ^= 1
			break
		case 'm':
			pSecPar.fRetimeRegs ^= 1
			break
		case 'f':
			pSecPar.fFraiging ^= 1
			break
		case 'n':
			fIgnoreNames ^= 1
			break
		case 'c':
			fCheck ^= 1
			break
		case 'v':
			pSecPar.fVerbose ^= 1
			break
		case 'w':
			pSecPar.fVeryVerbose ^= 1
			break
		default:
			goto usage
		}
	}

	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, fCheck) {
		return 1
	}
	if Abc_NtkLatchNum(pNtk1) == 0 || Abc_NtkLatchNum(pNtk2) == 0 {
		if fDelete1 != 0 {
			Abc_NtkDelete(pNtk1)
		}
		if fDelete2 != 0 {
			Abc_NtkDelete(pNtk2)
		}
		Abc_Print(-1, "The network has no latches. Used combinational command \"cec\".\n")
		return 0
	}

	if fIgnoreNames != 0 {
		if !fDelete1 {
			pNtk1 = Abc_NtkStrash(pNtk1, 0, 1, 0)
			fDelete1 = 1
		}
		if !(fDelete2 != 0) {
			pNtk2 = Abc_NtkStrash(pNtk2, 0, 1, 0)
			fDelete2 = 1
		}
		Abc_NtkShortNames(pNtk1)
		Abc_NtkShortNames(pNtk2)
	}

	// perform verification
	pAbc.Status = Abc_NtkDarSec(pNtk1, pNtk2, pSecPar)

	if fDelete1 != 0 {
		Abc_NtkDelete(pNtk1)
	}
	if fDelete2 != 0 {
		Abc_NtkDelete(pNtk2)
	}
	return 0

usage:
	Abc_Print(-2, "usage: dsec [-F num] [-T num] [-armfncvwh] <file1> <file2>\n")
	Abc_Print(-2, "\t         performs inductive sequential equivalence checking\n")
	Abc_Print(-2, "\t-F num : the limit on the depth of induction [default = %d]\n", pSecPar.nFramesMax)
	Abc_Print(-2, "\t-T num : the approximate runtime limit (in seconds) [default = %d]\n", pSecPar.TimeLimit)
	Abc_Print(-2, "\t-a     : toggles the use of phase abstraction [default = %s]\n", abcSelect(fPhaseAbstract, "yes", "no"))
	Abc_Print(-2, "\t-r     : toggles forward retiming at the beginning [default = %s]\n", abcSelect(fRetimeFirst, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggles min-register retiming [default = %s]\n", abcSelect(fRetimeRegs, "yes", "no"))
	Abc_Print(-2, "\t-f     : toggles the internal use of fraiging [default = %s]\n", abcSelect(fFraiging, "yes", "no"))
	Abc_Print(-2, "\t-n     : toggles how CIs/COs are matched (by name or by order) [default = %s]\n", abcSelect(fIgnoreNames, "by order", "by name"))
	Abc_Print(-2, "\t-c     : toggles performing internal netlist check [default = %s]\n", abcSelect(fCheck, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggles additional verbose output [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\tfile1  : (optional) the file with the first network\n")
	Abc_Print(-2, "\tfile2  : (optional) the file with the second network\n")
	Abc_Print(-2, "\t         if no files are given, uses the current network and its spec\n")
	Abc_Print(-2, "\t         if one file is given, uses the current network and the file\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDProve(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var SecPar Fra_Sec_t
	var pSecPar *Fra_Sec_t = &SecPar
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var pLogFileName string
	var nBmcFramesMax int32 = 20
	var nBmcConfMax int32 = 2000

	// set defaults
	Fra_SecSetDefaultParams(pSecPar)
	//    pSecPar->TimeLimit = 300;
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "cbAEFCGDVBRTLarmfijkoupwvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "cbAEFCGDVBRTLarmfijkoupwvh") {
		switch c {
		case 'c':
			pSecPar.fTryComb ^= 1
			break
		case 'b':
			pSecPar.fTryBmc ^= 1
			break
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by an integer.\n")
				goto usage
			}
			nBmcFramesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBmcFramesMax < 0 {
				goto usage
			}
			break
		case 'E':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-E\" should be followed by an integer.\n")
				goto usage
			}
			nBmcConfMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBmcConfMax < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nFramesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nFramesMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nBTLimit < 0 {
				goto usage
			}
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nBTLimitGlobal = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nBTLimitGlobal < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nBTLimitInter = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nBTLimitInter < 0 {
				goto usage
			}
			break
		case 'V':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-V\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nBddVarsMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nBddVarsMax < 0 {
				goto usage
			}
			break
		case 'B':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-B\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nBddMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nBddMax < 0 {
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nBddIterMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nBddIterMax < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			pSecPar.nPdrTimeout = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pSecPar.nPdrTimeout < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a file name.\n")
				goto usage
			}
			pLogFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'a':
			pSecPar.fPhaseAbstract ^= 1
			break
		case 'r':
			pSecPar.fRetimeFirst ^= 1
			break
		case 'm':
			pSecPar.fRetimeRegs ^= 1
			break
		case 'f':
			pSecPar.fFraiging ^= 1
			break
		case 'i':
			pSecPar.fInduction ^= 1
			break
		case 'j':
			pSecPar.fInterpolation ^= 1
			break
		case 'k':
			pSecPar.fInterSeparate ^= 1
			break
		case 'o':
			pSecPar.fReorderImage ^= 1
			break
		case 'u':
			pSecPar.fReadUnsolved ^= 1
			break
		case 'p':
			pSecPar.fUsePdr ^= 1
			break
		case 'w':
			pSecPar.fVeryVerbose ^= 1
			break
		case 'v':
			pSecPar.fVerbose ^= 1
			break
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "This command works only for structrally hashed networks. Run \"st\".\n")
		return 0
	}
	if pAbc.fBatchMode && (pAbc.Status == 0 || pAbc.Status == 1) {
		Abc_Print(1, "The miters is already solved; skipping the command.\n")
		return 0
	}

	// perform verification
	pAbc.Status = Abc_NtkDarProve(pNtk, pSecPar, nBmcFramesMax, nBmcConfMax)
	Abc_FrameReplaceCex(pAbc, &pNtk.pSeqModel)
	if pLogFileName != "" {
		Abc_NtkWriteLogFile(pLogFileName, pAbc.pCex, pAbc.Status, pAbc.nFrames, "dprove")
	}

	// read back the resulting unsolved reduced sequential miter
	if pSecPar.fReadUnsolved && pSecPar.nSMnumber >= 0 {
		var FileName string // was [100]byte in C

		FileName = fmt.Sprintf("sm%02d.aig", pSecPar.nSMnumber)
		pNtk = Io_Read(FileName, Io_ReadFileType(FileName), 1, 0)
		if pNtk == nil {
			Abc_Print(-1, "Cannot read back unsolved reduced sequential miter \"%s\",\n", FileName)
		} else {
			Abc_FrameReplaceCurrentNetwork(pAbc, pNtk)
		}
	}
	return 0

usage:
	Abc_Print(-2, "usage: dprove [-AEFCGDVBRT num] [-L file] [-cbarmfijoupvwh]\n")
	Abc_Print(-2, "\t         performs SEC on the sequential miter\n")
	Abc_Print(-2, "\t-A num : the limit on the depth of BMC [default = %d]\n", nBmcFramesMax)
	Abc_Print(-2, "\t-E num : the conflict limit during BMC [default = %d]\n", nBmcConfMax)
	Abc_Print(-2, "\t-F num : the limit on the depth of induction [default = %d]\n", pSecPar.nFramesMax)
	Abc_Print(-2, "\t-C num : the conflict limit at a node during induction [default = %d]\n", pSecPar.nBTLimit)
	Abc_Print(-2, "\t-G num : the global conflict limit during induction [default = %d]\n", pSecPar.nBTLimitGlobal)
	Abc_Print(-2, "\t-D num : the conflict limit during interpolation [default = %d]\n", pSecPar.nBTLimitInter)
	Abc_Print(-2, "\t-V num : the flop count limit for BDD-based reachablity [default = %d]\n", pSecPar.nBddVarsMax)
	Abc_Print(-2, "\t-B num : the BDD size limit in BDD-based reachablity [default = %d]\n", pSecPar.nBddMax)
	Abc_Print(-2, "\t-R num : the max number of reachability iterations [default = %d]\n", pSecPar.nBddIterMax)
	Abc_Print(-2, "\t-T num : the timeout for property directed reachability [default = %d]\n", pSecPar.nPdrTimeout)
	Abc_Print(-2, "\t-L file: the log file name [default = %s]\n", abcDefaultString(pLogFileName, "no logging"))
	Abc_Print(-2, "\t-c     : toggles using CEC before attempting SEC [default = %s]\n", abcSelect(fTryComb, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggles using BMC before attempting SEC [default = %s]\n", abcSelect(fTryBmc, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggles the use of phase abstraction [default = %s]\n", abcSelect(fPhaseAbstract, "yes", "no"))
	Abc_Print(-2, "\t-r     : toggles forward retiming at the beginning [default = %s]\n", abcSelect(fRetimeFirst, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggles min-register retiming [default = %s]\n", abcSelect(fRetimeRegs, "yes", "no"))
	Abc_Print(-2, "\t-f     : toggles the internal use of fraiging [default = %s]\n", abcSelect(fFraiging, "yes", "no"))
	Abc_Print(-2, "\t-i     : toggles the use of induction [default = %s]\n", abcSelect(fInduction, "yes", "no"))
	Abc_Print(-2, "\t-j     : toggles the use of interpolation [default = %s]\n", abcSelect(fInterpolation, "yes", "no"))
	Abc_Print(-2, "\t-k     : toggles applying interpolation to each output [default = %s]\n", abcSelect(fInterSeparate, "yes", "no"))
	Abc_Print(-2, "\t-o     : toggles using BDD variable reordering during image computation [default = %s]\n", abcSelect(fReorderImage, "yes", "no"))
	Abc_Print(-2, "\t-u     : toggles reading back unsolved reduced sequential miter [default = %s]\n", abcSelect(fReadUnsolved, "yes", "no"))
	Abc_Print(-2, "\t-p     : toggles trying property directed reachability in the end [default = %s]\n", abcSelect(fUsePdr, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggles additional verbose output [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\tCommand \"dprove\" can also be used for sequential synthesis (dprove -brjopu)\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbSec(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtk1, pNtk2 *Abc_Ntk_t
	var fDelete1, fDelete2 int32
	var pArgvNew *string
	var nArgcNew int32
	var fMiter, nFrames, fVerbose, c int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fMiter = 1
	nFrames = 2
	fVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Fmvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Fmvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'm':
			fMiter ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		default:
			goto usage
		}
	}

	if fMiter != 0 {
		//        pNtk = Io_Read( argv[globalUtilOptind], Io_ReadFileType(argv[globalUtilOptind]), 1, 0 );
		if argc == globalUtilOptind+1 {
			Abc_Print(-1, "The miter cannot be given on the command line. Use \"read\".\n")
			return 0
		}
		if !Abc_NtkIsStrash(pNtk) {
			Abc_Print(-1, "The miter should be structurally hashed. Use \"st\"\n")
			return 0
		}
		if Abc_NtkDarAbSec(pNtk, nil, nFrames, fVerbose) == 1 {
			pAbc.Status = 1
		} else {
			pAbc.Status = -1
		}

	} else {
		pArgvNew = argv + globalUtilOptind
		nArgcNew = argc - globalUtilOptind
		if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1) {
			return 1
		}
		if Abc_NtkLatchNum(pNtk1) == 0 || Abc_NtkLatchNum(pNtk2) == 0 {
			if fDelete1 != 0 {
				Abc_NtkDelete(pNtk1)
			}
			if fDelete2 != 0 {
				Abc_NtkDelete(pNtk2)
			}
			Abc_Print(-1, "The network has no latches. Used combinational command \"cec\".\n")
			return 0
		}
		// perform verification
		if Abc_NtkDarAbSec(pNtk1, pNtk2, nFrames, fVerbose) == 1 {
			pAbc.Status = 1
		} else {
			pAbc.Status = -1
		}
		if fDelete1 != 0 {
			Abc_NtkDelete(pNtk1)
		}
		if fDelete2 != 0 {
			Abc_NtkDelete(pNtk2)
		}
	}
	return 0

usage:
	Abc_Print(-2, "usage: absec [-F num] [-mv] <file1> <file2>\n")
	Abc_Print(-2, "\t         performs SEC by applying CEC to several timeframes\n")
	Abc_Print(-2, "\t-F num : the total number of timeframes to use [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-m     : toggles miter vs. two networks [default = %s]\n", abcSelect(fMiter, "miter", "two networks"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\tfile1  : (optional) the file with the first network\n")
	Abc_Print(-2, "\tfile2  : (optional) the file with the second network\n")
	Abc_Print(-2, "\t         if no files are given, uses the current network and its spec\n")
	Abc_Print(-2, "\t         if one file is given, uses the current network and the file\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSimSec(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var Pars Ssw_Pars_t
	var pPars *Ssw_Pars_t = &Pars
	var pNtk, pNtk1, pNtk2 *Abc_Ntk_t
	var fDelete1, fDelete2 int32
	var pArgvNew *string
	var nArgcNew, c int32
	var fMiter int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fMiter = 1
	Ssw_ManSetDefaultParams(pPars)
	pPars.fPartSigCorr = 1
	pPars.fVerbose = 1
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FDcymvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FDcymvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nFramesK = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nFramesK < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nIsleDist = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nIsleDist < 0 {
				goto usage
			}
			break
		case 'm':
			fMiter ^= 1
			break
		case 'c':
			pPars.fPartSigCorr ^= 1
			break
		case 'y':
			pPars.fDumpSRInit ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		default:
			goto usage
		}
	}

	if fMiter != 0 {
		//        Abc_Ntk_t * pNtkA, * pNtkB;
		if !Abc_NtkIsStrash(pNtk) {
			Abc_Print(-1, "This command works only for structrally hashed networks. Run \"st\".\n")
			return 0
		}
		Abc_NtkDarSimSec(pNtk, nil, pPars)
		/*
		   pNtkA = Abc_NtkDup( pNtk );
		   pNtkB = Abc_NtkDup( pNtk );
		   Abc_NtkDarSimSec( pNtkA, pNtkB, pPars );
		   Abc_NtkDelete( pNtkA );
		   Abc_NtkDelete( pNtkB );
		*/

	} else {
		pArgvNew = argv + globalUtilOptind
		nArgcNew = argc - globalUtilOptind
		if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1) {
			return 1
		}
		if Abc_NtkLatchNum(pNtk1) == 0 || Abc_NtkLatchNum(pNtk2) == 0 {
			if fDelete1 != 0 {
				Abc_NtkDelete(pNtk1)
			}
			if fDelete2 != 0 {
				Abc_NtkDelete(pNtk2)
			}
			Abc_Print(-1, "The network has no latches. Used combinational command \"cec\".\n")
			return 0
		}
		// perform verification
		Abc_NtkDarSimSec(pNtk1, pNtk2, pPars)
		if fDelete1 != 0 {
			Abc_NtkDelete(pNtk1)
		}
		if fDelete2 != 0 {
			Abc_NtkDelete(pNtk2)
		}
	}
	return 0

usage:
	Abc_Print(-2, "usage: simsec [-FD num] [-mcyv] <file1> <file2>\n")
	Abc_Print(-2, "\t         performs SEC using structural similarity\n")
	Abc_Print(-2, "\t-F num : the limit on the depth of induction [default = %d]\n", pPars.nFramesK)
	Abc_Print(-2, "\t-D num : the distance for extending islands [default = %d]\n", pPars.nIsleDist)
	Abc_Print(-2, "\t-m     : toggles miter vs. two networks [default = %s]\n", abcSelect(fMiter, "miter", "two networks"))
	Abc_Print(-2, "\t-c     : uses partial vs. full signal correspondence [default = %s]\n", abcSelect(fPartSigCorr, "partial", "full"))
	Abc_Print(-2, "\t-y     : dumps speculatively reduced miter of the classes [default = %s]\n", abcSelect(fDumpSRInit, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\tfile1  : (optional) the file with the first network\n")
	Abc_Print(-2, "\tfile2  : (optional) the file with the second network\n")
	Abc_Print(-2, "\t         if no files are given, uses the current network and its spec\n")
	Abc_Print(-2, "\t         if one file is given, uses the current network and the file\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandMatch(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtk1, pNtk2, pNtkRes *Abc_Ntk_t
	var fDelete1, fDelete2 int32
	var pArgvNew *string
	var nArgcNew, c int32
	var fMiter int32
	var nDist int32
	var fVerbose int32

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	fMiter = 0
	nDist = 0
	fVerbose = 1
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Dmvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Dmvh") {
		switch c {
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			nDist = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nDist < 0 {
				goto usage
			}
			break
		case 'm':
			fMiter ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		default:
			goto usage
		}
	}

	if fMiter != 0 {
		//        Abc_Ntk_t * pNtkA, * pNtkB;
		if !Abc_NtkIsStrash(pNtk) {
			Abc_Print(-1, "This command works only for structrally hashed networks. Run \"st\".\n")
			return 0
		}
		pNtkRes = Abc_NtkDarMatch(pNtk, nil, nDist, fVerbose)
		/*
		   pNtkA = Abc_NtkDup( pNtk );
		   pNtkB = Abc_NtkDup( pNtk );
		   Abc_NtkDarSimSec( pNtkA, pNtkB, pPars );
		   Abc_NtkDelete( pNtkA );
		   Abc_NtkDelete( pNtkB );
		*/

	} else {
		pArgvNew = argv + globalUtilOptind
		nArgcNew = argc - globalUtilOptind
		if !Abc_NtkPrepareTwoNtks(os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1) {
			return 1
		}
		if Abc_NtkLatchNum(pNtk1) == 0 || Abc_NtkLatchNum(pNtk2) == 0 {
			if fDelete1 != 0 {
				Abc_NtkDelete(pNtk1)
			}
			if fDelete2 != 0 {
				Abc_NtkDelete(pNtk2)
			}
			Abc_Print(-1, "The network has no latches. Used combinational command \"cec\".\n")
			return 0
		}
		// perform verification
		pNtkRes = Abc_NtkDarMatch(pNtk1, pNtk2, nDist, fVerbose)
		if fDelete1 != 0 {
			Abc_NtkDelete(pNtk1)
		}
		if fDelete2 != 0 {
			Abc_NtkDelete(pNtk2)
		}
	}
	if pNtkRes == nil {
		Abc_Print(-1, "Matching has failed.\n")
		return 1
	}
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkRes)
	return 0

usage:
	Abc_Print(-2, "usage: match [-D num] [-mv] <file1> <file2>\n")
	Abc_Print(-2, "\t         detects structural similarity using simulation\n")
	Abc_Print(-2, "\t         replaces the current network by the miter of differences\n")
	Abc_Print(-2, "\t-D num : the distance for extending differences [default = %d]\n", nDist)
	Abc_Print(-2, "\t-m     : toggles miter vs. two networks [default = %s]\n", abcSelect(fMiter, "miter", "two networks"))
	Abc_Print(-2, "\t-v     : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\tfile1  : (optional) the file with the first network\n")
	Abc_Print(-2, "\tfile2  : (optional) the file with the second network\n")
	Abc_Print(-2, "\t         if no files are given, uses the current network and its spec\n")
	Abc_Print(-2, "\t         if one file is given, uses the current network and the file\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSat(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var RetValue int32
	var fVerbose int32
	var nConfLimit int32
	var nInsLimit int32
	var clk abctime
	// set defaults
	fVerbose = 0
	nConfLimit = 0
	nInsLimit = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CIvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "CIvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfLimit < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nInsLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nInsLimit < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkLatchNum(pNtk) > 0 {
		Abc_Print(-1, "Currently can only solve the miter for combinational circuits.\n")
		return 0
	}

	clk = Abc_Clock()
	if Abc_NtkIsStrash(pNtk) {
		RetValue = Abc_NtkMiterSat(pNtk, ABC_INT64_T(nConfLimit), ABC_INT64_T(nInsLimit), fVerbose, nil, nil)

	} else {
		assert(Abc_NtkIsLogic(pNtk), "Abc_NtkIsLogic(pNtk)")
		Abc_NtkToBdd(pNtk)
		RetValue = Abc_NtkMiterSat(pNtk, ABC_INT64_T(nConfLimit), ABC_INT64_T(nInsLimit), fVerbose, nil, nil)
	}

	// verify that the pattern is correct
	if RetValue == 0 && Abc_NtkPoNum(pNtk) == 1 {
		//int i;
		//Abc_Obj_t * pObj;
		pSimInfo := Abc_NtkVerifySimulatePattern(pNtk, pNtk.pModel)
		if *pSimInfo != 1 {
			Abc_Print(1, "ERROR in Abc_NtkMiterSat(): Generated counter example is invalid.\n")
		}
		ABC_FREE(pSimInfo)
		/*
		   // print model
		   Abc_NtkForEachPi( pNtk, pObj, i )
		   {
		       Abc_Print( -1, "%d", (int)(pNtk->pModel[i] > 0) );
		       if ( i == 70 )
		           break;
		   }
		   Abc_Print( -1, "\n" );
		*/
	}
	pAbc.Status = RetValue
	if RetValue == -1 {
		Abc_Print(1, "UNDECIDED      ")
	} else if RetValue == 0 {
		Abc_Print(1, "SATISFIABLE    ")
	} else {
		Abc_Print(1, "UNSATISFIABLE  ")
	}
	//Abc_Print( -1, "\n" );
	Abc_PrintTime(1, "Time", Abc_Clock()-clk)
	return 0

usage:
	Abc_Print(-2, "usage: sat [-C num] [-I num] [-vh]\n")
	Abc_Print(-2, "\t         solves the combinational miter using SAT solver MiniSat-1.14\n")
	Abc_Print(-2, "\t         derives CNF from the current network and leave it unchanged\n")
	Abc_Print(-2, "\t         (there is also a newer SAT solving command \"dsat\")\n")
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", nConfLimit)
	Abc_Print(-2, "\t-I num : limit on the number of inspections [default = %d]\n", nInsLimit)
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDSat(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var RetValue int32
	var fAlignPol int32
	var fAndOuts int32
	var fNewSolver int32
	var fSilent int32
	var fShowPattern int32
	var fVerbose int32
	var nConfLimit int32
	var nLearnedStart int32
	var nLearnedDelta int32
	var nLearnedPerce int32
	var nInsLimit int32
	var clk abctime

	// set defaults
	fAlignPol = 0
	fAndOuts = 0
	fNewSolver = 0
	fSilent = 0
	fShowPattern = 0
	fVerbose = 0
	nConfLimit = 0
	nInsLimit = 0
	nLearnedStart = 0
	nLearnedDelta = 0
	nLearnedPerce = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CILDEpansvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "CILDEpansvwh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfLimit < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nInsLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nInsLimit < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nLearnedStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLearnedStart < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			nLearnedDelta = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLearnedDelta < 0 {
				goto usage
			}
			break
		case 'E':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-E\" should be followed by an integer.\n")
				goto usage
			}
			nLearnedPerce = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLearnedPerce < 0 {
				goto usage
			}
			break
		case 'p':
			fAlignPol ^= 1
			break
		case 'a':
			fAndOuts ^= 1
			break
		case 'n':
			fNewSolver ^= 1
			break
		case 's':
			fSilent ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fShowPattern ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if argc == globalUtilOptind+1 {
		var pModel *int32 = nil

		// get the input file name
		var pFileName string = argv[globalUtilOptind]
		var pFile *os.File = os.Open(pFileName)
		if pFile == nil {
			fmt.Printf("Cannot open file \"%s\" for writing.\n", pFileName)
			return 0
		}
		_ = pFile.Close()
		piNum := int32(0)
		if pNtk != nil {
			piNum = Abc_NtkPiNum(pNtk)
		}
		Cnf_DataSolveFromFile(pFileName, nConfLimit, nLearnedStart, nLearnedDelta, nLearnedPerce, fVerbose, fShowPattern, &pModel, piNum)
		if (pModel != nil) && (pNtk != nil) {
			pSimInfo := Abc_NtkVerifySimulatePattern(pNtk, pModel)
			if *pSimInfo != 1 {
				Abc_Print(1, "ERROR in mapping PIs into SAT vars: Generated CEX is invalid.\n")
			}
			ABC_FREE(pSimInfo)
			pAbc.pCex = Abc_CexCreate(0, Abc_NtkPiNum(pNtk), pModel, 0, 0, 0)
		}
		ABC_FREE(pModel)
		return 0
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkLatchNum(pNtk) > 0 {
		Abc_Print(-1, "Currently can only solve the miter for combinational circuits.\n")
		return 0
	}

	if Abc_NtkPoNum(pNtk) != 1 {
		Abc_Print(-1, "Currently expects a single-output miter.\n")
		return 0
	}

	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Currently only works for structurally hashed circuits.\n")
		return 0
	}
	clk = Abc_Clock()
	RetValue = Abc_NtkDSat(pNtk, ABC_INT64_T(nConfLimit), ABC_INT64_T(nInsLimit), nLearnedStart, nLearnedDelta, nLearnedPerce, fAlignPol, fAndOuts, fNewSolver, fVerbose)
	// verify that the pattern is correct
	if RetValue == 0 && Abc_NtkPoNum(pNtk) == 1 {
		pSimInfo := Abc_NtkVerifySimulatePattern(pNtk, pNtk.pModel)
		if *pSimInfo != 1 {
			Abc_Print(1, "ERROR in Abc_NtkMiterSat(): Generated counter example is invalid.\n")
		}
		ABC_FREE(pSimInfo)
		pAbc.pCex = Abc_CexCreate(0, Abc_NtkPiNum(pNtk), pNtk.pModel, 0, 0, 0)
	}
	pAbc.Status = RetValue
	if !(fSilent != 0) {
		if RetValue == -1 {
			Abc_Print(1, "UNDECIDED      ")
		} else if RetValue == 0 {
			Abc_Print(1, "SATISFIABLE    ")
		} else {
			Abc_Print(1, "UNSATISFIABLE  ")
		}
		Abc_PrintTime(1, "Time", Abc_Clock()-clk)
	}
	return 0

usage:
	Abc_Print(-2, "usage: dsat [-CILDE num] [-pansvh]\n")
	Abc_Print(-2, "\t         solves the combinational miter using SAT solver MiniSat-1.14\n")
	Abc_Print(-2, "\t         derives CNF from the current network and leaves it unchanged\n")
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", nConfLimit)
	Abc_Print(-2, "\t-I num : limit on the number of inspections [default = %d]\n", nInsLimit)
	Abc_Print(-2, "\t-L num : starting value for learned clause removal [default = %d]\n", nLearnedStart)
	Abc_Print(-2, "\t-D num : delta value for learned clause removal [default = %d]\n", nLearnedDelta)
	Abc_Print(-2, "\t-E num : ratio percentage for learned clause removal [default = %d]\n", nLearnedPerce)
	Abc_Print(-2, "\t-p     : align polarity of SAT variables [default = %s]\n", abcSelect(fAlignPol, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggle ANDing/ORing of miter outputs [default = %s]\n", abcSelect(fAndOuts, "ANDing", "ORing"))
	Abc_Print(-2, "\t-n     : toggle using new solver [default = %s]\n", abcSelect(fNewSolver, "yes", "no"))
	Abc_Print(-2, "\t-s     : enable silent computation (no reporting) [default = %s]\n", abcSelect(fSilent, "yes", "no"))
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandXSat(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var clk abctime
	var c int32
	var fVerbose int32
	var nConfLimit int32
	var nInsLimit int32
	var nLearnedStart int32
	var nLearnedDelta int32
	var nLearnedPerce int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CILDEhv"); c != -1; c = Extra_UtilGetopt(argc, argv, "CILDEhv") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfLimit < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nInsLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nInsLimit < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nLearnedStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLearnedStart < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			nLearnedDelta = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLearnedDelta < 0 {
				goto usage
			}
			break
		case 'E':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-E\" should be followed by an integer.\n")
				goto usage
			}
			nLearnedPerce = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLearnedPerce < 0 {
				goto usage
			}
			break
		case 'h':
			goto usage
		case 'v':
			fVerbose ^= 1
			break

		default:
			goto usage
		}
	}

	if argc == globalUtilOptind+1 {
		var pFileName string = argv[globalUtilOptind]
		var p *xSAT_Solver_t
		var status int32

		var pFile *os.File = os.Open(pFileName)
		if pFile == nil {
			fmt.Printf("Cannot open file \"%s\" for writing.\n", pFileName)
			return 0
		}
		xSAT_SolverParseDimacs(pFile, &p)

		clk = Abc_Clock()
		status = xSAT_SolverSolve(p)
		_ = pFile.Close()

		xSAT_SolverPrintStats(p)
		if status == 0 {
			Abc_Print(1, "UNDECIDED      ")
		} else if status == 1 {
			Abc_Print(1, "SATISFIABLE    ")
		} else {
			Abc_Print(1, "UNSATISFIABLE  ")
		}

		Abc_PrintTime(1, "Time", Abc_Clock()-clk)

		xSAT_SolverDestroy(p)
		return 0
	}

usage:
	Abc_Print(-2, "usage: xsat [-CILDE num] [-hv]<file>.cnf\n")
	Abc_Print(-2, "\t         solves the combinational miter using SAT solver MiniSat-1.14\n")
	Abc_Print(-2, "\t         derives CNF from the current network and leaves it unchanged\n")
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", nConfLimit)
	Abc_Print(-2, "\t-I num : limit on the number of inspections [default = %d]\n", nInsLimit)
	Abc_Print(-2, "\t-L num : starting value for learned clause removal [default = %d]\n", nLearnedStart)
	Abc_Print(-2, "\t-D num : delta value for learned clause removal [default = %d]\n", nLearnedDelta)
	Abc_Print(-2, "\t-E num : ratio percentage for learned clause removal [default = %d]\n", nLearnedPerce)
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandSatoko(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	// create default options
	var opts satoko_opts_t
	var popts *satoko_opts_t
	satoko_default_opts(&opts)

	// override default options
	popts = Cmd_DeriveOptionFromSettings(argc, argv)
	if popts == nil {
		goto usage
	}
	memcpy(&opts, popts, sizeof(satoko_opts_t))
	ABC_FREE(popts)

	if argc == globalUtilOptind+1 {
		var clk abctime
		var pFileName string = argv[globalUtilOptind]
		var p *satoko_t
		var status int32

		status = satoko_parse_dimacs(pFileName, &p)
		satoko_configure(p, &opts)

		clk = Abc_Clock()
		if status == SATOKO_OK {
			status = satoko_solve(p)
		}

		if status == SATOKO_UNDEC {
			Abc_Print(1, "UNDECIDED      ")
		} else if status == SATOKO_SAT {
			Abc_Print(1, "SATISFIABLE    ")
		} else {
			Abc_Print(1, "UNSATISFIABLE  ")
		}

		Abc_PrintTime(1, "Time", Abc_Clock()-clk)

		satoko_destroy(p)
		return 0
	}

usage:
	// SATOKO_ACT_VAR_FIXED is disabled in this build.
	Abc_Print(-2, "usage: satoko [-CPDEFGHIJKLMNOQRS num] [-hv]<file>.cnf\n")
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", opts.conf_limit)
	Abc_Print(-2, "\t-P num : limit on the number of propagations [default = %d]\n", opts.conf_limit)
	Abc_Print(-2, "\n\tConstants used for restart heuristic:\n")
	Abc_Print(-2, "\t-D num : Constant value used by restart heuristics in forcing restarts [default = %f]\n", opts.f_rst)
	Abc_Print(-2, "\t-E num : Constant value used by restart heuristics in  blocking restarts [default = %f]\n", opts.b_rst)
	Abc_Print(-2, "\t-F num : Lower bound n.of conflicts for start blocking restarts [default = %d]\n", opts.fst_block_rst)
	Abc_Print(-2, "\t-G num : Size of the moving avarege queue for LBD (force restart) [default = %d]\n", opts.sz_lbd_bqueue)
	Abc_Print(-2, "\t-H num : Size of the moving avarege queue for Trail size (block restart) [default = %d]\n", opts.sz_trail_bqueue)
	Abc_Print(-2, "\n\tConstants used for clause database reduction heuristic:\n")
	Abc_Print(-2, "\t-I num : N.of conflicts before first clause databese reduction [default = %d]\n", opts.n_conf_fst_reduce)
	Abc_Print(-2, "\t-J num : Increment to reduce [default = %d]\n", opts.inc_reduce)
	Abc_Print(-2, "\t-K num : Special increment to reduce [default = %d]\n", opts.inc_special_reduce)
	Abc_Print(-2, "\t-L num : Protecs clauses from deletion for one turn if its LBD is lower [default = %d]\n", opts.lbd_freeze_clause)
	Abc_Print(-2, "\t-M num : Percentage of learned clauses to remove [default = %d]\n", int32((100 * opts.learnt_ratio)))
	Abc_Print(-2, "\t-N num : Max percentage of garbage in clause database [default = %d]\n", int32((100 * opts.garbage_max_ratio)))
	Abc_Print(-2, "\n\tConstants used for binary resolution (clause minimization):\n")
	Abc_Print(-2, "\t-O num : Max clause size for binary resolution [default = %d]\n", opts.clause_max_sz_bin_resol)
	Abc_Print(-2, "\t-Q num : Min clause LBD for binary resolution [default = %d]\n", opts.clause_min_lbd_bin_resol)
	Abc_Print(-2, "\n\tConstants used for branching (VSIDS heuristic):\n")
	Abc_Print(-2, "\t-R num : Clause activity decay factor (when using float clause activity) [default = %f]\n", opts.clause_decay)
	Abc_Print(-2, "\t-S num : Varibale activity decay factor [default = %f]\n", opts.var_decay)
	Abc_Print(-2, "\n\t-v     : prints verbose information [default = %s]\n", abcSelect(verbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Satoko(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c, fSplit, fIncrem int32

	var opts satoko_opts_t
	satoko_default_opts(&opts)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Csivh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Csivh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			opts.conf_limit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if opts.conf_limit < 0 {
				goto usage
			}
			break
		case 's':
			fSplit ^= 1
			break
		case 'i':
			fIncrem ^= 1
			break
		case 'v':
			opts.verbose ^= 1
			break
		case 'h':
			goto usage

		default:
			goto usage
		}
	}
	if argc == globalUtilOptind+1 {
		Gia_ManSatokoDimacs(argv[globalUtilOptind], &opts)
		return 0
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Satoko(): There is no AIG.\n")
		return 1
	}
	Gia_ManSatokoCall(pAbc.pGia, &opts, fSplit, fIncrem)
	return 0

usage:
	Abc_Print(-2, "usage: &satoko [-C num] [-sivh] <file.cnf>\n")
	Abc_Print(-2, "\t             run Satoko by Bruno Schmitt\n")
	Abc_Print(-2, "\t-C num     : limit on the number of conflicts [default = %d]\n", opts.conf_limit)
	Abc_Print(-2, "\t-s         : split multi-output miter into individual outputs [default = %s]\n", abcSelect(fSplit, "yes", "no"))
	Abc_Print(-2, "\t-i         : split multi-output miter and solve incrementally [default = %s]\n", abcSelect(fIncrem, "yes", "no"))
	Abc_Print(-2, "\t-v         : prints verbose information [default = %s]\n", abcSelect(verbose, "yes", "no"))
	Abc_Print(-2, "\t<file.cnf> : (optional) CNF file to solve\n")
	Abc_Print(-2, "\t-h         : print the command usage\n")
	return 1
}

