/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandPSat(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var RetValue int32
	var c int32
	var nAlgo int32
	var nPartSize int32
	var nConfPart int32
	var nConfTotal int32
	var fAlignPol int32
	var fSynthesize int32
	var fVerbose int32
	var clk abctime

	// set defaults
	nAlgo = 0
	nPartSize = 10000
	nConfPart = 0
	nConfTotal = 1000000
	fAlignPol = 1
	fSynthesize = 0
	fVerbose = 1
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "APCpsvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "APCpsvh") {
		switch c {
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by an integer.\n")
				goto usage
			}
			nAlgo = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nAlgo < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nPartSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPartSize < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfTotal = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfTotal < 0 {
				goto usage
			}
			break
		case 'p':
			fAlignPol ^= 1
			break
		case 's':
			fSynthesize ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkLatchNum(pNtk) > 0 {
		Abc_Print(-1, "Currently can only solve the miter for combinational circuits.\n")
		return 0
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Currently only works for structurally hashed circuits.\n")
		return 0
	}

	clk = Abc_Clock()
	RetValue = Abc_NtkPartitionedSat(pNtk, nAlgo, nPartSize, nConfPart, nConfTotal, fAlignPol, fSynthesize, fVerbose)
	// verify that the pattern is correct
	if RetValue == 0 && Abc_NtkPoNum(pNtk) == 1 {
		//int i;
		//Abc_Obj_t * pObj;
		var pSimInfo *int32 = Abc_NtkVerifySimulatePattern(pNtk, pNtk.pModel)
		if pSimInfo[0] != 1 {
			Abc_Print(1, "ERROR in Abc_NtkMiterSat(): Generated counter example is invalid.\n")
		}
		ABC_FREE(pSimInfo)
		/*
		   // print model
		   Abc_NtkForEachPi( pNtk, pObj, i )
		   {
		       Abc_Print( -1, "%d", (int)(pNtk->pModel[i] > 0) );
		       if ( i == 70 )
		           break;
		   }
		   Abc_Print( -1, "\n" );
		*/
	}

	if RetValue == -1 {
		Abc_Print(1, "UNDECIDED      ")
	} else if RetValue == 0 {
		Abc_Print(1, "SATISFIABLE    ")
	} else {
		Abc_Print(1, "UNSATISFIABLE  ")
	}
	//Abc_Print( -1, "\n" );
	Abc_PrintTime(1, "Time", Abc_Clock()-clk)
	return 0

usage:
	Abc_Print(-2, "usage: psat [-APC num] [-psvh]\n")
	Abc_Print(-2, "\t         solves the combinational miter using partitioning\n")
	Abc_Print(-2, "\t         (derives CNF from the current network and leave it unchanged)\n")
	Abc_Print(-2, "\t         for multi-output miters, tries to prove that the AND of POs is always 0\n")
	Abc_Print(-2, "\t         (if POs should be ORed instead of ANDed, use command \"orpos\")\n")
	Abc_Print(-2, "\t-A num : partitioning algorithm [default = %d]\n", nAlgo)
	Abc_Print(-2, "\t         0 : no partitioning\n")
	Abc_Print(-2, "\t         1 : partitioning by level\n")
	Abc_Print(-2, "\t         2 : DFS post-order\n")
	Abc_Print(-2, "\t         3 : DFS pre-order\n")
	Abc_Print(-2, "\t         4 : bit-slicing\n")
	Abc_Print(-2, "\t         partitions are ordered by level (high level first)\n")
	Abc_Print(-2, "\t-P num : limit on the partition size [default = %d]\n", nPartSize)
	Abc_Print(-2, "\t-C num : limit on the number of conflicts [default = %d]\n", nConfTotal)
	Abc_Print(-2, "\t-p     : align polarity of SAT variables [default = %s]\n", abcSelect(fAlignPol, "yes", "no"))
	Abc_Print(-2, "\t-s     : apply logic synthesis to each partition [default = %s]\n", abcSelect(fSynthesize, "yes", "no"))
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandProve(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk, pNtkTemp *Abc_Ntk_t
	var Params Prove_Params_t
	var pParams *Prove_Params_t = &Params
	var c, RetValue int32
	var clk abctime

	pNtk = Abc_FrameReadNtk(pAbc)
	// set defaults
	Prove_ParamsSetDefault(pParams)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NCFGLIrfbvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NCFGLIrfbvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nItersMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nItersMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nMiteringLimitStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nMiteringLimitStart < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nFraigingLimitStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nFraigingLimitStart < 0 {
				goto usage
			}
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nFraigingLimitMulti = float32(abcAtoi(argv[globalUtilOptind]))
			globalUtilOptind++
			if pParams.nFraigingLimitMulti < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nMiteringLimitLast = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nMiteringLimitLast < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			pParams.nTotalInspectLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pParams.nTotalInspectLimit < 0 {
				goto usage
			}
			break
		case 'r':
			pParams.fUseRewriting ^= 1
			break
		case 'f':
			pParams.fUseFraiging ^= 1
			break
		case 'b':
			pParams.fUseBdds ^= 1
			break
		case 'v':
			pParams.fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if Abc_NtkLatchNum(pNtk) > 0 {
		Abc_Print(-1, "Currently can only solve the miter for combinational circuits.\n")
		return 0
	}
	if Abc_NtkCoNum(pNtk) != 1 {
		Abc_Print(-1, "Currently can only solve the miter with one output.\n")
		return 0
	}
	clk = Abc_Clock()

	if Abc_NtkIsStrash(pNtk) {
		pNtkTemp = Abc_NtkDup(pNtk)
	} else {
		pNtkTemp = Abc_NtkStrash(pNtk, 0, 0, 0)
	}

	RetValue = Abc_NtkMiterProve(&pNtkTemp, pParams)

	// verify that the pattern is correct
	if RetValue == 0 {
		var pSimInfo *int32 = Abc_NtkVerifySimulatePattern(pNtk, pNtkTemp.pModel)
		if pSimInfo[0] != 1 {
			Abc_Print(1, "ERROR in Abc_NtkMiterProve(): Generated counter-example is invalid.\n")
		}
		ABC_FREE(pSimInfo)
	}
	pAbc.Status = RetValue
	if RetValue == -1 {
		Abc_Print(1, "UNDECIDED      ")
	} else if RetValue == 0 {
		Abc_Print(1, "SATISFIABLE    ")
	} else {
		Abc_Print(1, "UNSATISFIABLE  ")
	}
	//Abc_Print( -1, "\n" );

	Abc_PrintTime(1, "Time", Abc_Clock()-clk)
	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkTemp)
	return 0

usage:
	Abc_Print(-2, "usage: prove [-NCFGLI num] [-rfbvh]\n")
	Abc_Print(-2, "\t         solves combinational miter by rewriting, FRAIGing, and SAT\n")
	Abc_Print(-2, "\t         replaces the current network by the cone modified by rewriting\n")
	Abc_Print(-2, "\t         (there is also newer CEC command \"iprove\")\n")
	Abc_Print(-2, "\t-N num : max number of iterations [default = %d]\n", pParams.nItersMax)
	Abc_Print(-2, "\t-C num : max starting number of conflicts in mitering [default = %d]\n", pParams.nMiteringLimitStart)
	Abc_Print(-2, "\t-F num : max starting number of conflicts in fraiging [default = %d]\n", pParams.nFraigingLimitStart)
	Abc_Print(-2, "\t-G num : multiplicative coefficient for fraiging [default = %d]\n", int32(pParams.nFraigingLimitMulti))
	Abc_Print(-2, "\t-L num : max last-gasp number of conflicts in mitering [default = %d]\n", pParams.nMiteringLimitLast)
	Abc_Print(-2, "\t-I num : max number of clause inspections in all SAT calls [default = %d]\n", int32(pParams.nTotalInspectLimit))
	Abc_Print(-2, "\t-r     : toggle the use of rewriting [default = %s]\n", abcSelect(fUseRewriting, "yes", "no"))
	Abc_Print(-2, "\t-f     : toggle the use of FRAIGing [default = %s]\n", abcSelect(fUseFraiging, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggle the use of BDDs [default = %s]\n", abcSelect(fUseBdds, "yes", "no"))
	Abc_Print(-2, "\t-v     : prints verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

