/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandBmc(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var nFrames int32
	var nSizeMax int32
	var nBTLimit int32
	var nBTLimitAll int32
	var nNodeDelta int32
	var fRewrite int32
	var fNewAlgo int32
	var nCofFanLit int32
	var fVerbose int32
	var iFrames int32
	var fUseSatoko int32
	var pLogFileName string

	// set defaults
	nFrames = 20
	nSizeMax = 100000
	nBTLimit = 0
	nBTLimitAll = 0
	nNodeDelta = 1000
	fRewrite = 0
	fNewAlgo = 1
	nCofFanLit = 0
	fVerbose = 0
	fUseSatoko = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FNCGDLrsvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FNCGDLrsvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nSizeMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBTLimit < 0 {
				goto usage
			}
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by an integer.\n")
				goto usage
			}
			nBTLimitAll = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBTLimitAll < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			nNodeDelta = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodeDelta < 0 {
				goto usage
			}
			break
			/*
			   case 'L':
			       if ( globalUtilOptind >= argc )
			       {
			           Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
			           goto usage;
			       }
			       nCofFanLit = atoi(argv[globalUtilOptind]);
			       globalUtilOptind++;
			       if ( nCofFanLit < 0 )
			           goto usage;
			       break;
			*/
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a file name.\n")
				goto usage
			}
			pLogFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'r':
			fRewrite ^= 1
			break
		case 'a':
			fNewAlgo ^= 1
			break
		case 's':
			fUseSatoko ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Currently only works for structurally hashed circuits.\n")
		return 0
	}
	if Abc_NtkLatchNum(pNtk) == 0 {
		Abc_Print(-1, "Does not work for combinational networks.\n")
		return 0
	}
	if pAbc.fBatchMode && (pAbc.Status == 0 || pAbc.Status == 1) {
		Abc_Print(1, "The miters is already solved; skipping the command.\n")
		return 0
	}
	pAbc.Status = Abc_NtkDarBmc(pNtk, 0, nFrames, nSizeMax, nNodeDelta, 0, nBTLimit, nBTLimitAll, fRewrite, fNewAlgo, 0, nCofFanLit, fVerbose, &iFrames, fUseSatoko)
	pAbc.nFrames = iFrames
	Abc_FrameReplaceCex(pAbc, &pNtk.pSeqModel)
	if pLogFileName != "" {
		Abc_NtkWriteLogFile(pLogFileName, pAbc.pCex, pAbc.Status, pAbc.nFrames, "bmc")
	}
	return 0

usage:
	Abc_Print(-2, "usage: bmc [-FNC num] [-L file] [-rcsvh]\n")
	Abc_Print(-2, "\t         performs bounded model checking with static unrolling\n")
	Abc_Print(-2, "\t-F num : the number of time frames [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-N num : the max number of nodes in the frames [default = %d]\n", nSizeMax)
	Abc_Print(-2, "\t-C num : the max number of conflicts at a node [default = %d]\n", nBTLimit)
	//    Abc_Print( -2, "\t-L num : the limit on fanout count of resets/enables to cofactor [default = %d]\n", nCofFanLit );
	Abc_Print(-2, "\t-L file: the log file name [default = %s]\n", abcDefaultString(pLogFileName, "no logging"))
	Abc_Print(-2, "\t-r     : toggle the use of rewriting [default = %s]\n", abcSelect(fRewrite, "yes", "no"))
	//    Abc_Print( -2, "\t-a     : toggle SAT sweeping and SAT solving [default = %s]\n", abcSelect(fNewAlgo, "SAT solving", "SAT sweeping") );
	Abc_Print(-2, "\t-s     : toggle using Satoko by Bruno Schmitt [default = %s]\n", abcSelect(fUseSatoko, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandBmc2(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc)
	var c int32
	var nStart int32
	var nFrames int32
	var nSizeMax int32
	var nBTLimit int32
	var nBTLimitAll int32
	var nNodeDelta int32
	var nTimeOut int32
	var fRewrite int32
	var fNewAlgo int32
	var fOrDecomp int32
	var fVerbose int32
	var iFrames int32
	var fUseSatoko int32
	var pLogFileName string

	// set defaults
	nStart = 0
	nFrames = 0
	nSizeMax = 200000
	nBTLimit = 0
	nBTLimitAll = 0
	nNodeDelta = 2000
	nTimeOut = 0
	fRewrite = 0
	fNewAlgo = 0
	fOrDecomp = 0
	fVerbose = 0
	fUseSatoko = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "SFNTCGDLrusvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "SFNTCGDLrusvh") {
		switch c {
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			nStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nStart < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nSizeMax < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			nTimeOut = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nTimeOut < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBTLimit < 0 {
				goto usage
			}
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by an integer.\n")
				goto usage
			}
			nBTLimitAll = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBTLimitAll < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			nNodeDelta = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodeDelta < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by a file name.\n")
				goto usage
			}
			pLogFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'r':
			fRewrite ^= 1
			break
		case 'a':
			fNewAlgo ^= 1
			break
		case 'u':
			fOrDecomp ^= 1
			break
		case 's':
			fUseSatoko ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pNtk == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(-1, "Currently only works for structurally hashed circuits.\n")
		return 0
	}
	if Abc_NtkLatchNum(pNtk) == 0 {
		Abc_Print(-1, "Does not work for combinational networks.\n")
		return 0
	}
	if pAbc.fBatchMode && (pAbc.Status == 0 || pAbc.Status == 1) {
		Abc_Print(1, "The miters is already solved; skipping the command.\n")
		return 0
	}
	pAbc.Status = Abc_NtkDarBmc(pNtk, nStart, nFrames, nSizeMax, nNodeDelta, nTimeOut, nBTLimit, nBTLimitAll, fRewrite, fNewAlgo, fOrDecomp, 0, fVerbose, &iFrames, fUseSatoko)
	pAbc.nFrames = iFrames
	Abc_FrameReplaceCex(pAbc, &pNtk.pSeqModel)
	if pLogFileName != "" {
		Abc_NtkWriteLogFile(pLogFileName, pAbc.pCex, pAbc.Status, pAbc.nFrames, "bmc2")
	}
	return 0

usage:
	Abc_Print(-2, "usage: bmc2 [-SFTCGD num] [-L file] [-usvh]\n")
	Abc_Print(-2, "\t         performs bounded model checking with dynamic unrolling\n")
	Abc_Print(-2, "\t-S num : the starting time frame [default = %d]\n", nStart)
	Abc_Print(-2, "\t-F num : the max number of time frames (0 = unused) [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-T num : approximate runtime limit in seconds [default = %d]\n", nTimeOut)
	Abc_Print(-2, "\t-C num : the max number of conflicts at a node [default = %d]\n", nBTLimit)
	Abc_Print(-2, "\t-G num : the max number of conflicts globally [default = %d]\n", nBTLimitAll)
	Abc_Print(-2, "\t-D num : the delta in the number of nodes [default = %d]\n", nNodeDelta)
	Abc_Print(-2, "\t-L file: the log file name [default = %s]\n", abcDefaultString(pLogFileName, "no logging"))
	Abc_Print(-2, "\t-u     : toggle performing structural OR-decomposition [default = %s]\n", abcSelect(fOrDecomp, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle using Satoko by Bruno Schmitt [default = %s]\n", abcSelect(fUseSatoko, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

