/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCexSave(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var c int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pCex == nil {
		Abc_Print(-1, "Current CEX is not available..\n")
		return 1
	}
	ABC_FREE(pAbc.pCex2)
	pAbc.pCex2 = Abc_CexDup(pAbc.pCex, -1)
	return 0

usage:
	Abc_Print(-2, "usage: cexsave [-h]\n")
	Abc_Print(-2, "\t        saves the current CEX into the internal storage\n")
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCexLoad(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var c int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pCex2 == nil {
		Abc_Print(-1, "Saved CEX is not available.\n")
		return 1
	}
	ABC_FREE(pAbc.pCex)
	pAbc.pCex = Abc_CexDup(pAbc.pCex2, -1)
	// update status
	pAbc.nFrames = pAbc.pCex2.iFrame
	pAbc.Status = 0
	return 0

usage:
	Abc_Print(-2, "usage: cexload [-h]\n")
	Abc_Print(-2, "\t        loads the current CEX from the internal storage\n")
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCexCut(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtkNew *Abc_Ntk_t
	var c, iFrStart int32
	var iFrStop int32 = ABC_INFINITY
	var fCombOnly int32
	var fUseOne int32
	var fAllFrames int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FGcnmvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FGcnmvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			iFrStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iFrStart < 0 {
				goto usage
			}
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by an integer.\n")
				goto usage
			}
			iFrStop = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iFrStop < 0 {
				goto usage
			}
			break
		case 'c':
			fCombOnly ^= 1
			break
		case 'n':
			fUseOne ^= 1
			break
		case 'm':
			fAllFrames ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			Abc_Print(-2, "Unknown switch.\n")
			goto usage
		}
	}

	if pAbc.pCex == nil {
		Abc_Print(1, "There is no current cex.\n")
		return 0
	}
	if pAbc.pNtkCur == nil {
		Abc_Print(1, "There is no AIG in the &-space.\n")
		return 0
	}
	if !Abc_NtkIsStrash(pAbc.pNtkCur) {
		Abc_Print(1, "Current network is not an AIG.\n")
		return 0
	}
	if iFrStop == ABC_INFINITY {
		iFrStop = pAbc.pCex.iFrame
	}

	{
		var pAig *Aig_Man_t = Abc_NtkToDar(pAbc.pNtkCur, 0, 1)
		var pAigNew *Aig_Man_t = Bmc_AigTargetStates(pAig, pAbc.pCex, iFrStart, iFrStop, fCombOnly, fUseOne, fAllFrames, fVerbose)
		Aig_ManStop(pAig)
		if pAigNew == nil {
			Abc_Print(1, "Command has failed.\n")
			return 0
		}
		pNtkNew = Abc_NtkFromAigPhase(pAigNew)
		pNtkNew.pName = Extra_UtilStrsav(pAbc.pNtkCur.pName)
		Aig_ManStop(pAigNew)
		// update the network
		Abc_FrameReplaceCurrentNetwork(pAbc, pNtkNew)
	}
	/*
	   pGiaNew = Bmc_GiaTargetStates( pAbc->pGia, pAbc->pCex, iFrStart, iFrStop, fCombOnly, fUseOne, fVerbose );
	   if ( pGiaNew == NULL )
	   {
	       Abc_Print( 1, "Command has failed.\n");
	       return 0;
	   }
	   Abc_FrameUpdateGia( pAbc, pGiaNew );
	*/
	return 0

usage:
	Abc_Print(-2, "usage: cexcut [-FG num] [-cnmvh]\n")
	Abc_Print(-2, "\t         creates logic for bad states using the current CEX\n")
	Abc_Print(-2, "\t-F num : 0-based number of the starting frame [default = %d]\n", iFrStart)
	Abc_Print(-2, "\t-G num : 0-based number of the ending frame [default = %d]\n", iFrStop)
	Abc_Print(-2, "\t-c     : toggle outputting unate combinational circuit [default = %s]\n", abcSelect(fCombOnly, "yes", "no"))
	Abc_Print(-2, "\t-n     : toggle generating only one bad state [default = %s]\n", abcSelect(fUseOne, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggle generating bad states for all frames after G [default = %s]\n", abcSelect(fAllFrames, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCexMerge(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pCexNew *Abc_Cex_t
	var c int32
	var iFrStart int32
	var iFrStop int32 = ABC_INFINITY
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FGvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FGvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			iFrStart = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iFrStart < 0 {
				goto usage
			}
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by an integer.\n")
				goto usage
			}
			iFrStop = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iFrStop < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			Abc_Print(-2, "Unknown switch.\n")
			goto usage
		}
	}

	if pAbc.pCex == nil {
		Abc_Print(1, "There is no current cex.\n")
		return 0
	}
	if pAbc.pCex2 == nil {
		Abc_Print(1, "There is no saved cex.\n")
		return 0
	}
	if iFrStop-iFrStart+pAbc.pCex.iPo < pAbc.pCex.iFrame {
		Abc_Print(1, "Current CEX does not allow to shorten the saved CEX.\n")
		return 0
	}
	pCexNew = Abc_CexMerge(pAbc.pCex2, pAbc.pCex, iFrStart, iFrStop)
	if pCexNew == nil {
		Abc_Print(1, "Merging CEXes has failed.\n")
		return 0
	}
	// replace the saved CEX
	ABC_FREE(pAbc.pCex2)
	pAbc.pCex2 = pCexNew
	return 0

usage:
	Abc_Print(-2, "usage: cexmerge [-FG num] [-vh]\n")
	Abc_Print(-2, "\t         merges the current CEX into the saved one\n")
	Abc_Print(-2, "\t         and sets the resulting CEX as the saved one\n")
	Abc_Print(-2, "\t-F num : 0-based number of the starting frame [default = %d]\n", iFrStart)
	Abc_Print(-2, "\t-G num : 0-based number of the ending frame [default = %d]\n", iFrStop)
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandCexMin(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pNtk *Abc_Ntk_t
	var vCexNew *Abc_Cex_t = nil
	var c int32
	var nConfLimit int32 = 1000
	var nRounds int32 = 1
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CRvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "CRvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfLimit < 0 {
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			nRounds = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nRounds < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			Abc_Print(-2, "Unknown switch.\n")
			goto usage
		}
	}

	if pAbc.pCex == nil {
		Abc_Print(1, "There is no current cex.\n")
		return 0
	}

	// check the main AIG
	pNtk = Abc_FrameReadNtk(pAbc)
	if pNtk == nil {
		Abc_Print(1, "Main AIG: There is no current network.\n")
	} else if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(1, "Main AIG: The current network is not an AIG.\n")
	} else if Abc_NtkPiNum(pNtk) != pAbc.pCex.nPis {
		Abc_Print(1, "Main AIG: The number of PIs (%d) is different from cex (%d).\n", Abc_NtkPiNum(pNtk), pAbc.pCex.nPis)
		//      else if ( Abc_NtkLatchNum(pNtk) != pAbc->pCex->nRegs )
		//          Abc_Print( 1, "Main AIG: The number of registers (%d) is different from cex (%d).\n", Abc_NtkLatchNum(pNtk), pAbc->pCex->nRegs );
		//      else if ( Abc_NtkPoNum(pNtk) <= pAbc->pCex->iPo )
		//          Abc_Print( 1, "Main AIG: The number of POs (%d) is less than the PO index in cex (%d).\n", Abc_NtkPoNum(pNtk), pAbc->pCex->iPo );
	} else {
		var pAig *Aig_Man_t = Abc_NtkToDar(pNtk, 0, 1)
		var pGia *Gia_Man_t = Gia_ManFromAigSimple(pAig)
		//        if ( !Gia_ManVerifyCex( pGia, pAbc->pCex, 0 ) )
		var iPoOld int32 = pAbc.pCex.iPo
		pAbc.pCex.iPo = Gia_ManFindFailedPoCex(pGia, pAbc.pCex, 0)
		Gia_ManStop(pGia)
		if pAbc.pCex.iPo == -1 {
			pAbc.pCex.iPo = iPoOld
			Abc_Print(-1, "Main AIG: The cex does not fail any outputs.\n")
			return 0

		} else if iPoOld != pAbc.pCex.iPo {
			Abc_Print(0, "Main AIG: The cex refined PO %d instead of PO %d.\n", pAbc.pCex.iPo, iPoOld)
		}
		// perform minimization
		vCexNew = Saig_ManCexMinPerform(pAig, pAbc.pCex)
		Aig_ManStop(pAig)
		Abc_CexFree(vCexNew)
		//        Abc_FrameReplaceCex( pAbc, &vCexNew );

		//        Abc_Print( 1,"Implementation of this command is not finished.\n" );
	}
	return 0

usage:
	Abc_Print(-2, "usage: cexmin [-CR num] [-vh]\n")
	Abc_Print(-2, "\t         reduces the length of the counter-example\n")
	Abc_Print(-2, "\t-C num : the maximum number of conflicts [default = %d]\n", nConfLimit)
	Abc_Print(-2, "\t-R num : the number of minimization rounds [default = %d]\n", nRounds)
	Abc_Print(-2, "\t-v     : toggle printing optimization summary [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandDualRail(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pNtk *Abc_Ntk_t
	var pNtkNew *Abc_Ntk_t = nil
	var pAig, pAigNew *Aig_Man_t
	var vDcFlops *Vec_Int_t = nil
	var c int32
	var nDualPis int32
	var fDualFfs int32
	var fDualDcFfs int32
	var fMiterFfs int32
	var fComplPo int32
	var fCheckZero int32
	var fCheckOne int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Itxfczovh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Itxfczovh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nDualPis = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nDualPis < 0 {
				goto usage
			}
			break
		case 't':
			fDualFfs ^= 1
			break
		case 'x':
			fDualDcFfs ^= 1
			break
		case 'f':
			fMiterFfs ^= 1
			break
		case 'c':
			fComplPo ^= 1
			break
		case 'z':
			fCheckZero ^= 1
			break
		case 'o':
			fCheckOne ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			Abc_Print(-2, "Unknown switch.\n")
			goto usage
		}
	}

	// check the main AIG
	pNtk = Abc_FrameReadNtk(pAbc)
	if pNtk == nil {
		Abc_Print(1, "Main AIG: There is no current network.\n")
		return 0
	}
	if !Abc_NtkIsStrash(pNtk) {
		Abc_Print(1, "Main AIG: The current network is not an AIG.\n")
		return 0
	}

	if fDualDcFfs != 0 {
		vDcFlops = Abc_NtkFindDcLatches(pNtk)
	}

	// transform
	pAig = Abc_NtkToDar(pNtk, 0, 1)
	pAigNew = Saig_ManDupDual(pAig, vDcFlops, nDualPis, fDualFfs, fMiterFfs, fComplPo, fCheckZero, fCheckOne)
	Aig_ManStop(pAig)
	pNtkNew = Abc_NtkFromAigPhase(pAigNew)
	pNtkNew.pName = Extra_UtilStrsav(pNtk.pName)
	Aig_ManStop(pAigNew)
	Vec_IntFreeP(&vDcFlops)

	// replace the current network
	Abc_FrameReplaceCurrentNetwork(pAbc, pNtkNew)
	return 0

usage:
	Abc_Print(-2, "usage: dualrail [-I num] [-txfczovh]\n")
	Abc_Print(-2, "\t         transforms the current AIG into a dual-rail miter\n")
	Abc_Print(-2, "\t         expressing the property \"at least one PO has ternary value\"\n")
	Abc_Print(-2, "\t         (to compute an initialization sequence, use switches \"-tfc\")\n")
	Abc_Print(-2, "\t-I num : the number of first PIs interpreted as ternary [default = %d]\n", nDualPis)
	Abc_Print(-2, "\t-t     : toggle ternary flop init values for all flops [default = %s]\n", abcSelect(fDualFfs, "yes", "const0 init values"))
	Abc_Print(-2, "\t-x     : toggle ternary flop init values for DC-valued flops [default = %s]\n", abcSelect(fDualDcFfs, "yes", "const0 init values"))
	Abc_Print(-2, "\t-f     : toggle mitering flops instead of POs [default = %s]\n", abcSelect(fMiterFfs, "flops", "POs"))
	Abc_Print(-2, "\t-c     : toggle complementing the miter output [default = %s]\n", abcSelect(fComplPo, "yes", "no"))
	Abc_Print(-2, "\t-z     : toggle checking PO==0 instead of PO==X [default = %s]\n", abcSelect(fCheckZero, "yes", "no"))
	Abc_Print(-2, "\t-o     : toggle checking PO==1 instead of PO==X [default = %s]\n", abcSelect(fCheckOne, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing optimization summary [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

