/*
*Function*************************************************************

	Synopsis    [Compares to versions of the design and finds the best.]

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_NtkCompareWithBest(pBest *Abc_Ntk_t, p *Abc_Ntk_t, pnBestNtkArea *float32, pnBestNtkDelay *float32, pnBestNtkNodes *int32, pnBestNtkLevels *int32, fArea int32) int32 {
	var nNtkArea float32 = float32(Abc_NtkGetMappedArea(p))
	var nNtkDelay float32 = float32(Abc_NtkDelayTrace(p, nil, nil, 0))
	var nNtkNodes int32 = Abc_NtkNodeNum(p)
	var nNtkLevels int32 = Abc_NtkLevel(p)

	if pBest == nil ||
		Abc_NtkPiNum(pBest) != Abc_NtkPiNum(p) ||
		Abc_NtkPoNum(pBest) != Abc_NtkPoNum(p) ||
		Abc_NtkLatchNum(pBest) != Abc_NtkLatchNum(p) ||
		(int32(strings.Compare(Abc_NtkName(pBest), Abc_NtkName(p))) != 0) ||
		(!(fArea != 0) && (*pnBestNtkLevels > nNtkLevels || (*pnBestNtkLevels == nNtkLevels && *pnBestNtkDelay > nNtkDelay))) ||
		((fArea != 0) && (*pnBestNtkNodes > nNtkNodes || (*pnBestNtkNodes == nNtkNodes && *pnBestNtkArea > nNtkArea))) {
		*pnBestNtkArea = nNtkArea
		*pnBestNtkDelay = nNtkDelay
		*pnBestNtkNodes = nNtkNodes
		*pnBestNtkLevels = nNtkLevels
		fmt.Printf("\nUpdating the best network (Area = %10.2f  Delay = %10.2f  Nodes = %6d  Level = %6d).\n\n", nNtkArea, nNtkDelay, nNtkNodes, nNtkLevels)
		return 1
	}
	return 0
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbcSave(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var c, fArea int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ah"); c != -1; c = Extra_UtilGetopt(argc, argv, "ah") {
		switch c {
		case 'a':
			fArea ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pNtkCur == nil {
		Abc_Print(-1, "Empty network.\n")
		return 1
	}
	if !Abc_NtkHasMapping(pAbc.pNtkCur) {
		Abc_Print(-1, "Network has no mapping.\n")
		return 1
	}
	if !(Abc_NtkCompareWithBest(pAbc.pNtkBest, pAbc.pNtkCur,
		&pAbc.nBestNtkArea, &pAbc.nBestNtkDelay,
		&pAbc.nBestNtkNodes, &pAbc.nBestNtkLevels, fArea) != 0) {
		return 0
	}
	// save the design as best
	if pAbc.pNtkBest {
		Abc_NtkDelete(pAbc.pNtkBest)
	}
	pAbc.pNtkBest = Abc_NtkDup(pAbc.pNtkCur)
	return 0

usage:
	Abc_Print(-2, "usage: save [-ah]\n")
	Abc_Print(-2, "\t        compares and possibly saves network with mapping\n")
	Abc_Print(-2, "\t-a    : toggle using area as the primary metric [default = %s]\n", abcSelect(fArea, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbcLoad(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var c int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	// restore from best
	if pAbc.pNtkBest == nil {
		Abc_Print(-1, "Abc_CommandAbcLoad(): There is no best design saved.\n")
		return 1
	}
	if pAbc.pNtkCur {
		Abc_NtkDelete(pAbc.pNtkCur)
	}
	pAbc.pNtkCur = Abc_NtkDup(pAbc.pNtkBest)
	return 0

usage:
	Abc_Print(-2, "usage: load [-h]\n")
	Abc_Print(-2, "\t        loads mapped network previously saved by \"save\"\n")
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Read(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pAig *Gia_Man_t = nil
	var pFile *os.File
	var err error
	var pArgvNew *string
	var FileName, pTemp string
	var c, nArgcNew int32
	var fMiniAig int32
	var fMiniAig2 int32
	var fMiniLut int32
	var fVerbose int32
	var fGiaSimple int32
	var fSkipStrash int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "csmnlvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "csmnlvh") {
		switch c {
		case 'c':
			fGiaSimple ^= 1
			break
		case 's':
			fSkipStrash ^= 1
			break
		case 'm':
			fMiniAig ^= 1
			break
		case 'n':
			fMiniAig2 ^= 1
			break
		case 'l':
			fMiniLut ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		default:
			goto usage
		}
	}
	pArgvNew = argv + globalUtilOptind
	nArgcNew = argc - globalUtilOptind
	if nArgcNew != 1 {
		Abc_Print(-1, "There is no file name.\n")
		return 1
	}

	// get the input file name
	FileName = pArgvNew[0]
	// fix the wrong symbol
	FileName = strings.ReplaceAll(FileName, ">", "\\")
	pFile, err = os.Open(FileName)
	if err != nil {
		Abc_Print(-1, "Cannot open input file \"%s\". ", FileName)
		if similar := Extra_FileGetSimilarName(FileName, ".aig", ".blif", ".pla", ".eqn", ".bench"); similar != "" {
			Abc_Print(1, "Did you mean \"%s\"?", similar)
		}
		Abc_Print(1, "\n")
		return 1
	}
	_ = pFile.Close()

	if fMiniAig != 0 {
		pAig = Gia_ManReadMiniAig(FileName)
	} else if fMiniAig2 != 0 {
		pAig = Gia_MiniAigSuperDerive(FileName, fVerbose)
	} else if fMiniLut != 0 {
		pAig = Gia_ManReadMiniLut(FileName)
		//    else if ( Extra_FileIsType( FileName, ".v", NULL, NULL ) )
		//        Abc3_ReadShowHie( FileName, fSkipStrash );
	} else {
		pAig = Gia_AigerRead(FileName, fGiaSimple, fSkipStrash, 0)
	}
	if pAig != nil {
		Abc_FrameUpdateGia(pAbc, pAig)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &r [-csmnlvh] <file>\n")
	Abc_Print(-2, "\t         reads the current AIG from the AIGER file\n")
	Abc_Print(-2, "\t-c     : toggles reading simple AIG [default = %s]\n", abcSelect(fGiaSimple, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggles structural hashing while reading [default = %s]\n", !abcSelect(fSkipStrash, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggles reading MiniAIG rather than AIGER file [default = %s]\n", abcSelect(fMiniAig, "yes", "no"))
	Abc_Print(-2, "\t-n     : toggles reading MiniAIG as a set of supergates [default = %s]\n", abcSelect(fMiniAig2, "yes", "no"))
	Abc_Print(-2, "\t-l     : toggles reading MiniLUT rather than AIGER file [default = %s]\n", abcSelect(fMiniLut, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles additional verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	Abc_Print(-2, "\t<file> : the file name\n")
	return 1
}

