/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9MuxProfile(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c, fNpn, fMuxes, fAdders, nLimit, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Nnmavh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Nnmavh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLimit < 0 {
				goto usage
			}
			break
		case 'n':
			fNpn ^= 1
			break
		case 'm':
			fMuxes ^= 1
			break
		case 'a':
			fAdders ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9MuxProfile(): There is no AIG.\n")
		return 1
	}
	if fNpn != 0 {
		if !Gia_ManHasMapping(pAbc.pGia) || Gia_ManLutSizeMax(pAbc.pGia) >= 4 {
			Abc_Print(-1, "Abc_CommandAbc9MuxProfile(): Expecting AIG mapped into 3-LUTs.\n")
			return 1
		}
		Acec_StatsCollect(pAbc.pGia, fVerbose)

	} else if fMuxes != 0 {
		Gia_ManMuxProfiling(pAbc.pGia)
	} else if fAdders != 0 {
		Acec_ManProfile(pAbc.pGia, fVerbose)
	} else {
		Gia_ManProfileStructures(pAbc.pGia, nLimit, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &profile [-N num] [-nmavh]\n")
	Abc_Print(-2, "\t         profile gate structures appearing in the AIG\n")
	Abc_Print(-2, "\t-N num : limit on class size to show [default = %d]\n", nLimit)
	Abc_Print(-2, "\t-n     : toggle profiling NPN-classes (for 3-LUT mapped AIGs) [default = %s]\n", abcSelect(fNpn, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggle profiling MUX structures [default = %s]\n", abcSelect(fMuxes, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggle profiling adder structures [default = %s]\n", abcSelect(fAdders, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

