/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Show(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var vBold *Vec_Int_t = nil
	var c, fAdders, fFadds, fPath int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "afph"); c != -1; c = Extra_UtilGetopt(argc, argv, "afph") {
		switch c {
		case 'a':
			fAdders ^= 1
			break
		case 'f':
			fFadds ^= 1
			break
		case 'p':
			fPath ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Show(): There is no AIG.\n")
		return 1
	}
	if Gia_ManBufNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Show(): Cannot show GIA with barrier buffers.\n")
		return 1
	}
	if !fAdders && Gia_ManHasMapping(pAbc.pGia) {
		vBold = Vec_IntAlloc(100)
		Gia_ManForEachLut(pAbc.pGia, c)
		Vec_IntPush(vBold, c)
	}
	Gia_ManShow(pAbc.pGia, vBold, fAdders, fFadds, fPath)
	Vec_IntFreeP(&vBold)
	return 0

usage:
	Abc_Print(-2, "usage: &show [-afph]\n")
	Abc_Print(-2, "\t        shows the current GIA using GSView\n")
	Abc_Print(-2, "\t-a    : toggle visualazing adders [default = %s]\n", abcSelect(fAdders, "yes", "no"))
	Abc_Print(-2, "\t-f    : toggle showing only full-adders with \"-a\" [default = %s]\n", abcSelect(fFadds, "yes", "no"))
	Abc_Print(-2, "\t-p    : toggle showing the critical path of a LUT mapping [default = %s]\n", abcSelect(fPath, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

