func Abc_CommandAbc9SetRegNum(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var c, nRegNum int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Nh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Nh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nRegNum = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nRegNum < 0 {
				goto usage
			}
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9SetRegNum(): There is no AIG.\n")
		return 1
	}
	if nRegNum >= Gia_ManCiNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9SetRegNum(): The number of registers should be less than the number of CIs.\n")
		return 1
	}
	if nRegNum >= Gia_ManCoNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9SetRegNum(): The number of registers should be less than the number of COs.\n")
		return 1
	}
	pAbc.pGia.nRegs = nRegNum
	return 0

usage:
	Abc_Print(-2, "usage: &setregnum [-N num] [-h]\n")
	Abc_Print(-2, "\t         manually sets the number of registers to combine the last PI/PO pairs\n")
	Abc_Print(-2, "\t-N num : set the number of registers to be the given number [default = %d]\n", nRegNum)
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Strash(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var c int32
	var Limit int32 = 2
	var fAddStrash int32
	var fCollapse int32
	var fAddMuxes int32
	var fStrMuxes int32
	var fRehashMap int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Lacmrsh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Lacmrsh") {
		switch c {
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			Limit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Limit < 0 {
				goto usage
			}
			break
		case 'a':
			fAddStrash ^= 1
			break
		case 'c':
			fCollapse ^= 1
			break
		case 'm':
			fAddMuxes ^= 1
			break
		case 'r':
			fRehashMap ^= 1
			break
		case 's':
			fStrMuxes ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Strash(): There is no AIG.\n")
		return 1
	}
	if fStrMuxes != 0 {
		if Gia_ManHasMapping(pAbc.pGia) {
			Abc_Print(0, "Restructing the current AIG destroys the LUT mapping.\n")
		}
		Vec_IntFreeP(&pAbc.pGia.vMapping)
		pTemp = Gia_ManDupMuxRestructure(pAbc.pGia)
		Abc_Print(1, "Finished AIG restructing to enable efficient mapping of 4:1 MUXes into 4-LUTs.\n")

	} else if Gia_ManHasMapping(pAbc.pGia) && (fRehashMap != 0) {
		pTemp = Gia_ManDupHashMapping(pAbc.pGia)
		Gia_ManTransferPacking(pTemp, pAbc.pGia)
		Gia_ManTransferTiming(pTemp, pAbc.pGia)

	} else if Gia_ManHasMapping(pAbc.pGia) && pAbc.pGia.vConfigs {
		pTemp = If_ManDeriveGiaFromCells(pAbc.pGia)
	} else if Gia_ManHasMapping(pAbc.pGia) {
		pTemp = Dsm_ManDeriveGia(pAbc.pGia, fAddMuxes) // delay-oriented unmapping
	} else if fAddMuxes != 0 {
		if pAbc.pGia.pMuxes {
			Abc_Print(-1, "Abc_CommandAbc9Strash(): The AIG already has MUXes.\n")
			return 1
		}
		pTemp = Gia_ManDupMuxes(pAbc.pGia, Limit)
		if !Abc_FrameReadFlag("silentmode") {
			fmt.Printf("Generated AND/XOR/MUX graph.\n")
		}

	} else if (fCollapse != 0) && pAbc.pGia.pAigExtra {
		assert(!Gia_ManBufNum(pAbc.pGia), "!Gia_ManBufNum(pAbc.pGia)")
		if Gia_ManIsSeqWithBoxes(pAbc.pGia) || Gia_ManRegBoxNum(pAbc.pGia) {
			var pUnshuffled *Gia_Man_t = Gia_ManDupUnshuffleInputs(pAbc.pGia)
			Gia_ManTransferTiming(pUnshuffled, pAbc.pGia)
			pTemp = Gia_ManDupCollapse(pUnshuffled, pUnshuffled.pAigExtra, nil, Gia_ManRegBoxNum(pUnshuffled) > 0)
			Gia_ManTransferTiming(pAbc.pGia, pUnshuffled)
			Gia_ManStop(pUnshuffled)

		} else {
			pTemp = Gia_ManDupCollapse(pAbc.pGia, pAbc.pGia.pAigExtra, nil, 0)
		}
		if !Abc_FrameReadFlag("silentmode") {
			fmt.Printf("Collapsed AIG with boxes and logic of the boxes.\n")
		}

	} else if pAbc.pGia.pMuxes {
		pTemp = Gia_ManDupNoMuxes(pAbc.pGia, 0)
		if !Abc_FrameReadFlag("silentmode") {
			fmt.Printf("Generated AIG from AND/XOR/MUX graph.\n")
		}

	} else {
		pTemp = Gia_ManRehash(pAbc.pGia, fAddStrash)
		//        if ( !Abc_FrameReadFlag("silentmode") )
		//            printf( "Rehashed the current AIG.\n" );
	}
	if !((fCollapse != 0) && pAbc.pGia.pAigExtra) {
		Gia_ManTransferTiming(pTemp, pAbc.pGia)
		pAbc.pGia.vConfigs = pTemp.vConfigs
		pTemp.vConfigs = nil
		pAbc.pGia.pCellStr = pTemp.pCellStr
		pTemp.pCellStr = nil
	}
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &st [-L num] [-acmrsh]\n")
	Abc_Print(-2, "\t         performs structural hashing\n")
	Abc_Print(-2, "\t-a     : toggle additional hashing [default = %s]\n", abcSelect(fAddStrash, "yes", "no"))
	Abc_Print(-2, "\t-c     : toggle collapsing hierarchical AIG [default = %s]\n", abcSelect(fCollapse, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggle converting to larger gates [default = %s]\n", abcSelect(fAddMuxes, "yes", "no"))
	Abc_Print(-2, "\t-L num : create MUX when sum of refs does not exceed this limit [default = %d]\n", Limit)
	Abc_Print(-2, "\t         (use L = 1 to create AIG with XORs but without MUXes)\n")
	Abc_Print(-2, "\t-r     : toggle rehashing AIG while preserving mapping [default = %s]\n", abcSelect(fRehashMap, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle using MUX restructuring [default = %s]\n", abcSelect(fStrMuxes, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

