/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Cof(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var c, fVerbose int32
	var iVar, nLimFan int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "VLvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "VLvh") {
		switch c {
		case 'V':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-V\" should be followed by an integer.\n")
				goto usage
			}
			iVar = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iVar < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nLimFan = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLimFan < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Cof(): There is no AIG.\n")
		return 1
	}
	if nLimFan != 0 {
		Abc_Print(-1, "Cofactoring all variables whose fanout count is higher than %d.\n", nLimFan)
		pTemp = Gia_ManDupCofAll(pAbc.pGia, nLimFan, fVerbose)
		Abc_FrameUpdateGia(pAbc, pTemp)

	} else if iVar != 0 {
		Abc_Print(-1, "Cofactoring one variable with object ID %d.\n", iVar)
		pTemp = Gia_ManDupCof(pAbc.pGia, iVar)
		Abc_FrameUpdateGia(pAbc, pTemp)

	} else {
		Abc_Print(-1, "One of the parameters, -V <num> or -L <num>, should be set on the command line.\n")
		goto usage
	}
	return 0

usage:
	Abc_Print(-2, "usage: &cof [-VL num] [-vh]\n")
	Abc_Print(-2, "\t         performs cofactoring w.r.t. variable(s)\n")
	Abc_Print(-2, "\t-V num : the zero-based ID of one variable to cofactor [default = %d]\n", iVar)
	Abc_Print(-2, "\t-L num : cofactor vars with fanout count higher than this [default = %d]\n", nLimFan)
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

