/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9SimRsb(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var nCands int32 = 32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Nvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Nvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nCands = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCands < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9SimRsb(): There is no AIG.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) > 0 {
		Abc_Print(-1, "Abc_CommandAbc9SimRsb(): This command works only for combinational AIGs.\n")
		return 0
	}
	if pAbc.pGia.vSimsPi == nil {
		Abc_Print(-1, "Abc_CommandAbc9SimRsb(): Does not have simulation information available.\n")
		return 0
	}
	Gia_ManSimRsb(pAbc.pGia, nCands, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: &simrsb [-N num] [-vh]\n")
	Abc_Print(-2, "\t         performs resubstitution\n")
	Abc_Print(-2, "\t-C num : the number of candidates to try [default = %d]\n", nCands)
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

