/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Equiv2(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var nFramesMax int32 = 20
	var nConfMax int32 = 500
	var nRounds int32 = 10
	var TimeLimit int32
	var TimeLimit2 int32
	var fUseCex int32
	var fLatchOnly int32
	var fVerbose int32
	var c int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FCRTSxlvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FCRTSxlvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFramesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFramesMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfMax < 0 {
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			nRounds = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nRounds < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			TimeLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if TimeLimit < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			TimeLimit2 = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if TimeLimit2 < 0 {
				goto usage
			}
			break
		case 'x':
			fUseCex ^= 1
			break
		case 'l':
			fLatchOnly ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Equiv2(): There is no AIG.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) == 0 {
		Abc_Print(0, "Abc_CommandAbc9Equiv2(): There is no flops. Nothing is done.\n")
		return 0
	}
	if fUseCex != 0 {
		if pAbc.pCex == nil {
			Abc_Print(0, "Abc_CommandAbc9Equiv2(): Counter-example is not available.\n")
			return 0
		}
		if pAbc.pCex.nPis != Gia_ManPiNum(pAbc.pGia) {
			Abc_Print(-1, "Abc_CommandAbc9Equiv2(): The number of PIs differs in cex (%d) and in AIG (%d).\n",
				pAbc.pCex.nPis, Gia_ManPiNum(pAbc.pGia))
			return 1
		}
	}
	if fUseCex != 0 {
		cex = pAbc.pCex
	}
	Ssw_SignalFilterGia(pAbc.pGia, nFramesMax, nConfMax, nRounds, TimeLimit, TimeLimit2, cex, fLatchOnly, fVerbose)
	pAbc.Status = -1
	//    pAbc->nFrames = pAbc->pCex->iFrame;
	//    Abc_FrameReplaceCex( pAbc, &pAbc->pCex );
	return 0

usage:
	Abc_Print(-2, "usage: &equiv2 [-FCRTS num] [-xlvh]\n")
	Abc_Print(-2, "\t         computes candidate equivalence classes\n")
	Abc_Print(-2, "\t-F num : the max number of frames for BMC [default = %d]\n", nFramesMax)
	Abc_Print(-2, "\t-C num : the max number of conflicts at a node [default = %d]\n", nConfMax)
	Abc_Print(-2, "\t-R num : the max number of BMC rounds [default = %d]\n", nRounds)
	Abc_Print(-2, "\t-T num : runtime limit in seconds for all rounds [default = %d]\n", TimeLimit)
	Abc_Print(-2, "\t-S num : runtime limit in seconds for one round [default = %d]\n", TimeLimit2)
	Abc_Print(-2, "\t-x     : toggle using the current cex to perform refinement [default = %s]\n", abcSelect(fUseCex, "yes", "no"))
	Abc_Print(-2, "\t-l     : toggle considering only latch output equivalences [default = %s]\n", abcSelect(fLatchOnly, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

