/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Shrink(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t = nil
	var nLutSize int32
	var c, fVerbose int32
	var fKeepLevel int32
	var nFanoutMax int32 = 50
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Nlvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Nlvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by a char string.\n")
				goto usage
			}
			nFanoutMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFanoutMax < 0 {
				goto usage
			}
			break
		case 'l':
			fKeepLevel ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Shrink(): There is no AIG.\n")
		return 1
	}
	if !Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Shrink(): Mapping of the AIG is not defined.\n")
		return 1
	}
	nLutSize = Gia_ManLutSizeMax(pAbc.pGia)
	if nLutSize <= 4 {
		pTemp = Gia_ManMapShrink4(pAbc.pGia, fKeepLevel, fVerbose)
	} else if nLutSize <= 6 {
		pTemp = Gia_ManMapShrink6(pAbc.pGia, nFanoutMax, fKeepLevel, fVerbose)
	} else {
		Abc_Print(-1, "Abc_CommandAbc9Shrink(): Works only for 4-LUTs and 6-LUTs.\n")
	}
	if pTemp != nil {
		Abc_FrameUpdateGia(pAbc, pTemp)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &shrink [-N num] [-lvh]\n")
	Abc_Print(-2, "\t         performs fast shrinking using current mapping\n")
	Abc_Print(-2, "\t-N num : the max fanout count to skip a divisor [default = %d]\n", nFanoutMax)
	Abc_Print(-2, "\t-l     : toggle level update during shrinking [default = %s]\n", abcSelect(fKeepLevel, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Fx(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var nNewNodesMax int32 = 1000000
	var LitCountMax int32
	var fReverse int32
	var c, fVerbose int32
	var fVeryVerbose int32
	// set the defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NMrvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NMrvwh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nNewNodesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNewNodesMax < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			LitCountMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if LitCountMax < 0 {
				goto usage
			}
			break
		case 'r':
			fReverse ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
			break
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Shrink(): There is no AIG.\n")
		return 1
	}
	if !Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Shrink(): Mapping of the AIG is not defined.\n")
		return 1
	}
	pTemp = Gia_ManPerformFx(pAbc.pGia, nNewNodesMax, LitCountMax, fReverse, fVerbose, fVeryVerbose)
	if pTemp != nil {
		Abc_FrameUpdateGia(pAbc, pTemp)
	} else {
		Abc_Print(-1, "Abc_CommandAbc9Fx(): Command has failed.\n")
	}
	return 0

usage:
	Abc_Print(-2, "usage: &fx [-NM <num>] [-vh]\n")
	Abc_Print(-2, "\t           extract shared logic using the classical \"fast_extract\" algorithm\n")
	Abc_Print(-2, "\t-N <num> : max number of divisors to extract during this run [default = %d]\n", nNewNodesMax)
	Abc_Print(-2, "\t-M <num> : upper bound on literal count of divisors to extract [default = %d]\n", LitCountMax)
	Abc_Print(-2, "\t-r       : reversing variable order during ISOP computation [default = %s]\n", abcSelect(fReverse, "yes", "no"))
	Abc_Print(-2, "\t-v       : print verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggle printing additional information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Balance(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t = nil
	var nNewNodesMax int32 = ABC_INFINITY
	var fDelayOnly int32
	var fSimpleAnd int32
	var fStrict int32
	var fKeepLevel int32
	var c, fVerbose int32
	var fVeryVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Ndaslvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Ndaslvwh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by a char string.\n")
				goto usage
			}
			nNewNodesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNewNodesMax < 0 {
				goto usage
			}
			break
		case 'd':
			fDelayOnly ^= 1
			break
		case 'a':
			fSimpleAnd ^= 1
			break
		case 's':
			fStrict ^= 1
			break
		case 'l':
			fKeepLevel ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Balance(): There is no AIG.\n")
		return 1
	}
	if fDelayOnly != 0 {
		pTemp = Gia_ManBalance(pAbc.pGia, fSimpleAnd, fStrict, fVerbose)
	} else {
		pTemp = Gia_ManAreaBalance(pAbc.pGia, fSimpleAnd, nNewNodesMax, fVerbose, fVeryVerbose)
	}
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &b [-N num] [-dasvwh]\n")
	Abc_Print(-2, "\t         performs AIG balancing to reduce delay and area\n")
	Abc_Print(-2, "\t-N num : the max fanout count to skip a divisor [default = %d]\n", nNewNodesMax)
	Abc_Print(-2, "\t-d     : toggle delay only balancing [default = %s]\n", abcSelect(fDelayOnly, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggle using AND instead of AND/XOR/MUX [default = %s]\n", abcSelect(fSimpleAnd, "yes", "no"))
	Abc_Print(-2, "\t-s     : toggle strict control of area in delay-mode (\"&b -d\") [default = %s]\n", abcSelect(fStrict, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggle printing additional information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

