func Abc_CommandAbc9Resub(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var nNodes int32
	var nSupp int32
	var nDivs int32
	var c, fVerbose int32
	var fVeryVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NSDvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NSDvwh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(1, "Command line switch \"-N\" should be followed by a floating point number.\n")
				return 0
			}
			nNodes = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNodes < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(1, "Command line switch \"-S\" should be followed by a floating point number.\n")
				return 0
			}
			nSupp = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nSupp < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(1, "Command line switch \"-D\" should be followed by a floating point number.\n")
				return 0
			}
			nDivs = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nDivs < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if argc == globalUtilOptind+1 {
		pTemp = Gia_ManResub1(argv[globalUtilOptind], nNodes, nSupp, nDivs, 0, 0, fVerbose, fVeryVerbose)
		Abc_FrameUpdateGia(pAbc, pTemp)
		return 0
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Resub(): There is no AIG.\n")
		return 1
	}
	pTemp = Gia_ManResub2(pAbc.pGia, nNodes, nSupp, nDivs, 0, 0, fVerbose, fVeryVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &resub [-NSD num] [-vwh]\n")
	Abc_Print(-2, "\t           performs AIG resubstitution\n")
	Abc_Print(-2, "\t-N num   : the limit on added nodes (num >= 0) [default = %d]\n", nNodes)
	Abc_Print(-2, "\t-S num   : the limit on support size (num > 0) [default = %d]\n", nSupp)
	Abc_Print(-2, "\t-D num   : the limit on divisor count (num > 0) [default = %d]\n", nDivs)
	Abc_Print(-2, "\t-v       : toggles printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggles printing additional information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Syn2(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var c, fVerbose int32
	var fOldAlgo int32
	var fCoarsen int32 = 1
	var fCutMin int32
	var nRelaxRatio int32 = 20
	var fDelayMin int32
	var fVeryVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Rakmdvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Rakmdvwh") {
		switch c {
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(1, "Command line switch \"-R\" should be followed by a floating point number.\n")
				return 0
			}
			nRelaxRatio = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nRelaxRatio < 0 {
				goto usage
			}
			break
		case 'a':
			fOldAlgo ^= 1
			break
		case 'k':
			fCoarsen ^= 1
			break
		case 'm':
			fCutMin ^= 1
			break
		case 'd':
			fDelayMin ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Syn2(): There is no AIG.\n")
		return 1
	}
	if fDelayMin != 0 {
		p, _ := Abc_FrameReadManDsd().(*If_DsdMan_t)
		if p != nil && If_DsdManVarNum(p) < 6 {
			fmt.Printf("DSD manager has incompatible number of variables. Delay minimization is not performed.\n")
			fDelayMin = 0
		}
	}
	pTemp = Gia_ManAigSyn2(pAbc.pGia, fOldAlgo, fCoarsen, fCutMin, nRelaxRatio, fDelayMin, fVerbose, fVeryVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &syn2 [-R num] [-akmdvh]\n")
	Abc_Print(-2, "\t           performs AIG optimization\n")
	Abc_Print(-2, "\t-R num   : the delay relaxation ratio (num >= 0) [default = %d]\n", nRelaxRatio)
	Abc_Print(-2, "\t-a       : toggles using the old algorithm [default = %s]\n", abcSelect(fOldAlgo, "yes", "no"))
	Abc_Print(-2, "\t-k       : toggles coarsening the subject graph [default = %s]\n", abcSelect(fCoarsen, "yes", "no"))
	Abc_Print(-2, "\t-m       : toggles cut minimization [default = %s]\n", abcSelect(fCutMin, "yes", "no"))
	Abc_Print(-2, "\t-d       : toggles additional delay optimization [default = %s]\n", abcSelect(fDelayMin, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggles printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggles printing additional information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

