func Abc_CommandAbc9Synch2(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var Pars Dch_Pars_t
	var pPars *Dch_Pars_t = &Pars
	var c int32
	var nLutSize int32 = 6
	var nRelaxRatio int32 = 20
	// set defaults
	Dch_ManSetDefaultParams(pPars)
	pPars.nBTLimit = 100
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "WCSKRfrvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "WCSKRfrvh") {
		switch c {
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nWords = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nWords < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nBTLimit < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nSatVarMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nSatVarMax < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by a char string.\n")
				goto usage
			}
			nLutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLutSize < 0 {
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(1, "Command line switch \"-R\" should be followed by a floating point number.\n")
				return 0
			}
			nRelaxRatio = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nRelaxRatio < 0 {
				goto usage
			}
			break
		case 'f':
			pPars.fLightSynth ^= 1
			break
		case 'r':
			pPars.fSkipRedSupp ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Dch(): There is no AIG.\n")
		return 1
	}
	pTemp = Gia_ManAigSynch2(pAbc.pGia, pPars, nLutSize, nRelaxRatio)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &synch2 [-WCSKR num] [-frvh]\n")
	Abc_Print(-2, "\t         computes structural choices using a new approach\n")
	Abc_Print(-2, "\t-W num : the max number of simulation words [default = %d]\n", pPars.nWords)
	Abc_Print(-2, "\t-C num : the max number of conflicts at a node [default = %d]\n", pPars.nBTLimit)
	Abc_Print(-2, "\t-S num : the max number of SAT variables [default = %d]\n", pPars.nSatVarMax)
	Abc_Print(-2, "\t-K num : the target LUT size for downstream mapping [default = %d]\n", nLutSize)
	Abc_Print(-2, "\t-R num : the delay relaxation ratio (num >= 0) [default = %d]\n", nRelaxRatio)
	Abc_Print(-2, "\t-f     : toggle using lighter logic synthesis [default = %s]\n", abcSelect(fLightSynth, "yes", "no"))
	Abc_Print(-2, "\t-r     : toggle skipping choices with redundant support [default = %s]\n", abcSelect(fSkipRedSupp, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

