/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Scl(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var c int32
	var fConst int32 = 1
	var fEquiv int32 = 1
	var fVerbose int32
	var fVerboseFlops int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "cevwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "cevwh") {
		switch c {
		case 'c':
			fConst ^= 1
			break
		case 'e':
			fEquiv ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVerboseFlops ^= 1
			break
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Scl(): There is no AIG.\n")
		return 1
	}
	if Gia_ManBoxNum(pAbc.pGia) && Gia_ManRegBoxNum(pAbc.pGia) {
		if pAbc.pGia.pAigExtra == nil {
			fmt.Printf("Timing manager is given but there is no GIA of boxes.\n")
			return 0
		}
		pTemp = Gia_ManSweepWithBoxes(pAbc.pGia, nil, nil, fConst, fEquiv, fVerbose, fVerboseFlops)
		Abc_FrameUpdateGia(pAbc, pTemp)
		return 0
	}
	if Gia_ManRegNum(pAbc.pGia) == 0 {
		Abc_Print(-1, "The network is combinational.\n")
		return 0
	}
	pTemp = Gia_ManSeqStructSweep(pAbc.pGia, fConst, fEquiv, fVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &scl [-cevwh]\n")
	Abc_Print(-2, "\t         performs structural sequential cleanup\n")
	Abc_Print(-2, "\t-c     : toggle removing stuck-at constant registers [default = %s]\n", abcSelect(fConst, "yes", "no"))
	Abc_Print(-2, "\t-e     : toggle removing equivalent-driver registers [default = %s]\n", abcSelect(fEquiv, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggle printing verbose info about equivalent flops [default = %s]\n", abcSelect(fVerboseFlops, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

