	Abc_Print(-2, "\t-C num : the max number of conflicts at a node [default = %d]\n", pPars.nBTLimit)
	Abc_Print(-2, "\t-N num : the min number of calls to recycle the solver [default = %d]\n", pPars.nCallsRecycle)
