/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Srm(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pFileNameIn string
	var pFileName [10]byte = "gsrm.aig"
	var pFileName2 [10]byte = "gsyn.aig"
	var pTemp, pAux *Gia_Man_t
	var c, fVerbose int32
	var fSynthesis int32
	var fSpeculate int32 = 1
	var fSkipSome int32
	var fDualOut int32
	var fComb int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Adrsfcvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Adrsfcvh") {
		switch c {
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by a file name.\n")
				goto usage
			}
			pFileNameIn = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'd':
			fDualOut ^= 1
			break
		case 'r':
			fSynthesis ^= 1
			break
		case 's':
			fSpeculate ^= 1
			break
		case 'f':
			fSkipSome ^= 1
			break
		case 'c':
			fComb ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Srm(): There is no AIG.\n")
		return 1
	}
	if fComb != 0 {

		var Result int32 = Cec4_ManSimulateOnlyTest(pAbc.pGia, fVerbose)

		pTemp = Gia_ManCombSpecReduce(pAbc.pGia)
		Abc_FrameUpdateGia(pAbc, pTemp)
		Result = 0
		return 0
	}
	pFileName = fmt.Sprintf("gsrm%s.aig", abcSelect(fSpeculate, "", "s"))
	pFileName2 = fmt.Sprintf("gsyn%s.aig", abcSelect(fSpeculate, "", "s"))
	pTemp = Gia_ManSpecReduce(pAbc.pGia, fDualOut, fSynthesis, fSpeculate, fSkipSome, fVerbose)
	if pTemp != nil {
		if fSpeculate != 0 {
			pAux = pTemp
			pTemp = Gia_ManSeqStructSweep(pAux, 1, 1, 0)
			Gia_ManStop(pAux)
		}
		Gia_AigerWrite(pTemp, abcDefaultString(pFileNameIn, pFileName), 0, 0, 0)
		Abc_Print(1, "Speculatively reduced model was written into file \"%s\".\n", pFileName)
		Gia_ManPrintStatsShort(pTemp)
		Gia_ManStop(pTemp)
	}
	if fSynthesis != 0 {
		pTemp = Gia_ManEquivReduce(pAbc.pGia, 1, fDualOut, 0, fVerbose)
		if pTemp != nil {
			pAux = pTemp
			pTemp = Gia_ManSeqStructSweep(pAux, 1, 1, 0)
			Gia_ManStop(pAux)

			Gia_AigerWrite(pTemp, pFileName2, 0, 0, 0)
			Abc_Print(1, "Reduced original network was written into file \"%s\".\n", pFileName2)
			Gia_ManPrintStatsShort(pTemp)
			Gia_ManStop(pTemp)
		}
	}
	return 0

usage:
	Abc_Print(-2, "usage: &srm [-A file] [-drsfcvh]\n")
	Abc_Print(-2, "\t          derives or writes speculatively reduced model into file \"%s\"\n", pFileName)
	Abc_Print(-2, "\t-A file : file name for dumping speculative-reduced model [default = \"gsrm.aig\"]\n")
	Abc_Print(-2, "\t-d      : toggle creating dual-output miter [default = %s]\n", abcSelect(fDualOut, "yes", "no"))
	Abc_Print(-2, "\t-r      : toggle writing reduced network for synthesis [default = %s]\n", abcSelect(fSynthesis, "yes", "no"))
	Abc_Print(-2, "\t-s      : toggle using speculation at the internal nodes [default = %s]\n", abcSelect(fSpeculate, "yes", "no"))
	Abc_Print(-2, "\t-f      : toggle filtering to remove redundant equivalences [default = %s]\n", abcSelect(fSkipSome, "yes", "no"))
	Abc_Print(-2, "\t-c      : toggle using combinational speculation [default = %s]\n", abcSelect(fComb, "yes", "no"))
	Abc_Print(-2, "\t-v      : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Srm2(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pFileName string // was [10]byte in C

	var pFileName1 string
	var pFileName2 string
	var pTemp, pAux *Gia_Man_t
	var fLatchA, fLatchB int32
	var c, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "abvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "abvh") {
		switch c {
		case 'a':
			fLatchA ^= 1
			break
		case 'b':
			fLatchB ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Srm2(): There is no AIG.\n")
		return 1
	}
	if pAbc.pGia.pReprs == nil || pAbc.pGia.pNexts == nil {
		Abc_Print(-1, "Equivalences are not defined.\n")
		return 0
	}
	if argc != globalUtilOptind+2 {
		Abc_Print(-1, "Abc_CommandAbc9Srm2(): Expecting two file names on the command line.\n")
		return 1
	}
	// get the input file name
	pFileName1 = argv[globalUtilOptind]
	pFileName2 = argv[globalUtilOptind+1]
	// create file name
	pFileName = fmt.Sprintf("gsrm.aig")
	pTemp = Gia_ManDup(pAbc.pGia)
	// copy equivalences
	pTemp.pReprs = ABC_ALLOC(Gia_Rpr_t, Gia_ManObjNum(pTemp))
	memcpy(pTemp.pReprs, pAbc.pGia.pReprs, sizeof(Gia_Rpr_t)*Gia_ManObjNum(pTemp))
	pTemp.pNexts = ABC_ALLOC(int, Gia_ManObjNum(pTemp))
	memcpy(pTemp.pNexts, pAbc.pGia.pNexts, sizeof(int)*Gia_ManObjNum(pTemp))
	//Gia_ManPrintStats( pTemp, 0 );
	// filter the classes
	if !Gia_ManFilterEquivsForSpeculation(pTemp, pFileName1, pFileName2, fLatchA, fLatchB) {
		Gia_ManStop(pTemp)
		Abc_Print(-1, "Filtering equivalences has failed.\n")
		return 1
	}
	//Gia_ManPrintStats( pTemp, 0 );
	pAux = pTemp
	pTemp = Gia_ManSpecReduce(pAux, 0, 0, 1, 0, 0)
	Gia_ManStop(pAux)
	if pTemp != nil {
		pAux = pTemp
		pTemp = Gia_ManSeqStructSweep(pAux, 1, 1, 0)
		Gia_ManStop(pAux)

		Gia_AigerWrite(pTemp, pFileName, 0, 0, 0)
		Abc_Print(1, "Speculatively reduced model was written into file \"%s\".\n", pFileName)
		Gia_ManPrintStatsShort(pTemp)
		Gia_ManStop(pTemp)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &srm2 [-abvh] <PartA_FileName> <PartB_FileName>\n")
	Abc_Print(-2, "\t         writes speculatively reduced model into file \"%s\"\n", pFileName)
	Abc_Print(-2, "\t         only preserves equivalences across PartA and PartB\n")
	Abc_Print(-2, "\t-a     : toggle using latches only in PartA [default = %s]\n", abcSelect(fLatchA, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggle using latches only in PartB [default = %s]\n", abcSelect(fLatchB, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Filter(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pFileName1 string
	var pFileName2 string
	var fFlopsOnly, fFlopsWith, fUseRiDrivers int32
	var c, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "fgivh"); c != -1; c = Extra_UtilGetopt(argc, argv, "fgivh") {
		switch c {
		case 'f':
			fFlopsOnly ^= 1
			break
		case 'g':
			fFlopsWith ^= 1
			break
		case 'i':
			fUseRiDrivers ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Srm2(): There is no AIG.\n")
		return 1
	}
	if pAbc.pGia.pReprs == nil || pAbc.pGia.pNexts == nil {
		Abc_Print(-1, "Equivalences are not defined.\n")
		return 0
	}
	if argc != globalUtilOptind && argc != globalUtilOptind+2 {
		Abc_Print(-1, "Abc_CommandAbc9Srm2(): Expecting two file names on the command line.\n")
		return 1
	}
	// filter using one of the choices
	if fFlopsOnly ^ fFlopsWith {
		Gia_ManFilterEquivsUsingLatches(pAbc.pGia, fFlopsOnly, fFlopsWith, fUseRiDrivers)
	}
	// get the input file name
	if argc == globalUtilOptind+2 {
		pFileName1 = argv[globalUtilOptind]
		pFileName2 = argv[globalUtilOptind+1]
		if !Gia_ManFilterEquivsUsingParts(pAbc.pGia, pFileName1, pFileName2) {
			Abc_Print(-1, "Filtering equivalences using PartA and PartB has failed.\n")
			return 1
		}
	}
	return 0

usage:
	Abc_Print(-2, "usage: &filter [-fgivh] <PartA_FileName> <PartB_FileName>\n")
	Abc_Print(-2, "\t         performs filtering of equivalence classes\n")
	Abc_Print(-2, "\t         (if Parts A/B are given, removes classes composed of one part)\n")
	Abc_Print(-2, "\t-f     : toggle removing all elements except flops [default = %s]\n", abcSelect(fFlopsOnly, "yes", "no"))
	Abc_Print(-2, "\t-g     : toggle removing classes without flops [default = %s]\n", abcSelect(fFlopsWith, "yes", "no"))
	Abc_Print(-2, "\t-i     : toggle using flop inputs instead of flop outputs [default = %s]\n", abcSelect(fUseRiDrivers, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Reduce(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp, pTemp2 *Gia_Man_t
	var c, fVerbose int32
	var fUseAll int32
	var fDualOut int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "advh"); c != -1; c = Extra_UtilGetopt(argc, argv, "advh") {
		switch c {
		case 'a':
			fUseAll ^= 1
			break
		case 'd':
			fDualOut ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Reduce(): There is no AIG.\n")
		return 1
	}
	if fUseAll != 0 {
		pTemp = Gia_ManEquivReduce(pAbc.pGia, fUseAll, fDualOut, 0, fVerbose)
		pTemp2 = pTemp
		pTemp = Gia_ManSeqStructSweep(pTemp2, 1, 1, 0)
		Gia_ManStop(pTemp2)

	} else {
		pTemp = Gia_ManEquivReduceAndRemap(pAbc.pGia, 1, fDualOut)
	}
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &reduce [-advh]\n")
	Abc_Print(-2, "\t         reduces the circuit using equivalence classes\n")
	Abc_Print(-2, "\t-a     : toggle merging all equivalences [default = %s]\n", abcSelect(fUseAll, "yes", "no"))
	Abc_Print(-2, "\t-d     : toggle using dual-output merging [default = %s]\n", abcSelect(fDualOut, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

