	Abc_Print(-2, "\t-d     : toggle dumping AIGs to be compared [default = %s]\n", abcSelect(fDumpFiles, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
