			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by a floating point number.\n")
				goto usage
			}
			pPars.DelayTarget = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.DelayTarget <= 0.0 {
				goto usage
			}
			break
