/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Pack(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var nBlock int32 = 2
	var DelayRoute int32 = 10
	var DelayDir int32 = 2
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NRDvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NRDvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by a positive integer.\n")
				goto usage
			}
			nBlock = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBlock < 2 {
				Abc_Print(-1, "LUT block size (%d) should be more than 1.\n", nBlock)
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by a positive integer.\n")
				goto usage
			}
			DelayRoute = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if DelayRoute <= 0 {
				Abc_Print(-1, "Rounting delay (%d) should be more than 0.\n", DelayRoute)
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by a positive integer.\n")
				goto usage
			}
			DelayDir = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if DelayDir <= 0 {
				Abc_Print(-1, "Direct delay (%d) should be more than 0.\n", DelayRoute)
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			fallthrough
		default:
			goto usage
		}
	}

	if pAbc.pGia == nil {
		Abc_Print(-1, "Empty GIA network.\n")
		return 1
	}
	if !Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(-1, "Current AIG has no mapping. Run \"&if\".\n")
		return 1
	}
	if Gia_ManLutSizeMax(pAbc.pGia) > 6 {
		Abc_Print(0, "Current AIG has mapping into %d-LUTs.\n", Gia_ManLutSizeMax(pAbc.pGia))
	} else {
		Gia_ManLutPacking(pAbc.pGia, nBlock, DelayRoute, DelayDir, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &pack [-NRD num] [-vh]\n")
	Abc_Print(-2, "\t           performs packing for the LUT mapped network\n")
	Abc_Print(-2, "\t-N num   : the number of LUTs in the block [default = %d]\n", nBlock)
	Abc_Print(-2, "\t-R num   : the routable delay of a LUT [default = %d]\n", DelayRoute)
	Abc_Print(-2, "\t-D num   : the direct (non-routable) delay of a LUT [default = %d]\n", DelayDir)
	Abc_Print(-2, "\t-v       : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : prints the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Edge(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var nBTLimit int32
	var DelayMax int32
	var nFanouts int32
	var nEdges int32 = 1
	var fReverse int32
	var fUsePack int32
	var fUseOld int32
	var fMapping int32
	var fDynamic int32 = 1
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "CDFErpomdvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "CDFErpomdvh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by a positive integer.\n")
				goto usage
			}
			nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by a positive integer.\n")
				goto usage
			}
			DelayMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by a positive integer.\n")
				goto usage
			}
			nFanouts = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'E':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-E\" should be followed by a positive integer.\n")
				goto usage
			}
			nEdges = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nEdges != 1 && nEdges != 2 {
				Abc_Print(-1, "Edge limit (%d) should be 1 or 2.\n", nEdges)
				goto usage
			}
			break
		case 'r':
			fReverse ^= 1
			break
		case 'p':
			fUsePack ^= 1
			break
		case 'o':
			fUseOld ^= 1
			break
		case 'm':
			fMapping ^= 1
			break
		case 'd':
			fDynamic ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			fallthrough
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Empty GIA network.\n")
		return 1
	}
	if fMapping != 0 {
		Sle_ManExplore(pAbc.pGia, nBTLimit, DelayMax, fDynamic, nEdges == 2, fVerbose)
		return 0
	}
	if !Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(-1, "Current AIG has no mapping. Run \"&if\".\n")
		return 1
	}
	if Gia_ManLutSizeMax(pAbc.pGia) > 6 {
		Abc_Print(0, "Current AIG has mapping into %d-LUTs.\n", Gia_ManLutSizeMax(pAbc.pGia))
		return 0
	}
	if fUsePack != 0 {
		if pAbc.pGia.vPacking == nil {
			Abc_Print(-1, "Packing information is not present.\n")
			return 0
		}
		Gia_ManConvertPackingToEdges(pAbc.pGia)
		return 0
	}
	if !(fUseOld != 0) {
		//Edg_ManAssignEdgeNew( pAbc->pGia, nEdges, fVerbose );
		Seg_ManComputeDelay(pAbc.pGia, DelayMax, nFanouts, nEdges == 2, fVerbose)
		return 0
	}
	if pAbc.pGia.pManTime && (fReverse != 0) {
		Abc_Print(0, "Reverse computation does not work when boxes are present.\n")
		return 0
	}
	if fReverse != 0 {
		DelayMax = Gia_ManComputeEdgeDelay2(pAbc.pGia)
	} else {
		DelayMax = Gia_ManComputeEdgeDelay(pAbc.pGia, nEdges == 2)
	}
	//printf( "The number of edges = %d.  Delay = %d.\n", Gia_ManEvalEdgeCount(pAbc->pGia), DelayMax );
	return 0

usage:
	Abc_Print(-2, "usage: &edge [-CDFE num] [-rpomdvh]\n")
	Abc_Print(-2, "\t           find edge assignment of the LUT-mapped network\n")
	Abc_Print(-2, "\t-C num   : the SAT solver conflict limit (0 = unused) [default = %d]\n", nBTLimit)
	Abc_Print(-2, "\t-D num   : the upper bound on delay [default = %d]\n", DelayMax)
	Abc_Print(-2, "\t-F num   : skip using edge if fanout higher than this [default = %d]\n", nFanouts)
	Abc_Print(-2, "\t-E num   : the limit on the number of edges (1 <= num <= 2) [default = %d]\n", nEdges)
	Abc_Print(-2, "\t-r       : toggles using reverse order [default = %s]\n", abcSelect(fReverse, "yes", "no"))
	Abc_Print(-2, "\t-p       : toggles deriving edges from packing [default = %s]\n", abcSelect(fUsePack, "yes", "no"))
	Abc_Print(-2, "\t-o       : toggles using old algorithm [default = %s]\n", abcSelect(fUseOld, "yes", "no"))
	Abc_Print(-2, "\t-m       : toggles combining edge assignment with mapping [default = %s]\n", abcSelect(fMapping, "yes", "no"))
	Abc_Print(-2, "\t-d       : toggles dynamic addition of clauses [default = %s]\n", abcSelect(fDynamic, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : prints the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9SatLut(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var LutSize int32
	var nNumber int32 = 32
	var nImproves int32
	var nBTLimit int32 = 100
	var DelayMax int32
	var nEdges int32
	var fDelay, fReverse, fVeryVerbose, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NICDQdrwvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NICDQdrwvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by a positive integer.\n")
				goto usage
			}
			nNumber = abcAtoi(argv[globalUtilOptind])
			if nNumber > 128 {
				Abc_Print(-1, "The number of AIG nodes should not exceed 128.\n")
				goto usage
			}
			globalUtilOptind++
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by a positive integer.\n")
				goto usage
			}
			nImproves = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by a positive integer.\n")
				goto usage
			}
			nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by a positive integer.\n")
				goto usage
			}
			DelayMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'Q':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-Q\" should be followed by a positive integer.\n")
				goto usage
			}
			nEdges = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			break
		case 'd':
			fDelay ^= 1
			break
		case 'r':
			fReverse ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			fallthrough
		default:
			goto usage
		}
	}

	if pAbc.pGia == nil {
		Abc_Print(-1, "Empty GIA network.\n")
		return 1
	}
	if !Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(-1, "Current AIG has no mapping. Run \"&if\".\n")
		return 1
	}
	LutSize = Gia_ManLutSizeMax(pAbc.pGia)
	if LutSize > 6 {
		Abc_Print(0, "Current AIG is mapped into %d-LUTs (only 6-LUT mapping is currently supported).\n", Gia_ManLutSizeMax(pAbc.pGia))
	} else {
		Gia_ManLutSat(pAbc.pGia, LutSize, nNumber, nImproves, nBTLimit, DelayMax, nEdges, fDelay, fReverse, fVerbose, fVeryVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &satlut [-NICDQ num] [-drwvh]\n")
	Abc_Print(-2, "\t           performs SAT-based remapping of the LUT-mapped network\n")
	Abc_Print(-2, "\t-N num   : the limit on AIG nodes in the window (num <= 128) [default = %d]\n", nNumber)
	Abc_Print(-2, "\t-I num   : the limit on the number of improved windows [default = %d]\n", nImproves)
	Abc_Print(-2, "\t-C num   : the limit on the number of conflicts [default = %d]\n", nBTLimit)
	Abc_Print(-2, "\t-D num   : the user-specified required times at the outputs [default = %d]\n", DelayMax)
	Abc_Print(-2, "\t-Q num   : the maximum number of edges [default = %d]\n", nEdges)
	Abc_Print(-2, "\t-d       : toggles delay optimization [default = %s]\n", abcSelect(fDelay, "yes", "no"))
	Abc_Print(-2, "\t-r       : toggles using reverse search [default = %s]\n", abcSelect(fReverse, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggles verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : prints the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Unmap(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "vh"); c != -1; c = Extra_UtilGetopt(argc, argv, "vh") {
		switch c {
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Struct(): There is no AIG to map.\n")
		return 1
	}
	Vec_IntFreeP(&pAbc.pGia.vMapping)
	Vec_IntFreeP(&pAbc.pGia.vPacking)
	Vec_IntFreeP(&pAbc.pGia.vCellMapping)
	Vec_IntFreeP(&pAbc.pGia.vEdge1)
	Vec_IntFreeP(&pAbc.pGia.vEdge2)
	return 0

usage:
	Abc_Print(-2, "usage: &unmap [-vh]\n")
	Abc_Print(-2, "\t           removes mapping from the current network\n")
	Abc_Print(-2, "\t-v       : toggle printing optimization summary [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

