/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Speedup(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var fUseLutLib int32
	var Percentage int32
	var Degree int32
	var fVerbose int32
	var c, fVeryVerbose int32

	// set defaults
	fUseLutLib = 0
	Percentage = 5
	Degree = 2
	fVerbose = 0
	fVeryVerbose = 0
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "PNlvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "PNlvwh") {
		switch c {
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			Percentage = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Percentage < 1 || Percentage > 100 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			Degree = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Degree < 1 || Degree > 5 {
				goto usage
			}
			break
		case 'l':
			fUseLutLib ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Speedup(): There is no AIG to map.\n")
		return 1
	}
	if !Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Speedup(): Mapping of the AIG is not defined.\n")
		return 1
	}
	if fUseLutLib != 0 {
		pAbc.pGia.pLutLib = pAbc.pLibLut
	} else {
		pAbc.pGia.pLutLib = nil
	}
	pTemp = Gia_ManSpeedup(pAbc.pGia, Percentage, Degree, fVerbose, fVeryVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &speedup [-P num] [-N num] [-lvwh]\n")
	Abc_Print(-2, "\t           transforms LUT-mapped network into an AIG with choices;\n")
	Abc_Print(-2, "\t           the choices are added to speedup the next round of mapping\n")
	Abc_Print(-2, "\t-P <num> : delay delta defining critical path for library model [default = %d%%]\n", Percentage)
	Abc_Print(-2, "\t-N <num> : the max critical path degree for resynthesis (0 < num < 6) [default = %d]\n", Degree)
	Abc_Print(-2, "\t-l       : toggle using unit- or LUT-library-delay model [default = %s]\n", abcSelect(fUseLutLib, "lib", "unit"))
	Abc_Print(-2, "\t-v       : toggle printing optimization summary [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggle printing detailed stats for each node [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Era(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	//    Gia_Man_t * pTemp = NULL;
	var c, fVerbose int32
	var fUseCubes int32 = 1
	var fDumpFile int32
	var fMiter int32
	var nStatesMax int32 = 1000000000

	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Smcdvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Smcdvh") {
		switch c {
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by a positive integer.\n")
				goto usage
			}
			nStatesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nStatesMax < 0 {
				goto usage
			}
			break
		case 'm':
			fMiter ^= 1
			break
		case 'c':
			fUseCubes ^= 1
			break
		case 'd':
			fDumpFile ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Era(): There is no AIG.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) == 0 {
		Abc_Print(-1, "Abc_CommandAbc9Era(): The network is combinational.\n")
		return 1
	}
	if !(fUseCubes != 0) && Gia_ManPiNum(pAbc.pGia) > 12 {
		Abc_Print(-1, "Abc_CommandAbc9Era(): The number of PIs (%d) should be no more than 12 when cubes are not used.\n", Gia_ManPiNum(pAbc.pGia))
		return 1
	}
	if (fUseCubes != 0) && !(fDumpFile != 0) {
		pAbc.Status = Gia_ManArePerform(pAbc.pGia, nStatesMax, fMiter, fVerbose)
	} else {
		pAbc.Status = Gia_ManCollectReachable(pAbc.pGia, nStatesMax, fMiter, fDumpFile, fVerbose)
	}
	Abc_FrameReplaceCex(pAbc, &pAbc.pGia.pCexSeq)
	return 0

usage:
	Abc_Print(-2, "usage: &era [-S num] [-mcdvh]\n")
	Abc_Print(-2, "\t          explicit reachability analysis for small sequential AIGs\n")
	Abc_Print(-2, "\t-S num  : the max number of states (num > 0) [default = %d]\n", nStatesMax)
	Abc_Print(-2, "\t-m      : stop when the miter output is 1 [default = %s]\n", abcSelect(fMiter, "yes", "no"))
	Abc_Print(-2, "\t-c      : use state cubes instead of state minterms [default = %s]\n", abcSelect(fUseCubes, "yes", "no"))
	Abc_Print(-2, "\t-d      : toggle dumping STG into a file [default = %s]\n", abcSelect(fDumpFile, "yes", "no"))
	Abc_Print(-2, "\t-v      : print verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Dch(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var Pars Dch_Pars_t
	var pPars *Dch_Pars_t = &Pars
	var c, fMinLevel, fEquiv int32
	// set defaults
	Dch_ManSetDefaultParams(pPars)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "WCSsptfremgcxvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "WCSsptfremgcxvh") {
		switch c {
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nWords = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nWords < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nBTLimit < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nSatVarMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nSatVarMax < 0 {
				goto usage
			}
			break
		case 's':
			pPars.fSynthesis ^= 1
			break
		case 'p':
			pPars.fPower ^= 1
			break
		case 't':
			pPars.fSimulateTfo ^= 1
			break
		case 'f':
			pPars.fLightSynth ^= 1
			break
		case 'r':
			pPars.fSkipRedSupp ^= 1
			break
		case 'e':
			fEquiv ^= 1
			break
		case 'm':
			fMinLevel ^= 1
			break
		case 'g':
			pPars.fUseGia ^= 1
			break
		case 'c':
			pPars.fUseCSat ^= 1
			break
		case 'x':
			pPars.fUseNew ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Dch(): There is no AIG.\n")
		return 1
	}
	if Gia_ManBufNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Dch(): This command does not work with barrier buffers.\n")
		return 1
	}
	if fEquiv != 0 {
		var pNew *Aig_Man_t = Gia_ManToAigSimple(pAbc.pGia)
		assert(Gia_ManObjNum(pAbc.pGia) == Aig_ManObjNum(pNew), "Gia_ManObjNum(pAbc.pGia) == Aig_ManObjNum(pNew)")
		Dch_ComputeEquivalences(pNew, pPars)
		Gia_ManReprFromAigRepr(pNew, pAbc.pGia)
		Aig_ManStop(pNew)
		pTemp = Gia_ManEquivReduce(pAbc.pGia, 1, 0, 0, 0)

	} else {
		pTemp = Gia_ManPerformDch(pAbc.pGia, pPars)
		Abc_FrameUpdateGia(pAbc, pTemp)
		if fMinLevel != 0 {
			pTemp = Gia_ManEquivReduce2(pAbc.pGia)
		}
	}
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &dch [-WCS num] [-sptfremgcxvh]\n")
	Abc_Print(-2, "\t         computes structural choices using a new approach\n")
	Abc_Print(-2, "\t-W num : the max number of simulation words [default = %d]\n", pPars.nWords)
	Abc_Print(-2, "\t-C num : the max number of conflicts at a node [default = %d]\n", pPars.nBTLimit)
	Abc_Print(-2, "\t-S num : the max number of SAT variables [default = %d]\n", pPars.nSatVarMax)
	Abc_Print(-2, "\t-s     : toggle synthesizing three snapshots [default = %s]\n", abcSelect(fSynthesis, "yes", "no"))
	Abc_Print(-2, "\t-p     : toggle power-aware rewriting [default = %s]\n", abcSelect(fPower, "yes", "no"))
	Abc_Print(-2, "\t-t     : toggle simulation of the TFO classes [default = %s]\n", abcSelect(fSimulateTfo, "yes", "no"))
	Abc_Print(-2, "\t-f     : toggle using lighter logic synthesis [default = %s]\n", abcSelect(fLightSynth, "yes", "no"))
	Abc_Print(-2, "\t-r     : toggle skipping choices with redundant support [default = %s]\n", abcSelect(fSkipRedSupp, "yes", "no"))
	Abc_Print(-2, "\t-e     : toggle computing and merging equivalences [default = %s]\n", abcSelect(fEquiv, "yes", "no"))
	Abc_Print(-2, "\t-m     : toggle minimizing logic level after merging equivalences [default = %s]\n", abcSelect(fMinLevel, "yes", "no"))
	Abc_Print(-2, "\t-g     : toggle using GIA to prove equivalences [default = %s]\n", abcSelect(fUseGia, "yes", "no"))
	Abc_Print(-2, "\t-c     : toggle using circuit-based SAT vs. MiniSat [default = %s]\n", abcSelect(fUseCSat, "yes", "no"))
	Abc_Print(-2, "\t-x     : toggle using new choice computation [default = %s]\n", abcSelect(fUseNew, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose printout [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Rpm(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var c int32
	var nCutMax int32 = 16
	var fUseNaive int32
	var fUseOldAlgo int32
	var fVerbose int32
	var fVeryVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Cnavwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Cnavwh") {
		switch c {
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nCutMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCutMax < 0 {
				goto usage
			}
			break
		case 'n':
			fUseNaive ^= 1
			break
		case 'a':
			fUseOldAlgo ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Rpm(): There is no AIG.\n")
		return 0
	}
	if fUseNaive != 0 {
		pTemp = Gia_ManDupReplaceCut(pAbc.pGia)
	} else if fUseOldAlgo != 0 {
		pTemp = Abs_RpmPerformOld(pAbc.pGia, fVerbose)
	} else {
		pTemp = Abs_RpmPerform(pAbc.pGia, nCutMax, fVerbose, fVeryVerbose)
	}
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &rpm [-C num] [-navwh]\n")
	Abc_Print(-2, "\t         performs structural reparametrization\n")
	Abc_Print(-2, "\t-C num : max cut size for testing range equivalence [default = %d]\n", nCutMax)
	Abc_Print(-2, "\t-n     : toggle using naive reparametrization [default = %s]\n", abcSelect(fUseNaive, "yes", "no"))
	Abc_Print(-2, "\t-a     : toggle using old algorithm [default = %s]\n", abcSelect(fUseOldAlgo, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggle printing more verbose information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9BackReach(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t = nil
	var c, fVerbose int32
	var nFrameMax int32 = 1000000
	var nConfMax int32 = 1000000
	var nTimeMax int32 = 10
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FCTvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FCTvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrameMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrameMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfMax < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			nTimeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nTimeMax < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9BackReach(): There is no AIG.\n")
		return 1
	}
	if Gia_ManPoNum(pAbc.pGia) != 1 {
		Abc_Print(-1, "Abc_CommandAbc9BackReach(): The number of POs is different from 1.\n")
		return 1
	}
	pTemp = Gia_ManCofTest(pAbc.pGia, nFrameMax, nConfMax, nTimeMax, fVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &back_reach [-FCT <num>] [-vh]\n")
	Abc_Print(-2, "\t         performs backward reachability by circuit cofactoring\n")
	Abc_Print(-2, "\t-F num : the limit on the depth of induction [default = %d]\n", nFrameMax)
	Abc_Print(-2, "\t-C num : the conflict limit at a node during induction [default = %d]\n", nConfMax)
	Abc_Print(-2, "\t-T num : the timeout for property directed reachability [default = %d]\n", nTimeMax)
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Posplit(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pMan, pAux *Aig_Man_t
	var pTemp *Gia_Man_t = nil
	var c int32
	var nVars int32 = 5
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Nvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Nvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nVars < 0 {
				goto usage
			}
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Posplit(): There is no AIG.\n")
		return 1
	}
	pMan = Gia_ManToAigSimple(pAbc.pGia)
	pAux = pMan
	pMan = Aig_ManSplit(pAux, nVars, fVerbose)
	Aig_ManStop(pAux)
	if pMan != nil {
		pTemp = Gia_ManFromAigSimple(pMan)
		Aig_ManStop(pMan)
		Abc_FrameUpdateGia(pAbc, pTemp)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &posplit [-N num] [-vh]\n")
	Abc_Print(-2, "\t         cofactors the property output w.r.t. a support subset\n")
	Abc_Print(-2, "\t         (the OR of new PO functions is equal to the original property)\n")
	Abc_Print(-2, "\t-N num : the number of random cofactoring variables [default = %d]\n", nVars)
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

