/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Undo(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var c int32
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "h"); c != -1; c = Extra_UtilGetopt(argc, argv, "h") {
		switch c {
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Undo(): There is no design.\n")
		return 1
	}
	if pAbc.pGia2 == nil {
		Abc_Print(-1, "Abc_CommandAbc9Undo(): There is no previously saved network.\n")
		return 1
	}
	Gia_ManStop(pAbc.pGia)
	pAbc.pGia = pAbc.pGia2
	pAbc.pGia2 = nil
	return 0

usage:
	Abc_Print(-2, "usage: &undo [-h]\n")
	Abc_Print(-2, "\t        reverses the previous AIG transformation\n")
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Mesh(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var X int32 = 4
	var Y int32 = 4
	var T int32 = 3
	var fUseSatoko int32 = 1
	var c int32
	var fVerbose int32 = 1
	// set defaults
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "XYTsh"); c != -1; c = Extra_UtilGetopt(argc, argv, "XYTsh") {
		switch c {
		case 'X':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-X\" should be followed by an integer.\n")
				goto usage
			}
			X = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if X < 3 {
				goto usage
			}
			break
		case 'Y':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-Y\" should be followed by an integer.\n")
				goto usage
			}
			Y = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Y < 3 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			T = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if T < 2 {
				goto usage
			}
			break
		case 's':
			fUseSatoko ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Mesh(): There is no design.\n")
		return 1
	}
	if Gia_ManCoNum(pAbc.pGia) != 1 {
		Abc_Print(-1, "Currently this command expects AIG with one output.\n")
		return 1
	}
	if Gia_ManCiNum(pAbc.pGia) > 20 {
		Abc_Print(-1, "Currently this command expects AIG with no more than 20 nodes.\n")
		return 1
	}
	if Gia_ManLevelNum(pAbc.pGia) > T {
		Abc_Print(-1, "The depth of the AIG (%d) cannot be larger than the latency (%d).\n", Gia_ManLevelNum(pAbc.pGia), T)
		return 1
	}
	if fUseSatoko != 0 {
		Bmc_MeshTest(pAbc.pGia, X, Y, T, fVerbose)
	} else {
		Bmc_MeshTest2(pAbc.pGia, X, Y, T, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &mesh [-XYT num] [-sh]\n")
	Abc_Print(-2, "\t         creates a mesh architecture for the given AIG\n")
	Abc_Print(-2, "\t-X num : horizontal size of the mesh (X >= 3) [default = %d]\n", X)
	Abc_Print(-2, "\t-Y num : vertical size of the mesh (Y >= 3) [default = %d]\n", Y)
	Abc_Print(-2, "\t-T num : the latency of the mesh (T >= 2) [default = %d]\n", T)
	Abc_Print(-2, "\t-s     : toggle using new SAT solver Satoko [default = %s]\n", abcSelect(fUseSatoko, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Iso(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pAig *Gia_Man_t
	var vPosEquivs *Vec_Ptr_t
	//    Vec_Ptr_t * vPiPerms;
	var c int32
	var fNewAlgo int32 = 1
	var fEstimate int32
	var fBetterQual int32
	var fDualOut int32
	var fVerbose int32
	var fVeryVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "neqdvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "neqdvwh") {
		switch c {
		case 'n':
			fNewAlgo ^= 1
			break
		case 'e':
			fEstimate ^= 1
			break
		case 'q':
			fBetterQual ^= 1
			break
		case 'd':
			fDualOut ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'w':
			fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Iso(): There is no AIG.\n")
		return 1
	}
	if Gia_ManPoNum(pAbc.pGia) == 1 {
		Abc_Print(-1, "Abc_CommandAbc9Iso(): The AIG has only one PO. Isomorphism detection is not performed.\n")
		return 1
	}
	if fNewAlgo != 0 {
		pAig = Gia_ManIsoReduce2(pAbc.pGia, &vPosEquivs, nil, fEstimate, fBetterQual, fDualOut, fVerbose, fVeryVerbose)
	} else {
		pAig = Gia_ManIsoReduce(pAbc.pGia, &vPosEquivs, nil, fEstimate, fDualOut, fVerbose, fVeryVerbose)
	}
	//    pAig = Gia_ManIsoReduce( pAbc->pGia, &vPosEquivs, &vPiPerms, 0, fDualOut, fVerbose, fVeryVerbose );
	//    Vec_VecFree( (Vec_Vec_t *)vPiPerms );
	if pAig == nil {
		Abc_Print(-1, "Abc_CommandAbc9Iso(): Transformation has failed.\n")
		return 1
	}
	// update the internal storage of PO equivalences
	Abc_FrameReplacePoEquivs(pAbc, &vPosEquivs)
	// update the AIG
	Abc_FrameUpdateGia(pAbc, pAig)
	return 0

usage:
	Abc_Print(-2, "usage: &iso [-neqdvwh]\n")
	Abc_Print(-2, "\t         removes POs with isomorphic sequential COI\n")
	Abc_Print(-2, "\t-n     : toggle using new fast algorithm [default = %s]\n", abcSelect(fNewAlgo, "yes", "no"))
	Abc_Print(-2, "\t-e     : toggle computing lower bound on equivalence classes [default = %s]\n", abcSelect(fEstimate, "yes", "no"))
	Abc_Print(-2, "\t-q     : toggle improving quality at the expense of runtime [default = %s]\n", abcSelect(fBetterQual, "yes", "no"))
	Abc_Print(-2, "\t-d     : toggle treating the current AIG as a dual-output miter [default = %s]\n", abcSelect(fDualOut, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w     : toggle printing very verbose information [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9IsoNpn(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pAig *Gia_Man_t
	var vPosEquivs *Vec_Ptr_t
	var c, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "vh"); c != -1; c = Extra_UtilGetopt(argc, argv, "vh") {
		switch c {
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9IsoNpn(): There is no AIG.\n")
		return 1
	}
	if Gia_ManPoNum(pAbc.pGia) == 1 {
		Abc_Print(-1, "Abc_CommandAbc9IsoNpn(): The AIG has only one PO. Isomorphism detection is not performed.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9IsoNpn(): ISO-NPN does not work with sequential AIGs.\n")
		return 1
	}
	pAig = Gia_ManIsoNpnReduce(pAbc.pGia, &vPosEquivs, fVerbose)
	if pAig == nil {
		Abc_Print(-1, "Abc_CommandAbc9IsoNpn(): Transformation has failed.\n")
		return 1
	}
	// update the internal storage of PO equivalences
	Abc_FrameReplacePoEquivs(pAbc, &vPosEquivs)
	// update the AIG
	Abc_FrameUpdateGia(pAbc, pAig)
	return 0

usage:
	Abc_Print(-2, "usage: &isonpn [-vh]\n")
	Abc_Print(-2, "\t         removes POs with functionally isomorphic combinational COI\n")
	Abc_Print(-2, "\t         (currently ignores POs whose structural support is more than 16)\n")
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

