func Abc_CommandAbc9Cycle(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var c int32
	var nFrames int32 = 10
	var fUseCex int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Fcvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Fcvh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'c':
			fUseCex ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Cycle(): There is no AIG.\n")
		return 1
	}
	if fUseCex != 0 {
		cex = pAbc.pCex
	}
	pTemp = Gia_ManDupCycled(pAbc.pGia, cex, nFrames)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &cycle [-F num] [-cvh]\n")
	Abc_Print(-2, "\t         cycles sequential circuit for the given number of timeframes\n")
	Abc_Print(-2, "\t         to derive a new initial state (which may be on the envelope)\n")
	Abc_Print(-2, "\t-F num : the number of frames to simulate [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-c     : toggle using PI values from the current CEX [default = %s]\n", abcSelect(fUseCex, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Cone(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var vPos *Vec_Int_t
	var c int32
	var iOutNum int32 = -1
	var nOutRange int32 = 1
	var iPartNum int32 = -1
	var nLevelMax int32
	var nTimeWindow int32
	var fUseAllCis int32
	var fExtractAll int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ORPLWaevh"); c != -1; c = Extra_UtilGetopt(argc, argv, "ORPLWaevh") {
		switch c {
		case 'O':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-O\" should be followed by an integer.\n")
				goto usage
			}
			iOutNum = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iOutNum < 0 {
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			nOutRange = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nOutRange < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			iPartNum = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if iPartNum < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nLevelMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLevelMax < 0 {
				goto usage
			}
			break
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			nTimeWindow = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nTimeWindow < 0 {
				goto usage
			}
			break
		case 'a':
			fUseAllCis ^= 1
			break
		case 'e':
			fExtractAll ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Cone(): There is no AIG.\n")
		return 1
	}
	if fExtractAll != 0 {
		var Buffer string // was [1000]byte in C

		var pObj *Gia_Obj_t
		var i int32
		var nDigits int32 = Abc_Base10Log(Gia_ManPoNum(pAbc.pGia))
		Gia_ManForEachPo(pAbc.pGia, pObj, i)
		{
			var pOne *Gia_Man_t = Gia_ManDupDfsCone(pAbc.pGia, pObj)
			Buffer = fmt.Sprintf("%s_%0*d.aig", Extra_FileNameGeneric(pAbc.pGia.pSpec), nDigits, i)
			Gia_AigerWrite(pOne, Buffer, 0, 0, 0)
			Gia_ManStop(pOne)
		}
		fmt.Printf("Dumped all outputs into individual AIGER files.\n")
		return 0
	}
	if (nLevelMax != 0) || (nTimeWindow != 0) {
		if (nLevelMax != 0) && (nTimeWindow != 0) {
			Abc_Print(-1, "Abc_CommandAbc9Cone(): Parameters -L (max level) and -W (timing window) cannot be specified at the same time.\n")
			return 1

		} else {
			pTemp = Gia_ManExtractWindow(pAbc.pGia, nLevelMax, nTimeWindow, fVerbose)
			Abc_FrameUpdateGia(pAbc, pTemp)
			return 0
		}
	}
	if iPartNum >= 0 {
		var vClass *Vec_Int_t
		vClasses, _ := pAbc.vPoEquivs.(*Vec_Vec_t)
		if vClasses == nil {
			Abc_Print(-1, "Abc_CommandAbc9Cone(): Partitions are not defined.\n")
			return 1
		}
		if iPartNum >= Vec_VecSize(vClasses) {
			Abc_Print(-1, "Abc_CommandAbc9Cone(): Partition index exceed the array size.\n")
			return 1
		}
		vClass = Vec_VecEntryInt(vClasses, iPartNum)
		pTemp = Gia_ManDupCones(pAbc.pGia, Vec_IntArray(vClass), Vec_IntSize(vClass), !fUseAllCis)
		if pTemp != nil {
			Abc_FrameUpdateGia(pAbc, pTemp)
		}
		return 0
	}
	if iOutNum < 0 || iOutNum+nOutRange > Gia_ManPoNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Cone(): Range of outputs to extract is incorrect.\n")
		return 1
	}
	vPos = Vec_IntStartRange(iOutNum, nOutRange)
	pTemp = Gia_ManDupCones(pAbc.pGia, Vec_IntArray(vPos), nOutRange, !fUseAllCis)
	Vec_IntFree(vPos)
	if pTemp != nil {
		Abc_FrameUpdateGia(pAbc, pTemp)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &cone [-ORPLW num] [-aevh]\n")
	Abc_Print(-2, "\t         extracting multi-output sequential logic cones\n")
	Abc_Print(-2, "\t-O num : the index of first PO to extract [default = %d]\n", iOutNum)
	Abc_Print(-2, "\t-R num : (optional) the number of outputs to extract [default = %d]\n", nOutRange)
	Abc_Print(-2, "\t-P num : (optional) the partition number to extract [default = %d]\n", iPartNum)
	Abc_Print(-2, "\t-L num : (optional) extract cones with higher level [default = %d]\n", nLevelMax)
	Abc_Print(-2, "\t-W num : (optional) extract cones falling into this window [default = %d]\n", nTimeWindow)
	Abc_Print(-2, "\t-a     : toggle keeping all CIs or structral support only [default = %s]\n", abcSelect(fUseAllCis, "all", "structural"))
	Abc_Print(-2, "\t-e     : toggle writing all outputs into individual files [default = %s]\n", abcSelect(fExtractAll, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

