/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9FFTest(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var Pars Bmc_ParFf_t
	var pPars *Bmc_ParFf_t = &Pars
	var pFileName string
	var pFileName2 string
	var pGold *Gia_Man_t = nil
	var gold *Gia_Man_t
	var c int32
	Gia_ParFfSetDefault(pPars)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ATNKSGFkbsfcdeunvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "ATNKSGFkbsfcdeunvh") {
		switch c {
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by an integer.\n")
				goto usage
			}
			pPars.Algo = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.Algo < 0 || pPars.Algo > 4 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nTimeOut = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nTimeOut < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nIterCheck = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nIterCheck < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nCardConstr = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nCardConstr <= 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by a string.\n")
				goto usage
			}
			pPars.pFormStr = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by a file name.\n")
				goto usage
			}
			pFileName2 = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'G':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-G\" should be followed by a file name.\n")
				goto usage
			}
			pFileName = argv[globalUtilOptind]
			globalUtilOptind++
			break
		case 'k':
			pPars.fNonStrict ^= 1
			break
		case 'b':
			pPars.fBasic ^= 1
			break
		case 's':
			pPars.fStartPats ^= 1
			break
		case 'f':
			pPars.fFfOnly ^= 1
			break
		case 'c':
			pPars.fCheckUntest ^= 1
			break
		case 'd':
			pPars.fDump ^= 1
			break
		case 'e':
			pPars.fDumpDelay ^= 1
			break
		case 'u':
			pPars.fDumpUntest ^= 1
			break
		case 'n':
			pPars.fDumpNewFaults ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	// read string from file
	if pFileName2 != "" {
		if !(int32(strings.Compare(Extra_FileNameExtension(pFileName2), "blif")) != 0) {

			var pNtk2 *Abc_Ntk_t = Io_Read(pFileName2, Io_ReadFileType(pFileName2), 1, 0)
			var pNtk3 *Abc_Ntk_t = Abc_NtkStrash(pNtk2, 0, 0, 0)
			var pGia *Gia_Man_t = Abc_NtkClpGia(pNtk3)
			var ppNamesIn *string = Abc_NtkCollectCioNames(pNtk2, 0)
			if Gia_ManCoNum(pGia) == 1 {
				pPars.pFormStr = Gia_DeriveFormula(pGia, ppNamesIn)
			} else {
				fmt.Printf("The formula BLIF file contains the network with more one output.\n")
			}
			ABC_FREE(ppNamesIn)
			Gia_ManStop(pGia)
			Abc_NtkDelete(pNtk2)
			Abc_NtkDelete(pNtk3)
			if pPars.pFormStr == nil {
				goto usage
			}

		} else {
			var pFile *os.File = os.Open(pFileName2)
			if pFile == nil {
				Abc_Print(-1, "Abc_CommandAbc9FFTest(): File name \"%s\" with formula is invalid.\n", pFileName2)
				return 0
			}
			pPars.pFormStr = Extra_FileRead(pFile)
			_ = pFile.Close()
			// skip spaces
			for {
				var Len int32 = len(pPars.pFormStr)
				var Char byte = pPars.pFormStr[Len-1]
				if Char == ' ' || Char == '\n' || Char == '\r' || Char == '\t' || Char == -51 {
					pPars.pFormStr[Len-1] = 0
				} else {
					break
				}
			}
		}
		fmt.Printf("Using formula \"%s\" from file \"%s\".\n", pPars.pFormStr, pFileName2)
	}
	if pPars.Algo == 0 && pPars.pFormStr == nil {
		Abc_Print(-1, "Formula string (-S <str>) should be selected when algorithm is 0 (-A 0).\n")
		return 0
	}
	if pPars.Algo != 0 && pPars.pFormStr != nil {
		Abc_Print(-1, "Algorithm should be 0 (-A 0) when formula string is selected (-S <str>).\n")
		return 0
	}
	// get the file name
	if argc == globalUtilOptind+1 {
		var pFile *os.File
		pPars.pFileName = argv[globalUtilOptind]
		pFile = os.Open(pPars.pFileName)
		if pFile == nil {
			Abc_Print(-1, "Cannot open file \"%s\" with the input test patterns.\n", pPars.pFileName)
			return 0
		}
		_ = pFile.Close()
	}
	// check other conditions
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9FFTest(): There is no AIG.\n")
		return 0
	}
	if Gia_ManRegNum(pAbc.pGia) == 0 && pPars.Algo == 1 {
		Abc_Print(-1, "Abc_CommandAbc9FFTest(): For delay testing, AIG should be sequential.\n")
		return 0
	}
	// check if the file is valid
	if pFileName != "" {
		var pFile *os.File = os.Open(pFileName)
		if pFile == nil {
			Abc_Print(-1, "Abc_CommandAbc9FFTest(): File name \"%s\" with golden model is invalid.\n", pFileName)
			return 0
		}
		_ = pFile.Close()
		pGold = Gia_AigerRead(pFileName, 0, 0, 0)
		if pGold == nil {
			Abc_Print(-1, "Abc_CommandAbc9FFTest(): Cannot read file \"%s\" with golden model.\n", pFileName)
			return 0
		}
		if Gia_ManPiNum(pAbc.pGia) != Gia_ManPiNum(pGold) {
			Gia_ManStop(pGold)
			Abc_Print(-1, "Abc_CommandAbc9FFTest(): Old model and gold model have different number of PIs.\n")
			return 0
		}
		if Gia_ManPoNum(pAbc.pGia) != Gia_ManPoNum(pGold) {
			Gia_ManStop(pGold)
			Abc_Print(-1, "Abc_CommandAbc9FFTest(): Old model and gold model have different number of POs.\n")
			return 0
		}
		fmt.Printf("Entered spec AIG from file \"%s\".\n", pFileName)
	}
	gold = pAbc.pGia
	if pGold != nil {
		gold = pGold
	}
	Gia_ManFaultTest(pAbc.pGia, gold, pPars)
	Gia_ManStopP(&pGold)
	if pFileName2 != "" {
		ABC_FREE(pPars.pFormStr)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &fftest [-ATNK num] [-kbsfcdeunvh] <file> [-GF file] [-S str]\n")
	Abc_Print(-2, "\t          performs functional fault test generation\n")
	Abc_Print(-2, "\t-A num  : selects fault model for all gates [default = %d]\n", pPars.Algo)
	Abc_Print(-2, "\t                0: fault model is not selected (use -S str)\n")
	Abc_Print(-2, "\t                1: delay fault testing for sequential circuits\n")
	Abc_Print(-2, "\t                2: traditional stuck-at fault: -S (((a&b)&~p)|q)\n")
	Abc_Print(-2, "\t                3: complement fault: -S ((a&b)^p)\n")
	Abc_Print(-2, "\t                4: functionally observable fault\n")
	Abc_Print(-2, "\t-T num  : specifies approximate runtime limit in seconds [default = %d]\n", pPars.nTimeOut)
	Abc_Print(-2, "\t-N num  : specifies iteration to check for fixed parameters [default = %d]\n", pPars.nIterCheck)
	Abc_Print(-2, "\t-K num  : specifies cardinality constraint (num > 0) [default = unused]\n")
	Abc_Print(-2, "\t-k      : toggles non-strict cardinality (n <= K, instead of n == K) [default = %s]\n", abcSelect(pPars.fNonStrict, "yes", "no"))
	Abc_Print(-2, "\t-b      : toggles testing for single faults (the same as \"-K 1\") [default = %s]\n", abcSelect(pPars.fBasic, "yes", "no"))
	Abc_Print(-2, "\t-s      : toggles starting with the all-0 and all-1 patterns [default = %s]\n", abcSelect(pPars.fStartPats, "yes", "no"))
	Abc_Print(-2, "\t-f      : toggles faults at flop inputs only with \"-A 1\" and \"-S str\" [default = %s]\n", abcSelect(pPars.fFfOnly, "yes", "no"))
	Abc_Print(-2, "\t-c      : toggles checking if there are untestable faults [default = %s]\n", abcSelect(fCheckUntest, "yes", "no"))
	Abc_Print(-2, "\t-d      : toggles dumping test patterns into file \"<file>_tests.txt\" [default = %s]\n", abcSelect(pPars.fDump, "yes", "no"))
	Abc_Print(-2, "\t-e      : toggles dumping test pattern pairs (delay faults only) [default = %s]\n", abcSelect(fDumpDelay, "yes", "no"))
	Abc_Print(-2, "\t-u      : toggles dumping untestable faults into \"<file>_untest.txt\" [default = %s]\n", abcSelect(fDumpUntest, "yes", "no"))
	Abc_Print(-2, "\t-n      : toggles dumping faults not detected by a given test set [default = %s]\n", abcSelect(fDumpNewFaults, "yes", "no"))
	Abc_Print(-2, "\t-v      : toggles printing verbose information [default = %s]\n", abcSelect(pPars.fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	Abc_Print(-2, "\t<file>  : (optional) file name with input test patterns\n\n")
	Abc_Print(-2, "\t-G file : (optional) file name with the golden model\n\n")
	Abc_Print(-2, "\t-F file : (optional) file name with the fault model in BLIF format\n")
	Abc_Print(-2, "\t-S str  : (optional) string representing the fault model\n")
	Abc_Print(-2, "\t          The following notations are used:\n")
	Abc_Print(-2, "\t            Functional variables: {a,b} (both a and b are always present)\n")
	Abc_Print(-2, "\t            Parameter variables: {p,q,r,s,t,u,v,w} (any number from 1 to 8)\n")
	Abc_Print(-2, "\t            Boolean operators: AND(&), OR(|), XOR(^), MUX(?:), NOT(~)\n")
	Abc_Print(-2, "\t            Parentheses should be used around each operator. Spaces not allowed.\n")
	Abc_Print(-2, "\t            Complement (~) is only allowed before variables (use DeMorgan law).\n")
	Abc_Print(-2, "\t            Examples:\n")
	Abc_Print(-2, "\t              (((a&b)&~p)|q)        stuck-at-0/1 at the output\n")
	Abc_Print(-2, "\t              (((a&~p)|q)&b)        stuck-at-0/1 at input a\n")
	Abc_Print(-2, "\t              (((a|p)&(b|q))&~r)    stuck-at-1 at the inputs and stuck-at-0 at the output\n")
	Abc_Print(-2, "\t              (((a&~p)&(b&~q))|r)   stuck-at-0 at the inputs and stuck-at-1 at the output\n")
	Abc_Print(-2, "\t              ((a&b)^p)             complement at the output\n")
	Abc_Print(-2, "\t              (((a^p)&(b^q))^r)     complement at the inputs and at the output\n")
	Abc_Print(-2, "\t              (a?(b?~s:r):(b?q:p))  functionally observable fault at the output\n")
	Abc_Print(-2, "\t              (p?(a|b):(a&b))       replace AND by OR\n")
	Abc_Print(-2, "\t           If the BLIF file is used for the formula with option '-F', following rules apply:\n")
	Abc_Print(-2, "\t              - the network should be combinational and have exactly one primary output\n")
	Abc_Print(-2, "\t              - input names should have only one character:\n")
	Abc_Print(-2, "\t                {a, b} (for functional variables)\n")
	Abc_Print(-2, "\t                {p,q,r,s,t,u,v,w} (for parameter variables)\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Qbf(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c int32
	var nPars int32 = -1
	var nIterLimit int32
	var nConfLimit int32
	var nTimeOut int32
	var nEncVars int32
	var fDumpCnf int32
	var fGlucose int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "PICTKdgvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "PICTKdgvh") {
		switch c {
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nPars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPars < 0 {
				goto usage
			}
			break
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nIterLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nIterLimit < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nConfLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nConfLimit < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			nTimeOut = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nTimeOut < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nEncVars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nEncVars < 0 {
				goto usage
			}
			break
		case 'd':
			fDumpCnf ^= 1
			break
		case 'g':
			fGlucose ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "There is no current GIA.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) {
		Abc_Print(-1, "Works only for combinational networks.\n")
		return 1
	}
	if Gia_ManPoNum(pAbc.pGia) != 1 {
		Abc_Print(-1, "The miter should have one primary output.\n")
		return 1
	}
	if !(nPars > 0 && nPars < Gia_ManPiNum(pAbc.pGia)) {
		Abc_Print(-1, "The number of parameter variables is invalid (should be > 0 and < PI num).\n")
		return 1
	}
	if fDumpCnf != 0 {
		Gia_QbfDumpFile(pAbc.pGia, nPars)
	} else {
		Gia_QbfSolve(pAbc.pGia, nPars, nIterLimit, nConfLimit, nTimeOut, nEncVars, fGlucose, fVerbose)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &qbf [-PICTK num] [-dgvh]\n")
	Abc_Print(-2, "\t         solves QBF problem EpVxM(p,x)\n")
	Abc_Print(-2, "\t-P num : number of parameters p (should be the first PIs) [default = %d]\n", nPars)
	Abc_Print(-2, "\t-I num : quit after the given iteration even if unsolved [default = %d]\n", nIterLimit)
	Abc_Print(-2, "\t-C num : conflict limit per problem [default = %d]\n", nConfLimit)
	Abc_Print(-2, "\t-T num : global timeout [default = %d]\n", nTimeOut)
	Abc_Print(-2, "\t-K num : the number of input bits (for encoding miters only) [default = %d]\n", nEncVars)
	Abc_Print(-2, "\t-d     : toggle dumping QDIMACS file instead of solving [default = %s]\n", abcSelect(fDumpCnf, "yes", "no"))
	Abc_Print(-2, "\t-g     : toggle using Glucose 3.0 by Gilles Audemard and Laurent Simon [default = %s]\n", abcSelect(fGlucose, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9QVar(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var c int32
	var nPars int32 = -1
	var fQuantU int32
	var fQuantE int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "Puevh"); c != -1; c = Extra_UtilGetopt(argc, argv, "Puevh") {
		switch c {
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nPars = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPars < 0 {
				goto usage
			}
			break
		case 'u':
			fQuantU ^= 1
			break
		case 'e':
			fQuantE ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "There is no current GIA.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) {
		Abc_Print(-1, "Works only for combinational networks.\n")
		return 1
	}
	if !(nPars > 0 && nPars < Gia_ManPiNum(pAbc.pGia)) {
		Abc_Print(-1, "The number of parameter variables is invalid (should be > 0 and < PI num).\n")
		return 1
	}
	pTemp = Gia_QbfQuantifyAll(pAbc.pGia, nPars, fQuantU, fQuantE)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &qvar [-P num] [-uevh]\n")
	Abc_Print(-2, "\t         derives cofactors w.r.t. the last NumPi-<num> variables\n")
	Abc_Print(-2, "\t-P num : number of parameters p (should be the first PIs) [default = %d]\n", nPars)
	Abc_Print(-2, "\t-u     : toggle ANDing cofactors (universal quantification) [default = %s]\n", abcSelect(fQuantU, "yes", "no"))
	Abc_Print(-2, "\t-e     : toggle ORing cofactors (existential quantification) [default = %s]\n", abcSelect(fQuantE, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9GenQbf(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var nFrames int32 = 1
	var nLutNum int32 = 1
	var nLutSize int32 = 6
	var pStr string
	var fUseOut int32
	var fVerbose int32
	var c int32
	var pTemp *Gia_Man_t
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "FKNSovh"); c != -1; c = Extra_UtilGetopt(argc, argv, "FKNSovh") {
		switch c {
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			nLutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLutSize < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nLutNum = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLutNum < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by a string.\n")
				goto usage
			}
			pStr = Abc_UtilStrsav(argv[globalUtilOptind])
			globalUtilOptind++
			if pStr == nil {
				goto usage
			}
			break
		case 'o':
			fUseOut ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "There is no current GIA.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) == 0 {
		Abc_Print(-1, "Works only for sequential networks.\n")
		return 1
	}
	if Gia_ManRegNum(pAbc.pGia) < nLutSize*nLutNum {
		Abc_Print(-1, "The number of flops (%d) is less than required (%d).\n", Gia_ManRegNum(pAbc.pGia), nLutSize*nLutNum)
		return 1
	}
	if nFrames != 1 || nLutNum != 1 {
		Abc_Print(-1, "Currently this commands works for one frame and one LUT.\n")
		return 1
	}
	pTemp = Gia_GenQbfMiter(pAbc.pGia, nFrames, nLutNum, nLutSize, pStr, fUseOut, fVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	ABC_FREE(pStr)
	return 0

usage:
	Abc_Print(-2, "usage: &genqbf [-FKN num] [-ovh]\n")
	Abc_Print(-2, "\t         generates QBF miter for computing an inductive invariant\n")
	Abc_Print(-2, "\t-F num : the number of time frames for induction [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-K num : the LUT size [default = %d]\n", nLutSize)
	Abc_Print(-2, "\t-N num : the number of LUTs [default = %d]\n", nLutNum)
	Abc_Print(-2, "\t-o     : toggle using the last output [default = %s]\n", abcSelect(fUseOut, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggle verbose output [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

