/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Demiter(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {
	var pTemp *Gia_Man_t
	var c, fDumpFiles, fDumpFilesTwo, fDual, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "ftdvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "ftdvh") {
		switch c {
		case 'f':
			fDumpFiles ^= 1
			break
		case 't':
			fDumpFilesTwo ^= 1
			break
		case 'd':
			fDual ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Demiter(): There is no AIG.\n")
		return 0
	}
	if (fDumpFiles != 0) || fDumpFilesTwo {
		var pName0 [1000]byte = "miter_part0.aig"
		var pName1 [1000]byte = "miter_part1.aig"
		var pPart1, pPart2 *Gia_Man_t
		if Gia_ManPoNum(pAbc.pGia)%2 != 0 {
			Abc_Print(-1, "Abc_CommandAbc9Demiter(): Does not look like a dual-output miter.\n")
			return 0
		}
		if fDumpFilesTwo != 0 {
			Gia_ManDemiterTwoWords(pAbc.pGia, &pPart1, &pPart2)
		} else {
			Gia_ManDemiterDual(pAbc.pGia, &pPart1, &pPart2)
		}
		if pAbc.pGia.pSpec {
			var pGen string = Extra_FileNameGeneric(pAbc.pGia.pSpec)
			pName0 = fmt.Sprintf("%s_1.aig", pGen)
			pName1 = fmt.Sprintf("%s_2.aig", pGen)
			ABC_FREE(pGen)
		}
		Gia_AigerWrite(pPart1, pName0, 0, 0, 0)
		Gia_AigerWrite(pPart2, pName1, 0, 0, 0)
		Gia_ManStop(pPart1)
		Gia_ManStop(pPart2)
		if fDumpFilesTwo != 0 {
			printf("Two parts of the two-word miter are dumped into files \"%s\" and \"%s\".\n", pName0, pName1)
		} else {
			printf("Two parts of the dual-output miter are dumped into files \"%s\" and \"%s\".\n", pName0, pName1)
		}
		return 0
	}
	if Gia_ManPoNum(pAbc.pGia) != 1 {
		Abc_Print(-1, "Abc_CommandAbc9Demiter(): Miter should have one output.\n")
		return 0
	}
	if fDual != 0 {
		pTemp = Gia_ManDemiterToDual(pAbc.pGia)
	} else {
		pTemp = Gia_ManDupDemiter(pAbc.pGia, fVerbose)
	}
	Abc_FrameUpdateGia(pAbc, pTemp)
	if fVerbose != 0 {
		Gia_ManPrintStatsMiter(pTemp, 0)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &demiter [-ftdvh]\n")
	Abc_Print(-2, "\t         decomposes a miter (by default, tries to extract an OR gate)\n")
	Abc_Print(-2, "\t-f     : write files with two sides of a dual-output miter [default = %s]\n", abcSelect(fDumpFiles, "yes", "no"))
	Abc_Print(-2, "\t-t     : write files with two sides of a two-word miter [default = %s]\n", abcSelect(fDumpFilesTwo, "yes", "no"))
	Abc_Print(-2, "\t-d     : take single-output and decompose into dual-output [default = %s]\n", abcSelect(fDual, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Fadds(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp, pTemp2 *Gia_Man_t
	var c int32
	var nFaddMin int32 = 3
	var fUseNat int32
	var fUseArt int32
	var fVerbose int32
	var DelayC int32
	var nPathMin int32 = 3
	var nPathMax int32 = 32
	var nPathLimit int32 = 50
	var fUseFanout int32
	var fUseXorTrick int32
	var fIgnoreBoxDelays int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "NBSLPnafxbvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "NBSLPnafxbvh") {
		switch c {
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nFaddMin = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFaddMin < 0 {
				goto usage
			}
			break
		case 'B':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-B\" should be followed by an integer.\n")
				goto usage
			}
			DelayC = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if DelayC < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			nPathMin = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPathMin < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			nPathMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPathMax < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nPathLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nPathLimit < 0 {
				goto usage
			}
			break
		case 'n':
			fUseNat ^= 1
			break
		case 'a':
			fUseArt ^= 1
			break
		case 'f':
			fUseFanout ^= 1
			break
		case 'x':
			fUseXorTrick ^= 1
			break
		case 'b':
			fIgnoreBoxDelays ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Fadds(): There is no AIG.\n")
		return 0
	}
	if fUseNat != 0 {
		pTemp = Gia_ManDupWithNaturalBoxes(pAbc.pGia, nFaddMin, fVerbose)
	} else {
		pTemp = Gia_ManDup(pAbc.pGia)
		Gia_ManTransferTiming(pTemp, pAbc.pGia)
	}
	if fUseArt != 0 {
		pTemp2 = Gia_ManDupWithArtificialBoxes(pTemp, DelayC, nPathMin, nPathMax, nPathLimit, fUseFanout, fUseXorTrick, fIgnoreBoxDelays, fVerbose)
	} else {
		pTemp2 = Gia_ManDup(pTemp)
		Gia_ManTransferTiming(pTemp2, pTemp)
	}
	Gia_ManStop(pTemp)
	Abc_FrameUpdateGia(pAbc, pTemp2)
	return 0
usage:
	Abc_Print(-2, "usage: &fadds [-NBSLP num] [-nafxvh]\n")
	Abc_Print(-2, "\t         detects full-adder chains and puts them into white boxes\n")
	Abc_Print(-2, "\t-n     : toggles detecting natural full-adder chains [default = %s]\n", abcSelect(fUseNat, "yes", "no"))
	Abc_Print(-2, "\t-N num : minimum length of a natural full-adder chain to detect [default = %d]\n", nFaddMin)
	Abc_Print(-2, "\t-a     : toggles detecting artificial full-adder chains [default = %s]\n", abcSelect(fUseArt, "yes", "no"))
	Abc_Print(-2, "\t-B num : full-adder box delay (percentage of AND-gate delay) [default = %d]\n", DelayC)
	Abc_Print(-2, "\t-S num : minimum length of an artificial full-adder chain [default = %d]\n", nPathMin)
	Abc_Print(-2, "\t-L num : maximum length of an artificial full-adder chain [default = %d]\n", nPathMax)
	Abc_Print(-2, "\t-P num : maximum number of artificial full-adder chains to detect [default = %d]\n", nPathLimit)
	Abc_Print(-2, "\t-f     : toggles allowing external fanouts in artificial chains [default = %s]\n", abcSelect(fUseFanout, "yes", "no"))
	Abc_Print(-2, "\t-x     : toggles using XOR to generate fanouts in artificial chains [default = %s]\n", abcSelect(fUseXorTrick, "yes", "no"))
	Abc_Print(-2, "\t-b     : toggles ignoring boxes when computing delays [default = %s]\n", abcSelect(fIgnoreBoxDelays, "yes", "no"))
	Abc_Print(-2, "\t-v     : toggles printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h     : print the command usage\n")
	return 1
}

