/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Exorcism(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var vEsop *Vec_Wec_t = nil
	var pNtk *Abc_Ntk_t = nil
	var pFileNameIn string
	var pFileNameOut string
	var c int32
	var Quality int32 = 2
	var Verbosity int32
	var nCubesMax int32 = 20000
	var fUseQCost int32
	var fVerbose int32
	var nInputs int32 = -1
	var nOutputs int32 = -1

	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "QVCqvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "QVCqvh") {
		switch c {
		case 'Q':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-Q\" should be followed by an integer.\n")
				goto usage
			}
			Quality = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Quality < 0 {
				goto usage
			}
			break
		case 'V':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-V\" should be followed by an integer.\n")
				goto usage
			}
			Verbosity = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Verbosity < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			nCubesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nCubesMax < 0 {
				goto usage
			}
			break
		case 'q':
			fUseQCost ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}

	if argc == globalUtilOptind+2 {
		pFileNameIn = argv[globalUtilOptind]
		pFileNameOut = argv[globalUtilOptind+1]

	} else if argc == globalUtilOptind+1 {
		pFileNameOut = argv[globalUtilOptind]

	} else {
		Abc_Print(-1, "Abc_CommandAbc9Exorcism(): Argument error.\n")
		goto usage
	}

	if pAbc.pGia == nil && pFileNameIn == nil {
		Abc_Print(-1, "Abc_CommandAbc9Exorcism(): There is neither an AIG nor an ESOP-PLA file.\n")
		return 0
	}

	if pFileNameIn != "" {
		pNtk = Io_ReadPla(pFileNameIn, 0, 0, 0 /* no preprocessing = */, 1 /* check = */, 1)
		if pNtk == nil {
			fmt.Printf("Reading PLA file has failed.\n")
			return 1
		}
		nInputs = Abc_NtkCiNum(pNtk)
		nOutputs = Abc_NtkCoNum(pNtk)
		vEsop = Abc_ExorcismNtk2Esop(pNtk)
		if vEsop == nil {
			fmt.Printf("Converting PLA to ESOP failed.\n")
			return 1
		}

	} else if pAbc.pGia {
		// generate starting cover
		nInputs = Gia_ManCiNum(pAbc.pGia)
		nOutputs = Gia_ManCoNum(pAbc.pGia)
		Eso_ManCompute(pAbc.pGia, fVerbose, &vEsop)
	}

	if vEsop != nil {
		// run minimization
		Abc_ExorcismMain(vEsop, nInputs, nOutputs, pFileNameOut, Quality, Verbosity, nCubesMax, fUseQCost)
		Vec_WecFree(vEsop)
	}
	return 0

usage:
	Abc_Print(-2, "usage: &exorcism [-Q N] [-V N] [-C N] -q [file_in] <file_out>\n")
	Abc_Print(-2, "                     performs heuristic exclusive sum-of-project minimization\n")
	Abc_Print(-2, "        -Q N       : minimization quality [default = %d]\n", Quality)
	Abc_Print(-2, "                     increasing this number improves quality and adds to runtime\n")
	Abc_Print(-2, "        -V N       : verbosity level [default = %d]\n", Verbosity)
	Abc_Print(-2, "                     0 = no output; 1 = outline; 2 = verbose\n")
	Abc_Print(-2, "        -C N       : maximum number of cubes in startign cover [default = %d]\n", nCubesMax)
	Abc_Print(-2, "        -q         : toggle using quantum cost [default = %s]\n", abcSelect(fUseQCost, "yes", "no"))
	Abc_Print(-2, "        [file_in]  : optional input file in ESOP-PLA format (otherwise current AIG is used)\n")
	Abc_Print(-2, "        <file_out> : output file in ESOP-PLA format\n")
	Abc_Print(-2, "\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Mfs(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var c int32
	var Pars Sfm_Par_t
	var pPars *Sfm_Par_t = &Pars
	Sfm_ParSetDefault(pPars)
	pPars.nTfoLevMax = 5
	pPars.nDepthMax = 100
	pPars.nWinSizeMax = 2000
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "WFDMLCNdaeblvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "WFDMLCNdaeblvwh") {
		switch c {
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nTfoLevMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nTfoLevMax < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nFanoutMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nFanoutMax < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nDepthMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nDepthMax < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nWinSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nWinSizeMax < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nGrowthLevel = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nGrowthLevel < 0 || pPars.nGrowthLevel > ABC_INFINITY {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nBTLimit < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nNodesMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nNodesMax < 0 {
				goto usage
			}
			break
		case 'd':
			pPars.fRrOnly ^= 1
			break
		case 'a':
			pPars.fArea ^= 1
			break
		case 'e':
			pPars.fMoreEffort ^= 1
			break
		case 'b':
			pPars.fAllBoxes ^= 1
			break
		case 'l':
			pPars.fUseDcs ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		case 'w':
			pPars.fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Mfs(): There is no AIG.\n")
		return 0
	}
	if Gia_ManBufNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Mfs(): This command does not work with barrier buffers.\n")
		return 1
	}
	if !Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Mfs(): The current AIG has no mapping.\n")
		return 0
	}
	if Gia_ManLutSizeMax(pAbc.pGia) > 15 {
		Abc_Print(-1, "Abc_CommandAbc9Mfs(): The current mapping has nodes with more than 15 inputs. Cannot use \"mfs\".\n")
		return 0
	}
	/*
	   if ( pAbc->pGia->pAigExtra && Gia_ManPiNum(pAbc->pGia->pAigExtra) > 6 )
	   {
	       Abc_Print( -1, "Abc_CommandAbc9Mfs(): The current white-boxes have more than 6 inputs. Cannot use \"mfs\".\n" );
	       return 0;
	   }
	*/
	pTemp = Gia_ManPerformMfs(pAbc.pGia, pPars)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &mfs [-WFDMLCN <num>] [-daeblvwh]\n")
	Abc_Print(-2, "\t           performs don't-care-based optimization of logic networks\n")
	Abc_Print(-2, "\t-W <num> : the number of levels in the TFO cone (0 <= num) [default = %d]\n", pPars.nTfoLevMax)
	Abc_Print(-2, "\t-F <num> : the max number of fanouts to skip (1 <= num) [default = %d]\n", pPars.nFanoutMax)
	Abc_Print(-2, "\t-D <num> : the max depth nodes to try (0 = no limit) [default = %d]\n", pPars.nDepthMax)
	Abc_Print(-2, "\t-M <num> : the max node count of windows to consider (0 = no limit) [default = %d]\n", pPars.nWinSizeMax)
	Abc_Print(-2, "\t-L <num> : the max increase in node level after resynthesis (0 <= num) [default = %d]\n", pPars.nGrowthLevel)
	Abc_Print(-2, "\t-C <num> : the max number of conflicts in one SAT run (0 = no limit) [default = %d]\n", pPars.nBTLimit)
	Abc_Print(-2, "\t-N <num> : the max number of nodes to try (0 = all) [default = %d]\n", pPars.nNodesMax)
	Abc_Print(-2, "\t-d       : toggle performing redundancy removal [default = %s]\n", abcSelect(fRrOnly, "yes", "no"))
	Abc_Print(-2, "\t-a       : toggle minimizing area or area+edges [default = %s]\n", abcSelect(fArea, "area", "area+edges"))
	Abc_Print(-2, "\t-e       : toggle high-effort resubstitution [default = %s]\n", abcSelect(fMoreEffort, "yes", "no"))
	Abc_Print(-2, "\t-b       : toggle preserving all white boxes [default = %s]\n", abcSelect(fAllBoxes, "yes", "no"))
	Abc_Print(-2, "\t-l       : toggle deriving don't-cares [default = %s]\n", abcSelect(fUseDcs, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle printing optimization summary [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggle printing detailed stats for each node [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Mfsd(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var c int32
	var Pars Sbd_Par_t
	var pPars *Sbd_Par_t = &Pars
	Sbd_ParSetDefault(pPars)
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "KSNPWFMCmcdpvwh"); c != -1; c = Extra_UtilGetopt(argc, argv, "KSNPWFMCmcdpvwh") {
		switch c {
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nLutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nLutSize < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nLutNum = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nLutNum < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nCutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nCutSize < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nCutNum = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nCutNum < 0 {
				goto usage
			}
			break
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nTfoLevels = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nTfoLevels < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nTfoFanMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nTfoFanMax < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nWinSizeMax = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nWinSizeMax < 0 {
				goto usage
			}
			break
		case 'C':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-C\" should be followed by an integer.\n")
				goto usage
			}
			pPars.nBTLimit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if pPars.nBTLimit < 0 {
				goto usage
			}
			break
		case 'm':
			pPars.fMapping ^= 1
			break
		case 'c':
			pPars.fMoreCuts ^= 1
			break
		case 'd':
			pPars.fFindDivs ^= 1
			break
		case 'p':
			pPars.fUsePath ^= 1
			break
		case 'v':
			pPars.fVerbose ^= 1
			break
		case 'w':
			pPars.fVeryVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Mfsd(): There is no AIG.\n")
		return 0
	}
	if Gia_ManBufNum(pAbc.pGia) {
		Abc_Print(-1, "Abc_CommandAbc9Mfsd(): This command does not work with barrier buffers.\n")
		return 1
	}
	if Gia_ManHasMapping(pAbc.pGia) {
		Abc_Print(1, "The current AIG has mapping, which can be used to determine critical path if \"-p\" is selected.\n")
	}
	pTemp = Sbd_NtkPerform(pAbc.pGia, pPars)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &mfsd [-KSNPWFMC <num>] [-mcdpvwh]\n")
	Abc_Print(-2, "\t           performs SAT-based delay-oriented AIG optimization\n")
	Abc_Print(-2, "\t-K <num> : the LUT size for delay minimization (2 <= num <= 6) [default = %d]\n", pPars.nLutSize)
	Abc_Print(-2, "\t-S <num> : the LUT structure size (1 <= num <= 2) [default = %d]\n", pPars.nLutNum)
	Abc_Print(-2, "\t-N <num> : the cut size considered for optimization (2 <= num <= 10) [default = %d]\n", pPars.nCutSize)
	Abc_Print(-2, "\t-P <num> : the number of cuts computed at a node (1 <= num <= 500) [default = %d]\n", pPars.nCutNum)
	Abc_Print(-2, "\t-W <num> : the number of levels in the TFO cone (0 <= num) [default = %d]\n", pPars.nTfoLevels)
	Abc_Print(-2, "\t-F <num> : the max number of fanouts to skip (1 <= num) [default = %d]\n", pPars.nTfoFanMax)
	Abc_Print(-2, "\t-M <num> : the max node count of windows to consider (0 = no limit) [default = %d]\n", pPars.nWinSizeMax)
	Abc_Print(-2, "\t-C <num> : the max number of conflicts in one SAT run (0 = no limit) [default = %d]\n", pPars.nBTLimit)
	Abc_Print(-2, "\t-m       : toggle generating delay-oriented mapping [default = %s]\n", abcSelect(fMapping, "yes", "no"))
	Abc_Print(-2, "\t-c       : toggle using several cuts at each node [default = %s]\n", abcSelect(fMoreCuts, "yes", "no"))
	Abc_Print(-2, "\t-d       : toggle additional search for good divisors [default = %s]\n", abcSelect(fFindDivs, "yes", "no"))
	Abc_Print(-2, "\t-p       : toggle optimizing critical path only [default = %s]\n", abcSelect(fUsePath, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle printing optimization summary [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-w       : toggle printing detailed stats for each node [default = %s]\n", abcSelect(fVeryVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9DeepSyn(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t
	var c int32
	var nIters int32 = 1
	var nNoImpr int32 = ABC_INFINITY
	var TimeOut int32
	var nAnds int32
	var Seed int32
	var fUseTwo int32
	var fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "IJTAStvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "IJTAStvh") {
		switch c {
		case 'I':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-I\" should be followed by an integer.\n")
				goto usage
			}
			nIters = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nIters < 0 {
				goto usage
			}
			break
		case 'J':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-J\" should be followed by an integer.\n")
				goto usage
			}
			nNoImpr = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nNoImpr < 0 {
				goto usage
			}
			break
		case 'T':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-T\" should be followed by an integer.\n")
				goto usage
			}
			TimeOut = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if TimeOut < 0 {
				goto usage
			}
			break
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by an integer.\n")
				goto usage
			}
			nAnds = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nAnds < 0 {
				goto usage
			}
			break
		case 'S':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-S\" should be followed by an integer.\n")
				goto usage
			}
			Seed = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Seed < 0 {
				goto usage
			}
			break
		case 't':
			fUseTwo ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9DeepSyn(): There is no AIG.\n")
		return 0
	}
	pTemp = Gia_ManDeepSyn(pAbc.pGia, nIters, nNoImpr, TimeOut, nAnds, Seed, fUseTwo, fVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &deepsyn [-IJTAS <num>] [-tvh]\n")
	Abc_Print(-2, "\t           performs synthesis\n")
	Abc_Print(-2, "\t-I <num> : the number of iterations [default = %d]\n", nIters)
	Abc_Print(-2, "\t-J <num> : the number of steps without improvements [default = %d]\n", nNoImpr)
	Abc_Print(-2, "\t-T <num> : the timeout in seconds (0 = no timeout) [default = %d]\n", TimeOut)
	Abc_Print(-2, "\t-A <num> : the number of nodes to stop (0 = no limit) [default = %d]\n", nAnds)
	Abc_Print(-2, "\t-S <num> : user-specified random seed (0 <= num <= 100) [default = %d]\n", Seed)
	Abc_Print(-2, "\t-t       : toggle using two-input LUTs [default = %s]\n", abcSelect(fUseTwo, "yes", "no"))
	Abc_Print(-2, "\t-v       : toggle printing optimization summary [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h       : print the command usage\n")
	return 1
}

