/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Gen(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var pTemp *Gia_Man_t = nil
	var Algo int32
	var LutSize int32 = 6
	var nLuts int32 = 256
	var nLevels int32 = 8
	var Limit int32
	var nBestTries int32 = 1
	var Multi int32
	var fXor int32 = 1
	var c, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "AKNDLBMxvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "AKNDLBMxvh") {
		switch c {
		case 'A':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-A\" should be followed by an integer.\n")
				goto usage
			}
			Algo = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Algo < 0 {
				goto usage
			}
			break
		case 'K':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-K\" should be followed by an integer.\n")
				goto usage
			}
			LutSize = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if LutSize < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			nLuts = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLuts < 0 {
				goto usage
			}
			break
		case 'D':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-D\" should be followed by an integer.\n")
				goto usage
			}
			nLevels = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nLevels < 0 {
				goto usage
			}
			break
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			Limit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Limit < 0 {
				goto usage
			}
			break
		case 'B':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-B\" should be followed by an integer.\n")
				goto usage
			}
			nBestTries = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nBestTries < 0 {
				goto usage
			}
			break
		case 'M':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-M\" should be followed by an integer.\n")
				goto usage
			}
			Multi = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Multi < 0 {
				goto usage
			}
			break
		case 'x':
			fXor ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	pTemp = Extra_CommandGen(Algo, LutSize, nLuts, nLevels, Limit, nBestTries, Multi, fXor, fVerbose)
	Abc_FrameUpdateGia(pAbc, pTemp)
	return 0

usage:
	Abc_Print(-2, "usage: &gen [-AKNDLBMxvh]\n")
	Abc_Print(-2, "\t          generates network\n")
	Abc_Print(-2, "\t-A num  : the generation algorithm [default = %d]\n", Algo)
	Abc_Print(-2, "\t-K num  : the number of LUT inputs [default = %d]\n", LutSize)
	Abc_Print(-2, "\t-N num  : the number of LUTs on one level [default = %d]\n", nLuts)
	Abc_Print(-2, "\t-D num  : the number of LUT levels [default = %d]\n", nLevels)
	Abc_Print(-2, "\t-L num  : limit below which we randomize [default = %d]\n", Limit)
	Abc_Print(-2, "\t-B num  : select best fanins among this many tries [default = %d]\n", nBestTries)
	Abc_Print(-2, "\t-M num  : the multiplier type (1=array, 2=booth) [default = %d]\n", Multi)
	Abc_Print(-2, "\t-x      : toggle using XOR gates [default = %s]\n", abcSelect(fXor, "yes", "no"))
	Abc_Print(-2, "\t-v      : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Cfs(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var Limit int32
	var Reps int32 = 1
	var UnseenUse int32 = 2
	var RareUse int32 = 2
	var fReplaceRare int32
	var fConstSim int32
	var fDagNodes int32
	var FlipProb float32
	var c, fVerbose int32
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "LNURPrcdvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "LNURPrcdvh") {
		switch c {
		case 'L':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-L\" should be followed by an integer.\n")
				goto usage
			}
			Limit = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Limit < 0 {
				goto usage
			}
			break
		case 'N':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-N\" should be followed by an integer.\n")
				goto usage
			}
			Reps = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if Reps < 0 {
				goto usage
			}
			break
		case 'U':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-U\" should be followed by an integer.\n")
				goto usage
			}
			UnseenUse = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if UnseenUse < 0 {
				goto usage
			}
			break
		case 'R':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-R\" should be followed by an integer.\n")
				goto usage
			}
			RareUse = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if RareUse < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			FlipProb = atof(argv[globalUtilOptind])
			globalUtilOptind++
			if FlipProb < 0 {
				goto usage
			}
			break
		case 'r':
			fReplaceRare ^= 1
			break
		case 'c':
			fConstSim ^= 1
			break
		case 'd':
			fDagNodes ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	if pAbc.pGia == nil {
		Abc_Print(-1, "Abc_CommandAbc9Cfs(): There is no AIG.\n")
		return 1
	}
	Extra_CommandCfs(pAbc.pGia, Limit, Reps, UnseenUse, RareUse, fReplaceRare, fConstSim, fDagNodes, FlipProb, fVerbose)
	return 0

usage:
	Abc_Print(-2, "usage: &cfs [-LNURPrcdvh]\n")
	Abc_Print(-2, "\t          performs simulation\n")
	Abc_Print(-2, "\t-L num  : the limit on the number of occurrences [default = %d]\n", Limit)
	Abc_Print(-2, "\t-N num  : the number of repetions of each pattern [default = %d]\n", Reps)
	Abc_Print(-2, "\t-U num  : what to do with unseen patterns [default = %d]\n", UnseenUse)
	Abc_Print(-2, "\t-R num  : what to do with rare patterns [default = %d]\n", RareUse)
	Abc_Print(-2, "\t-P num  : base2-log of ramdom flip probability [default = %f]\n", FlipProb)
	Abc_Print(-2, "\t-r      : toggle replacing rare patterns [default = %s]\n", abcSelect(fReplaceRare, "yes", "no"))
	Abc_Print(-2, "\t-c      : toggle inserting constants [default = %s]\n", abcSelect(fConstSim, "yes", "no"))
	Abc_Print(-2, "\t-d      : toggle using only DAG nodes [default = %s]\n", abcSelect(fDagNodes, "yes", "no"))
	Abc_Print(-2, "\t-v      : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h      : print the command usage\n")
	return 1
}

/*
*Function*************************************************************

	Synopsis    []

	Description []

	SideEffects []

	SeeAlso     []

**********************************************************************
*/
func Abc_CommandAbc9Test(pAbc *Abc_Frame_t, argc int32, argv []string) int32 {

	var c, fVerbose int32
	var nFrames int32 = 5
	var fSwitch int32
	var nWords int32 = 1000
	var nProcs int32 = 2
	Extra_UtilGetoptReset()
	for c = Extra_UtilGetopt(argc, argv, "WPFsvh"); c != -1; c = Extra_UtilGetopt(argc, argv, "WPFsvh") {
		switch c {
		case 'W':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-W\" should be followed by an integer.\n")
				goto usage
			}
			nWords = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nWords < 0 {
				goto usage
			}
			break
		case 'P':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-P\" should be followed by an integer.\n")
				goto usage
			}
			nProcs = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nProcs < 0 {
				goto usage
			}
			break
		case 'F':
			if globalUtilOptind >= argc {
				Abc_Print(-1, "Command line switch \"-F\" should be followed by an integer.\n")
				goto usage
			}
			nFrames = abcAtoi(argv[globalUtilOptind])
			globalUtilOptind++
			if nFrames < 0 {
				goto usage
			}
			break
		case 's':
			fSwitch ^= 1
			break
		case 'v':
			fVerbose ^= 1
			break
		case 'h':
			goto usage
		default:
			goto usage
		}
	}
	//    if ( pAbc->pGia == NULL )
	//    {
	//        Abc_Print( -1, "Abc_CommandAbc9Test(): There is no AIG.\n" );
	//        return 1;
	//    }
	//    Abc_FrameUpdateGia( pAbc, Abc_Procedure(pAbc->pGia) );
	//    Gia_ManTryResub( pAbc->pGia );
	Gia_RsbEnumerateWindows(pAbc.pGia, 6, 5)
	return 0
usage:
	Abc_Print(-2, "usage: &test [-FW num] [-svh]\n")
	Abc_Print(-2, "\t        testing various procedures\n")
	Abc_Print(-2, "\t-F num: the number of timeframes [default = %d]\n", nFrames)
	Abc_Print(-2, "\t-W num: the number of machine words [default = %d]\n", nWords)
	Abc_Print(-2, "\t-s    : toggle enable (yes) vs. disable (no) [default = %s]\n", abcSelect(fSwitch, "yes", "no"))
	Abc_Print(-2, "\t-v    : toggle printing verbose information [default = %s]\n", abcSelect(fVerbose, "yes", "no"))
	Abc_Print(-2, "\t-h    : print the command usage\n")
	return 1
}

